// ── §สีประจำรถ · vehicle identity colour ────────────────────────────────────────
// Until now the van-job list coloured each row by its POSITION (PAL[i%6]), so a van's colour
// changed from day to day depending on who else was dispatched. A colour is only useful to a
// dispatcher if it is the SAME colour every day, so it now lives on the vehicle: v.color.
// (The DB needs a matching sb_vehicles.color column or the value is silently dropped on sync.)
const VEH_COLORS = [
  // เขียว          น้ำเงิน-ฟ้า          ม่วง                ชมพู-แดง            ส้ม-เหลือง          กลาง
  '#13B96A','#0E9C7F','#0E7490','#19A7C9','#1577B0','#1E4E8C','#3B7BE0','#5B8DEF',
  '#7C5CE0','#8B5CF6','#6D3BE0','#A855C7','#C2469B','#F25CA2','#E0457F','#C42B4B',
  '#DC5B4B','#E0792B','#F2A33C','#D4A017','#B45309','#8A5A2B','#6B4A2F','#4E5D3A',
  '#2E7D5B','#16794E','#0F5F73','#334E68','#64748B','#4B5563','#5A5F7A','#7A4A6B'
];
function vjShade(hex, pct){                        // pct<0 = darker
  const m=/^#?([0-9a-f]{6})$/i.exec(String(hex||'')); if(!m) return hex||'#64748B';
  const num=parseInt(m[1],16); const f=(100+(pct||0))/100;
  const cl=x=>Math.max(0,Math.min(255,Math.round(x*f)));
  const r=cl((num>>16)&255), g=cl((num>>8)&255), b=cl(num&255);
  return '#'+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);
}
function vehColor(vid){
  const v=(typeof vehGet==='function'?vehGet(vid):null)||{};
  if(v.color && /^#[0-9a-fA-F]{6}$/.test(v.color)) return v.color;
  const s=String(vid||''); let acc=0; for(let i=0;i<s.length;i++) acc=(acc*31+s.charCodeAt(i))>>>0;
  return VEH_COLORS[acc % VEH_COLORS.length];      // stable per-vehicle fallback, never position-based
}
function vehGrad(vid){ const c=vehColor(vid); return [c, vjShade(c,-22)]; }
function vjTint(hex, pct){                          // pct 0..1 = ผสมกับสีขาว
  const m=/^#?([0-9a-f]{6})$/i.exec(String(hex||'')); if(!m) return '#EFEDE6';
  const num=parseInt(m[1],16); const mix=x=>Math.round(x+(255-x)*pct);
  const r=mix((num>>16)&255), g=mix((num>>8)&255), b=mix(num&255);
  return '#'+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1);
}
// [พื้นอ่อน, ตัวหนังสือเข้ม] — รูปแบบเดียวกับ PAL_BOAT เดิม จึงเสียบแทนได้ตรงๆ
function vehChipPair(vid){ const c=vehColor(vid); return [vjTint(c,.87), vjShade(c,-30)]; }
function vehSetColor(vid, hex){
  const v=(typeof vehGet==='function'?vehGet(vid):null); if(!v) return;
  if(hex) v.color=hex; else delete v.color;        // no hex = back to the automatic colour
  if(typeof vehLog==='function') vehLog(vid,'edit','เปลี่ยนสีประจำรถ → '+(hex||'อัตโนมัติ'));
  if(typeof sbVehiclesPersist==='function') sbVehiclesPersist();
  vehColorClose();
  if(typeof renderVanJobs==='function' && document.getElementById('vanjobs-host')) renderVanJobs();
  if(typeof renderVehicles==='function' && document.getElementById('vehicles-host')) renderVehicles();
}
// ลากใน color picker แล้วเห็นผลทันที (ไม่ปิด popup · ไม่ยิง log ทุก pixel)
function vehSetColorLive(vid, hex){
  const v=(typeof vehGet==='function'?vehGet(vid):null); if(!v) return;
  if(!/^#[0-9a-fA-F]{6}$/.test(hex||'')) return;
  v.color=String(hex).toLowerCase();
  if(typeof sbVehiclesPersist==='function') sbVehiclesPersist();
  if(typeof renderVanJobs==='function' && document.getElementById('vanjobs-host')) renderVanJobs();
  if(typeof renderVehicles==='function' && document.getElementById('vehicles-host')) renderVehicles();
}
function vehColorClose(){ const p=document.getElementById('veh-color-pop'); if(p) p.remove(); }
function vehColorPick(vid, ev){ if(typeof window.laGuardEdit==='function' && !window.laGuardEdit('operations')) return;   /* §edit-guard · VC view-only → no color change */
  if(ev){ ev.stopPropagation(); ev.preventDefault(); }
  vehColorClose();
  const v=(typeof vehGet==='function'?vehGet(vid):null)||{};
  const cur=vehColor(vid), custom=!!v.color;
  const r=(ev&&ev.currentTarget&&ev.currentTarget.getBoundingClientRect)?ev.currentTarget.getBoundingClientRect():{left:80,bottom:80};
  const pop=document.createElement('div'); pop.id='veh-color-pop';
  pop.style.cssText='position:fixed;z-index:9999;background:#fff;border:1px solid rgba(0,0,0,.10);border-radius:12px;'
    +'box-shadow:0 14px 40px -10px rgba(0,0,0,.30);padding:12px;width:236px;'
    +'left:'+Math.max(8, Math.min(window.innerWidth-248, r.left))+'px;top:'+Math.max(8, Math.min(window.innerHeight-300, r.bottom+8))+'px';
  pop.onclick=e=>e.stopPropagation();
  pop.innerHTML='<div style="font-size:11px;font-weight:700;color:#6b7280;letter-spacing:.04em;text-transform:uppercase;margin-bottom:9px">'
      +'สีประจำ '+String(v.name||vid).replace(/</g,'&lt;')+'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(8,1fr);gap:6px">'
    + VEH_COLORS.map(c=>'<button onclick="vehSetColor(\''+vid+'\',\''+c+'\')" title="'+c+'" style="width:22px;height:22px;border-radius:6px;'
        +'background:'+c+';border:2px solid '+(custom&&cur.toLowerCase()===c.toLowerCase()?'#111':'transparent')+';cursor:pointer;padding:0"></button>').join('')
    +'</div>'
    +'<div style="display:flex;align-items:center;gap:7px;margin-top:10px">'
      +'<input type="color" value="'+cur+'" oninput="vehSetColorLive(\''+vid+'\',this.value)" title="เลือกสีเองได้ไม่จำกัด" style="width:36px;height:32px;flex:none;padding:2px;border:1px solid #e5e7eb;border-radius:7px;background:#fff;cursor:pointer">'
      +'<span style="font-size:10.5px;color:#9ca3af">เลือกสีเองได้ไม่จำกัด &#8594;</span>'
    +'</div>'
    +'<button onclick="vehSetColor(\''+vid+'\',\'\')" style="margin-top:8px;width:100%;background:#fff;border:1px solid #e5e7eb;border-radius:8px;'
      +'padding:6px;font-size:11.5px;font-weight:600;color:#6b7280;cursor:pointer;font-family:inherit">'
      +(custom?'ล้างสี · กลับเป็นอัตโนมัติ':'ใช้สีอัตโนมัติอยู่')+'</button>';
  document.body.appendChild(pop);
  setTimeout(()=>document.addEventListener('click', vehColorClose, {once:true}), 0);
}
function vehGet(id){ return (SB_VEHICLES||[]).find(v=>v.id===id); }
function vehName(id){ const v=vehGet(id); return v?(v.name+(v.plate&&v.plate!=='-'?(' · '+v.plate):'')):'—'; }
function staffGet(id){ return (SB_STAFF||[]).find(s=>s.id===id); }
function staffQuota(id, year){ const s=staffGet(id); return (s && s.quota && s.quota[String(year)]) || 0; }
// welfare FREE seats (FOC pax) used by a staff in a given year · paid over-quota pax (adult) do NOT count
function staffWelfareUsed(staffId, year){
  let n=0; (typeof SB_BOOKINGS!=='undefined'?SB_BOOKINGS:[]).forEach(b=>{
    if(b.staffId!==staffId) return;
    if(b.staffPurpose==='inspection' || b.purpose==='staff_inspection') return;   // inspection trips don't consume welfare quota
    if(['cancelled','rejected','cancelled_weather'].includes(b.status)) return;
    (b.trips||[]).forEach(t=>{ if((t.date||'').slice(0,4)===String(year)) n += (typeof bkV2PaxTot==='function'?bkV2PaxTot(t.pax||{},'foc'):0); });
  });
  return n;
}
function staffRemaining(id, year){ return staffQuota(id,year) - staffWelfareUsed(id,year); }
let _staffYear = new Date().getFullYear();
let _staffTab = 'roster';   // 'roster' | 'trips'
function staffSetTab(t){ _staffTab = t; renderStaff(); }
function staffSetYear(delta){ _staffYear += delta; renderStaff(); }
// Collect this-year staff trips (welfare + inspection) as flat rows: {bk, staff, t, route, purpose, foc, paid, head}
function staffTripsFor(year){
  const out=[]; (typeof SB_BOOKINGS!=='undefined'?SB_BOOKINGS:[]).forEach(b=>{
    const isStaffBk = b.staffId || b.purpose==='staff_welfare' || b.purpose==='staff_inspection';
    if(!isStaffBk) return;
    if(['cancelled','rejected','cancelled_weather'].includes(b.status)) return;
    const purpose = (b.staffPurpose==='inspection'||b.purpose==='staff_inspection') ? 'inspection' : 'welfare';
    (b.trips||[]).forEach(t=>{
      if((t.date||'').slice(0,4)!==String(year)) return;
      const foc = (typeof bkV2PaxTot==='function'?bkV2PaxTot(t.pax||{},'foc'):0);
      const head = (typeof bkV2PaxAllTot==='function'?bkV2PaxAllTot(t.pax||{}):0);
      out.push({ bk:b, staff:staffGet(b.staffId), t, route:(getRoute(t.routeId)||null), purpose, foc, head, paid:Math.max(0,head-foc) });
    });
  });
  out.sort((a,b)=>(a.t.date||'').localeCompare(b.t.date||''));
  return out;
}
function staffTripsReport(yr){
  const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const trips=staffTripsFor(yr);
  if(!trips.length) return `<div style="background:#fff;border:1px dashed rgba(0,0,0,.15);border-radius:12px;padding:40px;text-align:center;color:#8a8a82;font-size:13px">ยังไม่มีทริปพนักงานในปี ${yr} · สร้างใบจองด้วย agent "Staff / Welfare" แล้วเลือก Purpose</div>`;
  const wFoc=trips.filter(x=>x.purpose==='welfare').reduce((a,x)=>a+x.foc,0);
  const wPaid=trips.filter(x=>x.purpose==='welfare').reduce((a,x)=>a+x.paid,0);
  const insHead=trips.filter(x=>x.purpose==='inspection').reduce((a,x)=>a+x.head,0);
  const insTrips=trips.filter(x=>x.purpose==='inspection').length;
  const wTrips=trips.filter(x=>x.purpose==='welfare').length;
  const kpi=(lab,val,col,sub)=>`<div style="background:#fff;border:1px solid rgba(0,0,0,.08);border-radius:10px;padding:12px 15px;min-width:130px"><div style="font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#8a8a82">${lab}</div><div style="font-size:23px;font-weight:700;color:${col||'#1B2A55'};font-family:'DM Mono',monospace;margin-top:3px">${val}</div>${sub?`<div style="font-size:10px;color:#8a8a82;margin-top:2px">${sub}</div>`:''}</div>`;
  const badge=p=>p==='inspection'?`<span style="background:#EEE9FB;color:#6c5ce7;font-size:10px;font-weight:700;border-radius:6px;padding:2px 7px">ตรวจงาน</span>`:`<span style="background:#E7F2EC;color:#0F6E56;font-size:10px;font-weight:700;border-radius:6px;padding:2px 7px">สวัสดิการ</span>`;
  const th='padding:8px 10px;text-align:left;font-size:9.5px;color:#8a8a82;font-weight:700;letter-spacing:.06em;text-transform:uppercase;border-bottom:1px solid rgba(0,0,0,.08)';
  const td='padding:7px 10px;font-size:12px;border-bottom:0.5px solid rgba(0,0,0,.05)';
  const tdc=td+';text-align:center;font-family:\'DM Mono\',monospace';
  const rows=trips.map(x=>`<tr>
    <td style="${td};font-family:'DM Mono',monospace;color:#444">${esc(x.t.date)}</td>
    <td style="${td}">${esc(x.staff?(x.staff.name||x.staff.code):'—')}</td>
    <td style="${td}">${badge(x.purpose)}</td>
    <td style="${td}">${esc(x.route?x.route.name:x.t.routeId)}</td>
    <td style="${tdc};color:#0F6E56">${x.foc||''}</td>
    <td style="${tdc};color:#854F0B">${x.paid||''}</td>
    <td style="${tdc};font-weight:700">${x.head}</td>
    <td style="${td};font-size:10.5px;color:#8a8a82">${esc((x.bk.code||x.bk.id||''))}</td>
  </tr>`).join('');
  return `
    <div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap">
      ${kpi('Welfare · FOC seats', wFoc, '#0F6E56', wTrips+' trips')}
      ${kpi('Welfare · over-quota paid', wPaid, '#854F0B', 'charged seats')}
      ${kpi('Inspection · heads', insHead, '#6c5ce7', insTrips+' trips')}
      ${kpi('Total staff trips', trips.length, '#1B2A55')}
    </div>
    <div style="background:#fff;border:1px solid rgba(0,0,0,.08);border-radius:12px;overflow:hidden">
      <div style="padding:11px 14px;border-bottom:1px solid rgba(0,0,0,.06);background:#fafafa;font-size:13px;font-weight:700;color:#1B2A55">ทริปพนักงาน · ${yr}</div>
      <table style="width:100%;border-collapse:collapse">
        <thead><tr><th style="${th}">วันที่</th><th style="${th}">พนักงาน</th><th style="${th}">ประเภท</th><th style="${th}">เส้นทาง</th><th style="${th};text-align:center">ฟรี</th><th style="${th};text-align:center">จ่าย</th><th style="${th};text-align:center">รวมหัว</th><th style="${th}">Booking</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <div style="font-size:11px;color:#8a8a82;margin-top:12px">ฟรี = ที่นั่ง FOC (หักโควต้าสวัสดิการ) · จ่าย = ที่นั่งเกินโควต้า (คิดราคา) · ตรวจงานไม่หักโควต้า</div>`;
}
function staffAdd(){
  let _max=0; SB_STAFF.forEach(s=>{ const n=parseInt(String(s.id).replace(/^st/,''))||0; if(n>_max)_max=n; });
  const id='st'+String(_max+1).padStart(2,'0');
  SB_STAFF.push({id, code:'EMP-'+String(_max+1).padStart(3,'0'), name:'', dept:'', active:true, quota:{[String(_staffYear)]:3}});
  sbStaffPersist(); renderStaff();
}
function staffSetField(id, field, val){ const s=staffGet(id); if(!s) return; if(field==='active'){ s.active=!!val; } else { s[field]=val; } sbStaffPersist(); }
function staffSetQuota(id, year, val){ const s=staffGet(id); if(!s) return; if(!s.quota) s.quota={}; s.quota[String(year)]=Math.max(0, parseInt(val)||0); sbStaffPersist(); renderStaff(); }
function staffDelete(id){ const s=staffGet(id); if(!s) return; if(!confirm('Delete staff "'+(s.name||s.code||id)+'"?')) return; SB_STAFF=SB_STAFF.filter(x=>x.id!==id); sbStaffPersist(); renderStaff(); }
function renderStaff(){
  const host=document.getElementById('staff-host'); if(!host) return;
  const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const yr=_staffYear;
  const totStaff=SB_STAFF.filter(s=>s.active).length, totAll=SB_STAFF.length;
  const totQuota=SB_STAFF.reduce((a,s)=>a+staffQuota(s.id,yr),0);
  const totUsed=SB_STAFF.reduce((a,s)=>a+staffWelfareUsed(s.id,yr),0);
  const kpi=(lab,val,col)=>`<div style="background:#fff;border:1px solid rgba(0,0,0,.08);border-radius:10px;padding:12px 15px;min-width:120px"><div style="font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#8a8a82">${lab}</div><div style="font-size:23px;font-weight:700;color:${col||'#1B2A55'};font-family:'DM Mono',monospace;margin-top:3px">${val}</div></div>`;
  const th='padding:8px 10px;text-align:left;font-size:9.5px;color:#8a8a82;font-weight:700;letter-spacing:.06em;text-transform:uppercase;border-bottom:1px solid rgba(0,0,0,.08)';
  const rows=SB_STAFF.map(s=>{ const q=staffQuota(s.id,yr), u=staffWelfareUsed(s.id,yr), rem=q-u;
    return `<tr style="border-bottom:0.5px solid rgba(0,0,0,.05);${s.active?'':'opacity:.5'}">
      <td style="padding:6px 10px"><input value="${esc(s.code)}" oninput="staffSetField('${s.id}','code',this.value)" style="width:90px;border:1px solid var(--border,#e5e5e5);border-radius:6px;padding:5px 7px;font-family:'DM Mono',monospace;font-size:11px"></td>
      <td style="padding:6px 10px"><input value="${esc(s.name)}" oninput="staffSetField('${s.id}','name',this.value)" placeholder="ชื่อพนักงาน" style="width:160px;border:1px solid var(--border,#e5e5e5);border-radius:6px;padding:5px 7px;font-size:12px"></td>
      <td style="padding:6px 10px"><input value="${esc(s.dept)}" oninput="staffSetField('${s.id}','dept',this.value)" placeholder="แผนก" style="width:120px;border:1px solid var(--border,#e5e5e5);border-radius:6px;padding:5px 7px;font-size:12px"></td>
      <td style="padding:6px 10px;text-align:center"><input type="number" min="0" value="${q}" onchange="staffSetQuota('${s.id}',${yr},this.value)" style="width:60px;border:1px solid var(--border,#e5e5e5);border-radius:6px;padding:5px 7px;text-align:center;font-family:'DM Mono',monospace;font-size:13px;font-weight:700"></td>
      <td style="padding:6px 10px;text-align:center;font-family:'DM Mono',monospace;color:#854F0B">${u}</td>
      <td style="padding:6px 10px;text-align:center;font-family:'DM Mono',monospace;font-weight:700;color:${rem<0?'#A32D2D':'#0F6E56'}">${rem}</td>
      <td style="padding:6px 10px;text-align:center"><input type="checkbox" ${s.active?'checked':''} onchange="staffSetField('${s.id}','active',this.checked); renderStaff()"></td>
      <td style="padding:6px 10px;text-align:center"><button onclick="staffDelete('${s.id}')" style="background:transparent;border:1px solid #FCEBEB;color:#A32D2D;border-radius:7px;padding:4px 9px;font-size:10px;cursor:pointer">ลบ</button></td>
    </tr>`; }).join('');
  host.innerHTML = `
    <div style="padding:24px 28px;font-family:'DM Sans',sans-serif">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:4px">
        <h1 style="font-size:24px;font-weight:700;color:#1B2A55;margin:0">Staff &amp; Welfare</h1>
        <div style="display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid rgba(0,0,0,.1);border-radius:20px;padding:4px 6px;margin-left:auto">
          <button onclick="staffSetYear(-1)" style="border:none;background:transparent;cursor:pointer;font-size:15px;color:#666;padding:0 6px">&lsaquo;</button>
          <b style="font-family:'DM Mono',monospace;font-size:14px;color:#1B2A55">${yr}</b>
          <button onclick="staffSetYear(1)" style="border:none;background:transparent;cursor:pointer;font-size:15px;color:#666;padding:0 6px">&rsaquo;</button>
        </div>
      </div>
      <div style="font-size:12px;color:#8a8a82;margin-bottom:18px">ทะเบียนพนักงาน + โควต้าเที่ยวฟรี (สวัสดิการ) · นับเป็น <b>ที่นั่งต่อปี</b> · ปรับโควต้าได้ตามนโยบายแต่ละปี · พาครอบครัวได้ (หักตามจำนวนหัว)</div>
      <div style="display:inline-flex;gap:3px;background:#eef0f3;border-radius:10px;padding:3px;margin-bottom:16px">
        <button onclick="staffSetTab('roster')" style="border:none;border-radius:8px;padding:7px 16px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;${_staffTab!=='trips'?'background:#185FA5;color:#fff':'background:transparent;color:#666'}">ทะเบียน · Roster</button>
        <button onclick="staffSetTab('trips')" style="border:none;border-radius:8px;padding:7px 16px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;${_staffTab==='trips'?'background:#185FA5;color:#fff':'background:transparent;color:#666'}">ทริป · Trips report</button>
      </div>
      ${_staffTab==='trips' ? staffTripsReport(yr) : `
      <div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap">
        ${kpi('Active staff', totStaff+'<span style="font-size:13px;color:#8a8a82">/'+totAll+'</span>')}
        ${kpi('Quota seats · '+yr, totQuota, '#185FA5')}
        ${kpi('Used', totUsed, '#854F0B')}
        ${kpi('Remaining', (totQuota-totUsed), (totQuota-totUsed)<0?'#A32D2D':'#0F6E56')}
      </div>
      <div style="background:#fff;border:1px solid rgba(0,0,0,.08);border-radius:12px;overflow:hidden">
        <div style="display:flex;align-items:center;padding:11px 14px;border-bottom:1px solid rgba(0,0,0,.06);background:#fafafa">
          <span style="font-size:13px;font-weight:700;color:#1B2A55">รายชื่อพนักงาน</span>
          <button onclick="staffAdd()" style="margin-left:auto;background:#185FA5;color:#fff;border:none;border-radius:7px;padding:6px 13px;font-size:12px;font-weight:600;cursor:pointer">+ เพิ่มพนักงาน</button>
        </div>
        <table style="width:100%;border-collapse:collapse">
          <thead><tr><th style="${th}">Code</th><th style="${th}">ชื่อ</th><th style="${th}">แผนก</th><th style="${th};text-align:center">โควต้า ${yr}</th><th style="${th};text-align:center">ใช้ไป</th><th style="${th};text-align:center">เหลือ</th><th style="${th};text-align:center">Active</th><th style="${th};text-align:center"></th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
      <div style="font-size:11px;color:#8a8a82;margin-top:12px">โควต้า = ที่นั่งฟรีต่อปีต่อคน · "ใช้ไป" คำนวณจาก booking ที่เป็น staff welfare (ยังไม่มี = 0) · เปลี่ยนปีเพื่อตั้ง/ดูโควต้าแต่ละปี</div>
      `}
    </div>`;
}
function sbSalesPersist(){ if(typeof window.laCanEditArea==='function' && !window.laCanEditArea('sales')) return;   /* §edit-guard · ดูอย่างเดียว → ไม่ persist */  try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); d.sb_sales=SB_SALES; localStorage.setItem(LS_KEY, JSON.stringify(d)); }catch(e){ console.warn('persist sb_sales failed', e); } }

function sbGetSales(sId){return SB_SALES.find(s=>s.id===sId);}

