// ════════ CONTRACTS store (Rate/Contract model · Phase 1 · 2026-07-23) ════════
// Multiple contracts per agent: one 'main' + optional time-boxed 'promo' overlays (Phase 2+ adds the
// booking-time resolver). Phase 1 = DATA + MIGRATION ONLY — pricing is UNCHANGED (booking still reads
// agent.rateTypeId). Blob key 'sb_contracts' ↔ Postgres sb_contracts (+ child sb_contracts__programperiods).
// Load with Array.isArray so a deliberately-cleared list stays cleared (CLAUDE.md §2 "Load conditions matter").
let SB_CONTRACTS = [];
(function(){ try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); if(Array.isArray(d.sb_contracts)) SB_CONTRACTS = d.sb_contracts; }catch(e){ console.warn('load sb_contracts failed', e); } })();
function sbContractsPersist(){ if(typeof window.laCanEditArea==='function' && !window.laCanEditArea('sales')) return; try{ const d=JSON.parse(localStorage.getItem(LS_KEY)||'{}'); d.sb_contracts=SB_CONTRACTS; localStorage.setItem(LS_KEY, JSON.stringify(d)); }catch(e){ console.warn('persist sb_contracts failed', e); } }
// One-time, idempotent migration: each agent's existing single contract (contractStart/End/Version/
// programPeriods) → one 'main' sb_contract; archived contractHistory[] snapshots → prior 'expired' contracts.
// Skips agents that already have a migrated main (id 'ct_main_<agentId>') so re-runs / cloud-loads are no-ops.
(function _sbMigrateContracts(){
  try{
    if(typeof SB_AGENTS==='undefined' || !Array.isArray(SB_AGENTS)) return;
    const seen = new Set((SB_CONTRACTS||[]).map(c=>c && c.id));
    const _pp = list => (list||[]).map(p=>({routeId:p.routeId, bookFrom:p.bookFrom, bookTo:p.bookTo, travelFrom:p.travelFrom, travelTo:p.travelTo, note:p.note||''}));
    let added=0;
    (SB_AGENTS||[]).forEach(a=>{
      if(!a || !a.id) return;
      const mainId='ct_main_'+a.id;
      if(!seen.has(mainId)){
        SB_CONTRACTS.push({
          id:mainId, agentId:a.id, kind:'main', rateTypeId:a.rateTypeId||null,
          activeFrom:a.contractStart||null, activeTo:a.contractEnd||null, priority:0,
          version:a.contractVersion||'v1', status:(a.contractStatus==='expired'?'expired':'active'),
          createdDate:a.contractStart||null, createdBy:'migration', note:'', docId:null,
          programPeriods:_pp(a.programPeriods)
        });
        seen.add(mainId); added++;
      }
      (a.contractHistory||[]).forEach((h,i)=>{
        const hid='ct_hist_'+a.id+'_'+(h.version||i);
        if(seen.has(hid)) return;
        const snap=h.snapshot||{};
        SB_CONTRACTS.push({
          id:hid, agentId:a.id, kind:'main', rateTypeId:a.rateTypeId||null,
          activeFrom:h.contractStart||null, activeTo:h.contractEnd||null, priority:0,
          version:h.version||('hist'+i), status:'expired',
          createdDate:h.contractStart||null, createdBy:'migration', note:'archived', docId:null,
          programPeriods:_pp(snap.programPeriods)
        });
        seen.add(hid); added++;
      });
    });
    if(added>0){ sbContractsPersist(); console.log('[migrate] sb_contracts: created '+added+' contract(s) from agent fields'); }
  }catch(e){ console.warn('sb_contracts migration failed', e); }
})();

// ── Contract helper functions ──
function _ctTodayISO(){ return new Date().toISOString().slice(0,10); }
function _ctMockToday(){ return (typeof TODAY_STR!=='undefined' && TODAY_STR) ? TODAY_STR : fmt(new Date()); } // §ใช้วันจริง · เดิม hardcode '2026-09-02' ตอน demo → ทำให้ "เหลือกี่วัน" ในแบนเนอร์สัญญาเพี้ยน
function ctDaysUntilExpiry(a){
  if(!a?.contractEnd) return null;
  const today = new Date(_ctMockToday());
  const end = new Date(a.contractEnd);
  const diff = Math.ceil((end - today) / (1000*60*60*24));
  return diff;
}
function ctIsExpiringSoon(a, daysThreshold=60){   // §2026-07-24: widened 30→60 so the renewal warning + button surface earlier
  const d = ctDaysUntilExpiry(a);
  return d !== null && d >= 0 && d <= daysThreshold;
}
function ctIsExpired(a){
  const d = ctDaysUntilExpiry(a);
  return d !== null && d < 0;
}
function ctCountExpiringAgents(){
  return SB_AGENTS.filter(a=>ctIsExpiringSoon(a) || ctIsExpired(a)).length;
}
function ctFmtDate(iso){
  if(!iso) return '—';
  const d = new Date(iso); if(isNaN(d)) return iso;
  const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return `${String(d.getDate()).padStart(2,'0')} ${months[d.getMonth()]} ${String(d.getFullYear()).slice(2)}`;
}

// ── Pricing Matrix: prices[agentId][routeId][zone][paxType] ──
// paxType: adult-thai, adult-fr, child-thai, child-fr, infant-thai, infant-fr
// zone: PK, KL, NoTransfer
function _seedAgentPrices(){
  const prices = {};
  SB_AGENTS.forEach(ag=>{
    prices[ag.id] = {};
    (ag.programs||[]).forEach(rId=>{ /* UI-created agents have no programs array */
      const r = ROUTES.find(x=>x.id===rId);
      if(!r) return;
      // Base prices vary by market & route type
      const isWS = rId==='r12';           // whale shark - premium
      const isSurin = rId==='r6';         // surin - long distance
      const isPP = rId==='r10' || rId==='r9' || rId==='r7' || rId==='r8';
      // base adult thai (NoTransfer) by route
      let baseT = 1800;
      if(isWS) baseT = 3500;
      else if(isSurin) baseT = 2800;
      else if(isPP) baseT = 1500;
      else baseT = 2200; // similan default
      // market premium
      const mktMul = {ru:1.05, ota:1.15, ap:1.10, hpk:1.20, hkl:1.18, cpk:1.00, ckl:1.00, ww:1.12}[ag.market]||1;
      const adjT = Math.round(baseT*mktMul/10)*10;
      const adjF = Math.round(adjT*1.45/10)*10;  // foreigner usually higher
      prices[ag.id][rId] = {
        PK: {
          'adult-thai':adjT+200,'adult-fr':adjF+200,
          'child-thai':Math.round((adjT+200)*0.6/10)*10,'child-fr':Math.round((adjF+200)*0.6/10)*10,
          'infant-thai':0,'infant-fr':0
        },
        KL: {
          'adult-thai':adjT+100,'adult-fr':adjF+100,
          'child-thai':Math.round((adjT+100)*0.6/10)*10,'child-fr':Math.round((adjF+100)*0.6/10)*10,
          'infant-thai':0,'infant-fr':0
        },
        NoTransfer: {
          'adult-thai':adjT,'adult-fr':adjF,
          'child-thai':Math.round(adjT*0.6/10)*10,'child-fr':Math.round(adjF*0.6/10)*10,
          'infant-thai':0,'infant-fr':0
        }
      };
    });
  });
  return prices;
}
let SB_AGENT_PRICES = _seedAgentPrices();

// Backfill historical pricing snapshots for ALL IN TRAVEL (after SB_AGENT_PRICES is ready)
(function _seedHistoricalPricing(){
  const allin = SB_AGENTS.find(x=>x.id==='a73');
  if(!allin || !allin.contractHistory) return;
  const currentPrices = SB_AGENT_PRICES[allin.id] || {};
  // Apply discount per archive year — older = cheaper
  const applyDiscount = (basePrices, factor)=>{
    const out = {};
    Object.keys(basePrices).forEach(routeId=>{
      out[routeId] = {};
      Object.keys(basePrices[routeId]).forEach(zone=>{
        out[routeId][zone] = {};
        Object.keys(basePrices[routeId][zone]).forEach(pax=>{
          const v = basePrices[routeId][zone][pax];
          out[routeId][zone][pax] = v ? Math.round(v*factor/100)*100 : v;
        });
      });
    });
    return out;
  };
  // v2024-1 = 92% of current
  const v2024 = allin.contractHistory.find(h=>h.version==='v2024-1');
  if(v2024){
    // Only include routes that were in that contract
    const routeIds = (v2024.snapshot.programPeriods||[]).map(p=>p.routeId);
    const filtered = {};
    routeIds.forEach(rId=>{ if(currentPrices[rId]) filtered[rId] = currentPrices[rId]; });
    v2024.snapshot.prices = applyDiscount(filtered, 0.92);
  }
  // v2023-1 = 85% of current
  const v2023 = allin.contractHistory.find(h=>h.version==='v2023-1');
  if(v2023){
    const routeIds = (v2023.snapshot.programPeriods||[]).map(p=>p.routeId);
    const filtered = {};
    routeIds.forEach(rId=>{ if(currentPrices[rId]) filtered[rId] = currentPrices[rId]; });
    v2023.snapshot.prices = applyDiscount(filtered, 0.85);
  }
})();

