  try { const d = JSON.parse(localStorage.getItem(LS_KEY)||'{}'); return Array.isArray(d.sb_seat_locks) ? d.sb_seat_locks : SB_SEAT_LOCKS_SEED.map(l=>({...l})); }
  catch(e){ return SB_SEAT_LOCKS_SEED.map(l=>({...l})); }
