  return '<span class="ts-chip '+d.cls+' ts-doc" title="'+e(tip)+' · คลิกไปหน้าตรวจเอกสาร"'
    + ' onclick="tsGoDoc(\''+b.id+'\',\''+date+'\')">'+e(d.label)+(d.n?(' '+d.n):'')+'</span>';
