    var noVan  = _gone || (r.vanDone  && (r.vanActual!=null)  && r.vanActual<=0)
                       || (!!r.vanCk  && (typeof ckEventTally==='function') && ckEventTally(r.vanCk).total>=r.booked && r.booked>0);
    var noBoat = _gone || (r.pierDone && (r.pierActual!=null) && r.pierActual<=0)
