      <div style="display:flex;align-items:center;gap:11px">
        <span style="width:30px;height:30px;border-radius:50%;background:#13a538;display:inline-flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:14px">K</span>
        <div style="font-size:11px;color:#333"><div>${BANK.bank}</div><div style="font-weight:700">${BANK.acc}</div><div>${BANK.name}</div></div>
      </div>
