    <div style="border-top:1px solid #d7d9de;margin-top:11px;padding-top:11px"><div style="font-weight:700;font-size:12px">${ic(ICHAT,'#1a1a1a',14)}Remark</div><div style="min-height:16px;font-size:11px;color:#666">${inv.remark||''}</div></div>

