let _bkTab = 'b2b';
let _bkDraft = {
  channelType:'b2b',
  channel:'',
  programId:'',
  travelDate:'',
  customerName:'',
  nationality:'',
  paxType:'thai',
  pax:{adult:1,child:0,infant:0},
  transfer:'NoTransfer',
  payment:'',
  note:'',
};

function renderBooking(){
  // v2 Linear list (Phase 1) · old v1 form rendering kept below as legacy
  if(typeof bkV2RenderList === 'function'){
    bkV2RenderList();
    return;
  }
  // Fallback to legacy v1 (only runs if bkV2RenderList not loaded)
  _bkTab = 'b2b';
  _bkDraft.channelType = 'b2b';
  document.querySelectorAll('.bk-tab').forEach(t=>t.classList.toggle('on', t.dataset.bk==='b2b'));
  bkRenderForm();
  bkRenderRecent();
}

function bkSwitchTab(tab){
  _bkTab = tab;
  _bkDraft.channelType = tab;
  _bkDraft.channel = '';
  _bkDraft.payment = '';
  document.querySelectorAll('.bk-tab').forEach(t=>t.classList.toggle('on', t.dataset.bk===tab));
  bkRenderForm();
}

function bkRenderForm(){
  const host = document.getElementById('bk-form-host');
  if(!host) return;
  const isB2B = _bkTab==='b2b';

  // Build channel options (mark selected during build)
  const sel = _bkDraft.channel;
  const selAttr = (v) => v===sel ? ' selected' : '';
  let channelOptions = `<option value=""${sel===''?' selected':''}>— เลือก —</option>`;
  if(isB2B){
    SB_MARKETS.forEach(m=>{
      const list = SB_AGENTS.filter(a=>a.market===m.id);
      if(list.length===0) return;
      channelOptions += `<optgroup label="${m.name}">`;
      list.forEach(a=>{ channelOptions += `<option value="${a.id}"${selAttr(a.id)}>${a.name} (${a.code})</option>`; });
      channelOptions += `</optgroup>`;
    });
  } else {
    const ch = SB_B2C.filter(c=>c.type==='channel');
    const cm = SB_B2C.filter(c=>c.type==='campaign');
    channelOptions += `<optgroup label="ช่องทาง">`;
    ch.forEach(c=>{ channelOptions += `<option value="${c.id}"${selAttr(c.id)}>${c.name}</option>`; });
    channelOptions += `</optgroup><optgroup label="Campaign">`;
    cm.forEach(c=>{ channelOptions += `<option value="${c.id}"${selAttr(c.id)}>${c.name} (-${Math.round((c.discount||0)*100)}%)</option>`; });
    channelOptions += `</optgroup>`;
  }

  // Filter programs based on selected B2B agent
  let availPrograms = ROUTES;
  if(isB2B && _bkDraft.channel){
    const a = sbGetAgent(_bkDraft.channel);
    if(a) availPrograms = ROUTES.filter(r=>(a.programs||[]).includes(r.id));
  }
  const progOptions = '<option value="">— เลือก Program —</option>' + availPrograms.map(r=>`<option value="${r.id}" ${_bkDraft.programId===r.id?'selected':''}>${r.name} · ${r.pier==='tublamu'?'TL':'VP'}</option>`).join('');

  // Filter payment based on agent or channel
  let avPay = SB_PAYMENT_TYPES;
  if(isB2B && _bkDraft.channel){
    const a = sbGetAgent(_bkDraft.channel);
    if(a) avPay = SB_PAYMENT_TYPES.filter(p=>p.id===a.payType);
  } else if(!isB2B && _bkDraft.channel){
    const c = sbGetB2C(_bkDraft.channel);
    if(c) avPay = SB_PAYMENT_TYPES.filter(p=>(c.payment||[]).includes(p.id));
  }
  const payOptions = '<option value="">— เลือก —</option>' + avPay.map(p=>`<option value="${p.id}" ${_bkDraft.payment===p.id?'selected':''}>${p.name}</option>`).join('');

  // Unit price preview
  const unitInfo = bkPricePreview();

  host.innerHTML = `
    <div class="bk-form-grid">
      <div class="bk-fld">
        <label class="bk-fld-lbl">${isB2B?'Agent':'ช่องทาง / Campaign'}<span class="req">*</span></label>
        <select onchange="bkSet('channel',this.value)">
          ${channelOptions}
        </select>
      </div>
      <div class="bk-fld">
        <label class="bk-fld-lbl">Program<span class="req">*</span></label>
        <select onchange="bkSet('programId',this.value)">${progOptions}</select>
      </div>
      <div class="bk-fld">
        <label class="bk-fld-lbl">วันเดินทาง<span class="req">*</span></label>
        <input type="date" value="${_bkDraft.travelDate}" onchange="bkSet('travelDate',this.value)">
      </div>
      <div class="bk-fld">
        <label class="bk-fld-lbl">ชื่อลูกค้า (Lead)<span class="req">*</span></label>
        <input type="text" value="${_bkDraft.customerName}" placeholder="เช่น Sergei Volkov" oninput="bkSet('customerName',this.value)">
      </div>
      <div class="bk-fld">
        <label class="bk-fld-lbl">สัญชาติ</label>
        <input type="text" value="${_bkDraft.nationality}" placeholder="Russian / Chinese / Thai…" oninput="bkSet('nationality',this.value)">
      </div>
      <div class="bk-fld">
        <label class="bk-fld-lbl">Pax Type · ราคา</label>
        <select onchange="bkSet('paxType',this.value)">
          <option value="thai" ${_bkDraft.paxType==='thai'?'selected':''}>Thai rate</option>
          <option value="fr" ${_bkDraft.paxType==='fr'?'selected':''}>Foreigner rate</option>
        </select>
      </div>
      ${isB2B?`
      <div class="bk-fld">
        <label class="bk-fld-lbl">Transfer Zone</label>
        <select onchange="bkSet('transfer',this.value)">
          <option value="PK" ${_bkDraft.transfer==='PK'?'selected':''}>PK · Phuket pickup</option>
          <option value="KL" ${_bkDraft.transfer==='KL'?'selected':''}>KL · Khao Lak pickup</option>
          <option value="NoTransfer" ${_bkDraft.transfer==='NoTransfer'?'selected':''}>No Transfer · มาเอง</option>
        </select>
      </div>
      `:`
      <div class="bk-fld">
        <label class="bk-fld-lbl">Transfer</label>
        <select onchange="bkSet('transfer',this.value)">
          <option value="NoTransfer" ${_bkDraft.transfer==='NoTransfer'?'selected':''}>No Transfer · มาเอง</option>
          <option value="PK" ${_bkDraft.transfer==='PK'?'selected':''}>PK · Phuket pickup</option>
          <option value="KL" ${_bkDraft.transfer==='KL'?'selected':''}>KL · Khao Lak pickup</option>
        </select>
      </div>
      `}
      <div class="bk-fld">
        <label class="bk-fld-lbl">วิธีชำระเงิน<span class="req">*</span></label>
        <select onchange="bkSet('payment',this.value)">${payOptions}</select>
      </div>
    </div>

    <div class="bk-section-divider">PASSENGERS</div>
    <div class="bk-pax-grid">
      <div class="bk-pax-card">
        <div class="lbl">Adult</div>
        <input type="number" min="0" value="${_bkDraft.pax.adult}" oninput="bkSetPax('adult',this.value)">
        <div class="price">${unitInfo.adult?'฿'+sbFmtTHB(unitInfo.adult)+' / pax':'—'}</div>
      </div>
      <div class="bk-pax-card">
        <div class="lbl">Child</div>
        <input type="number" min="0" value="${_bkDraft.pax.child}" oninput="bkSetPax('child',this.value)">
        <div class="price">${unitInfo.child?'฿'+sbFmtTHB(unitInfo.child)+' / pax':'—'}</div>
      </div>
      <div class="bk-pax-card">
        <div class="lbl">Infant</div>
        <input type="number" min="0" value="${_bkDraft.pax.infant}" oninput="bkSetPax('infant',this.value)">
        <div class="price">${unitInfo.infant?'฿'+sbFmtTHB(unitInfo.infant)+' / pax':'Free · นับที่นั่ง'}</div>
      </div>
    </div>

    <div class="bk-section-divider">NOTES</div>
    <div class="bk-fld">
      <textarea placeholder="หมายเหตุเพิ่มเติม เช่น แพ้อาหารทะเล, ใช้รถตู้ส่วนตัว, ฯลฯ" oninput="bkSet('note',this.value)">${_bkDraft.note}</textarea>
    </div>

    <div class="bk-summary">
      <div class="bk-summary-row"><span class="lbl">Adult × ${_bkDraft.pax.adult}</span><span class="val">฿${sbFmtTHB((unitInfo.adult||0)*_bkDraft.pax.adult)}</span></div>
      <div class="bk-summary-row"><span class="lbl">Child × ${_bkDraft.pax.child}</span><span class="val">฿${sbFmtTHB((unitInfo.child||0)*_bkDraft.pax.child)}</span></div>
      <div class="bk-summary-row"><span class="lbl">Infant × ${_bkDraft.pax.infant}</span><span class="val">฿${sbFmtTHB((unitInfo.infant||0)*_bkDraft.pax.infant)}</span></div>
      <div class="bk-summary-row total"><span class="lbl">TOTAL</span><span class="val">฿${sbFmtTHB(unitInfo.total)}</span></div>
    </div>

    <div class="bk-actions">
      <button class="btn btn-ghost btn-sm" onclick="bkReset()">รีเซ็ต</button>
      <button class="btn btn-pink btn-sm" onclick="bkSubmit()">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 11l3 3L22 4M21 12v7a2 2 0 01-2 2H5a2 2 0 01-2-2V5a2 2 0 012-2h11"/></svg>
        บันทึกการจอง
      </button>
    </div>
  `;
}

function bkSet(key, val){
  _bkDraft[key] = val;
  // re-render when channel/program/paxType/transfer changes so prices update
  if(['channel','programId','paxType','transfer','payment'].includes(key)) bkRenderForm();
}
function bkSetPax(which, val){
  _bkDraft.pax[which] = parseInt(val)||0;
  bkRenderForm();
}
function bkPricePreview(){
  const tmp = {..._bkDraft};
  // build a dummy booking and use sbCalcBookingTotal logic but return per-pax
  let unitA=0, unitC=0, unitI=0;
  if(_bkDraft.channelType==='b2b' && _bkDraft.channel && _bkDraft.programId){
    const pm = SB_AGENT_PRICES[_bkDraft.channel];
    if(pm && pm[_bkDraft.programId]){
      const zone = pm[_bkDraft.programId][_bkDraft.transfer||'NoTransfer'];
      if(zone){
        unitA = zone[`adult-${_bkDraft.paxType}`]||0;
        unitC = zone[`child-${_bkDraft.paxType}`]||0;
        unitI = zone[`infant-${_bkDraft.paxType}`]||0;
      }
    }
  } else if(_bkDraft.channelType==='b2c' && _bkDraft.channel && _bkDraft.programId){
    const ch = sbGetB2C(_bkDraft.channel);
    const base = SB_B2C_BASE[_bkDraft.programId];
    if(ch && base){
      const mul = ch.type==='campaign' ? (1-(ch.discount||0)) : (ch.priceMul||1);
      unitA = Math.round((base[`adult-${_bkDraft.paxType}`]||0)*mul);
      unitC = Math.round((base[`child-${_bkDraft.paxType}`]||0)*mul);
      unitI = Math.round((base[`infant-${_bkDraft.paxType}`]||0)*mul);
    }
  }
  const total = unitA*_bkDraft.pax.adult + unitC*_bkDraft.pax.child + unitI*_bkDraft.pax.infant;
  return {adult:unitA, child:unitC, infant:unitI, total};
}
function bkReset(){
  _bkDraft = {channelType:_bkTab, channel:'', programId:'', travelDate:'', customerName:'', nationality:'', paxType:'thai', pax:{adult:1,child:0,infant:0}, transfer:'NoTransfer', payment:'', note:''};
  bkRenderForm();
}
function bkSubmit(){
  // basic validation
  if(!_bkDraft.channel) return alert('กรุณาเลือก '+(_bkTab==='b2b'?'Agent':'ช่องทาง'));
  if(!_bkDraft.programId) return alert('กรุณาเลือก Program');
  if(!_bkDraft.travelDate) return alert('กรุณาเลือกวันเดินทาง');
  if(!_bkDraft.customerName) return alert('กรุณาระบุชื่อลูกค้า');
  if(!_bkDraft.payment) return alert('กรุณาเลือกวิธีชำระเงิน');
  if(_bkDraft.pax.adult+_bkDraft.pax.child+_bkDraft.pax.infant===0) return alert('กรุณาระบุจำนวนผู้โดยสาร');

  const newBk = {
    id: 'BK-'+new Date().toISOString().slice(2,10).replace(/-/g,'')+'-'+String(SB_BOOKINGS.length+1).padStart(3,'0')+'-'+(Math.random().toString(36).slice(2,6)+'0000').slice(0,4).toUpperCase(),  // + random suffix · globally unique (multi-user safe)
    dateCreated: new Date().toISOString().slice(0,10),
    travelDate: _bkDraft.travelDate,
    customerName: _bkDraft.customerName,
    nationality: _bkDraft.nationality,
    channel: _bkDraft.channel,
    channelType: _bkDraft.channelType,
    programId: _bkDraft.programId,
    pax: {...(_bkDraft.pax)},
    paxType: _bkDraft.paxType,
    transfer: _bkDraft.transfer,
    payment: _bkDraft.payment,
    note: _bkDraft.note,
    status: 'confirmed',
    total: 0,
  };
  newBk.total = sbCalcBookingTotal(newBk);
  SB_BOOKINGS.push(newBk);
  alert(`บันทึกการจองเรียบร้อย\n${newBk.id}\nรวม ฿${sbFmtTHB(newBk.total)}`);
  bkReset();
  bkRenderRecent();
}

function bkRenderRecent(){
  const tbody = document.getElementById('bk-recent-body');
  if(!tbody) return;
  const list = SB_BOOKINGS.slice().reverse().slice(0,15);
  document.getElementById('bk-recent-count').textContent = `${SB_BOOKINGS.length} bookings`;
  tbody.innerHTML = list.map(bk=>{
    const r = ROUTES.find(x=>x.id===bk.programId);
    let chName = '—';
    if(bk.channelType==='b2b'){
      const a = sbGetAgent(bk.channel);
      chName = a ? `<span class="sb-chip" style="background:${'var(--ocean-50)'};color:${'var(--ocean)'}">B2B</span> ${a.code}` : '—';
    } else {
      const c = sbGetB2C(bk.channel);
      chName = c ? `<span class="sb-chip pink">B2C</span> ${c.name.split('(')[0].trim()}` : '—';
    }
    const totPax = (bk.pax.adult||0)+(bk.pax.child||0)+(bk.pax.infant||0);
    return `<tr>
      <td class="bk-id">${bk.id}</td>
      <td>${sbFmtDate(bk.dateCreated)}</td>
      <td>${sbFmtDate(bk.travelDate)}</td>
      <td>${bk.customerName}<div style="font-size:9px;color:var(--ink-soft);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.04em">${bk.nationality||''}</div></td>
      <td><div style="font-size:11px">${r?.name||'—'}</div><div style="font-size:9px;color:var(--ink-soft)">${bk.transfer==='NoTransfer'?'no transfer':bk.transfer+' transfer'}</div></td>
      <td>${chName}</td>
      <td class="num">${totPax}<div style="font-size:9px;color:var(--ink-soft)">${bk.pax.adult}A·${bk.pax.child}C·${bk.pax.infant}I</div></td>
      <td class="num">฿${sbFmtTHB(bk.total)}</td>
      <td><span class="pill ${bk.status==='confirmed'?'pill-green':bk.status==='pending'?'pill-amber':'pill-gray'}">${bk.status}</span></td>
    </tr>`;
  }).join('');
}

// ═══════════════════════════════════════════════════════════════
// BOOKING v2 — Linear list page (Phase 1)
// ═══════════════════════════════════════════════════════════════
// State (P1 rework · 3-tab + P2 New Booking form)
const _bkV2 = {
  tab: 'cal',           // 'cal' | 'bytrip' | 'all'
  view: 'cal',          // 'cal' | 'mx' (only when tab === 'cal')
  cursor: new Date(),   // 1st of currently viewed month
  selected: null,       // { date:'YYYY-MM-DD', routeId?:'r5' }
  avgMode: 'week',      // 'week' | 'day' | 'total' (per-route avg cards mode)
  expanded: new Set(),  // family ids currently expanded in Matrix view
  filterRoute: null,    // for Tab 2 'bytrip'
  filterDate: null,     // for Tab 2 'bytrip'
  search: '',           // for Tab 3 'all'
  statusFilter: 'all',  // for Tab 3 'all'
  newBooking: null,     // P2 · draft object when form is open · null when closed
  detailId: null,       // P3 · booking id when detail view is open · null when on list
  editingId: null,      // P3 · booking id when editing existing · used by Edit mode
  boatAssignMode: false,// By-trip-date "Boat Assign" mode → adds a Boat column + auto-assign
  vanAssignMode: false, // By-trip-date "Van Assign" mode → adds a Van column + pickup time + job order
  reconfirmMode: false  // By-trip-date "Re-Confirm" mode → confirm actual pickup times with the agent
};

// Program families · 5 main groups · each containing 1-5 route variants
const _BKV2_FAMILIES = [
  { id:'similan',    name:'Similan Islands',            color:'#185fa5' },
  { id:'surin',      name:'Surin Islands',              color:'#3B6D11' },
  { id:'phiphi',     name:'Phi Phi Bamboo',             color:'#c0392b' },
  { id:'krabi',      name:'Krabi + Phang Nga',          color:'#0F6E56' },
  { id:'whaleshark', name:'Whale Shark Phi Phi Maiton', color:'#BA7517' },
  { id:'selava',     name:'Day Trip - Se La Va',        color:'#BA7517' },
  { id:'nyaung',     name:'Day Trip - Nyaung Oo Phee Island', color:'#0F6E56' }
];
// Map a route to its family by name pattern (Whale check first to avoid Phi Phi conflict)
function bkV2RouteFamily(routeId){
  if(typeof ROUTES === 'undefined') return null;
  const r = ROUTES.find(rr => rr.id === routeId);
  if(!r) return null;
  const n = r.name || '';
  if(n.includes('Nyaung') || n.includes('Oo Phee')) return _BKV2_FAMILIES[6];
  if(n.includes('Se La Va') || n.includes('SeLaVa')) return _BKV2_FAMILIES[5];
  if(n.includes('Whale')) return _BKV2_FAMILIES[4];
  if(n.includes('Similan')) return _BKV2_FAMILIES[0];
  if(n.includes('Surin')) return _BKV2_FAMILIES[1];
  if(n.includes('Phi Phi')) return _BKV2_FAMILIES[2];
  if(n.includes('Krabi') || n.includes('Phang Nga')) return _BKV2_FAMILIES[3];
  return null;
}
// All families that have ≥1 active route in the visible month
// Looks at ALL ROUTES (not just rate-type ones) · so ops sees every variant
function bkV2Families(){
  if(typeof ROUTES === 'undefined') return _BKV2_FAMILIES;
  return _BKV2_FAMILIES.filter(fam =>
    ROUTES.some(r => bkV2RouteFamily(r.id)?.id === fam.id && bkV2RouteActiveInMonth(r.id, _bkV2.cursor))
  );
}
// Routes within a family · ALL variants active in visible month (not filtered by rate type)
// Includes variants that ops sells but no agent has bound yet (Early Tratato · Early SY · Phi Phi FS · etc.)
function bkV2FamilyRoutes(familyId){
  if(typeof ROUTES === 'undefined') return [];
  return ROUTES
    .filter(r => bkV2RouteFamily(r.id)?.id === familyId)
    .filter(r => bkV2RouteActiveInMonth(r.id, _bkV2.cursor))
    .map(r => ({ id: r.id, full: r.name, short: bkV2ShortenRouteName(r.name) }));
}
// Family active on a specific date (any sub-route open)
function bkV2IsFamilyOpenOn(familyId, dateStr){
  return bkV2FamilyRoutes(familyId).some(r => bkV2IsRouteOpenOn(r.id, dateStr));
}
// Aggregate family pax for a specific date (sum across sub-routes)
function bkV2FamilyAggregate(familyId, dateStr, agg){
  const day = agg.byDate[dateStr];
  if(!day) return { total:0, ad:0, chd:0, inf:0, foc:0, pk:0, kl:0, nt:0, hasFocPending:false, subCount:0 };
  const subRoutes = bkV2FamilyRoutes(familyId);
  let total=0, ad=0, chd=0, inf=0, foc=0, pk=0, kl=0, nt=0, hasFocPending=false, subCount=0;
  subRoutes.forEach(r => {
    const cell = day.routes[r.id];
    if(!cell) return;
    subCount++;
    total += cell.total; ad += cell.ad; chd += cell.chd; inf += cell.inf; foc += cell.foc;
    pk += cell.pk; kl += cell.kl; nt += cell.nt;
    if(cell.hasFocPending) hasFocPending = true;
  });
  return { total, ad, chd, inf, foc, pk, kl, nt, hasFocPending, subCount };
}
// Toggle expand state for a family in Matrix
function bkV2ToggleFamily(famId){
  if(_bkV2.expanded.has(famId)) _bkV2.expanded.delete(famId);
  else _bkV2.expanded.add(famId);
  bkV2Render();
}
function bkV2ExpandAllFamilies(){
  bkV2Families().forEach(f => _bkV2.expanded.add(f.id));
  bkV2Render();
}
function bkV2CollapseAllFamilies(){
  _bkV2.expanded.clear();
  bkV2Render();
}

// Routes shown in Tab 1 (Calendar + Matrix) · derived live from ROUTES + Rate Types + bookings
// Single source of truth: ROUTES (same as Agent · Rate Type pages)
function bkV2ShortenRouteName(name){
  if(!name) return '';
  return name
    .replace('Whale Shark Phi Phi Maiton Sunset','Whale Shark')
    .replace('Similan Islands by Speedboat','Similan SB')
    .replace('Similan Islands by Catamaran','Similan Cat')
    .replace('Similan Islands - PG','Similan PG')
    .replace('Early Tratato Similan Islands','Early Tratato')
    .replace('Early Tiger Similan Islands','Early Tiger')
    .replace('Surin Islands by Speedboat','Surin SB')
    .replace('Phi Phi Bamboo by Speedboat','Phi Phi SB')
    .replace('Phi Phi Bamboo - FS','Phi Phi FS')
    .replace('Early SY Phi Phi Bamboo','Early SY')
    .replace('Early OTA Phi Phi Bamboo','Early OTA')
    .replace('Early Krabi + Phang Nga','Early Krabi+PN');
}

// Is route open on a specific date? (consults Programs · seasons + overrides)
function bkV2IsRouteOpenOn(routeId, dateStr){
  if(typeof ROUTES === 'undefined') return true;
  const r = ROUTES.find(rr => rr.id === routeId);
  if(!r) return true;
  if(typeof getDayStatus !== 'function') return true;
  const s = getDayStatus(r, dateStr);
  if(!s) return true;  // no season defined → assume open
  return s.type === 'open';
}
// §non-operating · find the next date (from `fromDate`, inclusive) that this route actually runs.
// Used to default a trip's date to the next running day (skips closed/off-season/weather days).
// Caps the search at 120 days; returns fromDate unchanged if none found (the save-time guard will catch it).
function bkV2NextOpenDate(routeId, fromDate){
  if(typeof bkV2IsRouteOpenOn !== 'function') return fromDate;
  try{
    const base = fromDate ? new Date(fromDate + 'T00:00:00') : new Date();
    if(isNaN(base.getTime())) return fromDate;
    for(let i=0; i<=120; i++){
      const d = new Date(base.getTime() + i*864e5);
      const key = (typeof bkV2LocalYMD==='function') ? bkV2LocalYMD(d) : d.toISOString().slice(0,10);
      if(bkV2IsRouteOpenOn(routeId, key)) return key;
    }
  }catch(e){}
  return fromDate;
}

// Does route have ≥1 open day in the given month? (used to filter list)
function bkV2RouteActiveInMonth(routeId, cursor){
  const y = cursor.getFullYear();
  const m = cursor.getMonth();
  const lastDay = new Date(y, m+1, 0).getDate();
  for(let d = 1; d <= lastDay; d++){
    const key = `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    if(bkV2IsRouteOpenOn(routeId, key)) return true;
  }
  return false;
}

function bkV2Routes(){
  // Collect routeIds referenced by active Rate Types + any booking trip
  const ids = new Set();
  if(typeof SB_RATE_TYPES !== 'undefined' && Array.isArray(SB_RATE_TYPES)){
    SB_RATE_TYPES.forEach(rt => {
      if(rt.active !== false && Array.isArray(rt.routes)) rt.routes.forEach(rid => ids.add(rid));
    });
  }
  SB_BOOKINGS.forEach(bk => {
    if(bk.schemaVer === 2 && Array.isArray(bk.trips)){
      bk.trips.forEach(t => t.routeId && ids.add(t.routeId));
    } else if(bk.programId){
      ids.add(bk.programId);
    }
  });
  // Map to {id, short, full} via ROUTES (source of truth)
  if(typeof ROUTES === 'undefined') return [];
  const out = [];
  ids.forEach(id => {
    const r = ROUTES.find(rr => rr.id === id);
    if(!r) return;
    out.push({ id, full: r.name, short: bkV2ShortenRouteName(r.name) });
  });
  // Preserve ROUTES original order
  out.sort((a,b) => ROUTES.findIndex(r=>r.id===a.id) - ROUTES.findIndex(r=>r.id===b.id));
  // ★ Filter to routes that have ≥1 open day in the visible month (per Programs seasons)
  return out.filter(r => bkV2RouteActiveInMonth(r.id, _bkV2.cursor));
}

function bkV2Route(id){ return bkV2Routes().find(r => r.id === id); }
function bkV2RouteShort(id){
  const known = bkV2Routes().find(r => r.id === id);
  if(known) return known.short;
  const r = (typeof ROUTES !== 'undefined') ? ROUTES.find(rr => rr.id === id) : null;
  return r ? bkV2ShortenRouteName(r.name) : id;
}

// Pickup string → zone (PK / KL / NT)
function bkV2InferZone(bk){
  const pickup = (bk.pickup || '').toLowerCase();
  if(pickup.includes('khao lak') || pickup.startsWith('kl ')) return 'KL';
  if(pickup.includes('walk-in') || pickup.includes('pier') || pickup.includes('no transfer')) return 'NT';
  return 'PK';
}

// Aggregate all bookings into per-day, per-route, per-zone structure
function bkV2Aggregate(){
  const out = { byDate: {} };
  const ensureDay = d => {
    if(!out.byDate[d]) out.byDate[d] = {
      total:0, ad:0, chd:0, inf:0, foc:0, pk:0, kl:0, nt:0,
      hasFocPending:false, routes:{}, bookings:[], revenue:0
    };
    return out.byDate[d];
  };
  const ensureRoute = (day, rid) => {
    if(!day.routes[rid]) day.routes[rid] = {
      total:0, ad:0, chd:0, inf:0, foc:0, pk:0, kl:0, nt:0, hasFocPending:false
    };
    return day.routes[rid];
  };
  const addPax = (target, p, zone) => {
    // Handle both old (ad/chd/inf/foc) and new mixed (ad_fr+ad_th etc.) shapes
    const ad  = (p.ad||0) + (p.ad_fr||0) + (p.ad_th||0);
    const chd = (p.chd||0) + (p.chd_fr||0) + (p.chd_th||0);
    const inf = (p.inf||0) + (p.inf_fr||0) + (p.inf_th||0);
    const foc = (p.foc||0) + (p.foc_fr||0) + (p.foc_th||0);
    const tot = ad+chd+inf+foc;
    target.total += tot;
    target.ad += ad; target.chd += chd; target.inf += inf; target.foc += foc;
    target[zone.toLowerCase()] += tot;
  };

  SB_BOOKINGS.forEach(bk => {
    if(['cancelled','cancelled_weather','rejected'].includes(bk.status)) return;   // don't count cancelled/rejected pax in the calendar chips (matches By-trip / seat calc)
    if(bk.schemaVer === 2 && Array.isArray(bk.trips)){
      const zone = bkV2InferZone(bk);
      const focPending = bk.focApproval?.status === 'pending';
      bk.trips.forEach(trip => {
        if(!trip.date) return;
        const day = ensureDay(trip.date);
        const rt = ensureRoute(day, trip.routeId);
        const p = trip.pax || {};
        const focTot = (p.foc||0) + (p.foc_fr||0) + (p.foc_th||0);
        addPax(day, p, zone);
        addPax(rt, p, zone);
        day.revenue += ((bk.trips||[]).length<=1 ? (typeof bk.total==='number'?bk.total:(trip.subtotal||0)) : (trip.subtotal||0));   // single-trip → adjustment-inclusive total
        if(focTot > 0 && focPending){ day.hasFocPending = true; rt.hasFocPending = true; }
        if(!day.bookings.includes(bk.id)) day.bookings.push(bk.id);
      });
    } else if(bk.schemaVer !== 2 && bk.travelDate){
      // Legacy v1 — adapt pax shape
      const day = ensureDay(bk.travelDate);
      const rt = ensureRoute(day, bk.programId);
      const p = bk.pax || {};
      const compat = { ad: p.adult||0, chd: p.child||0, inf: p.infant||0, foc: 0 };
      const tr = (bk.transfer||'NoTransfer').toLowerCase();
      const zone = tr === 'pk' ? 'PK' : tr === 'kl' ? 'KL' : 'NT';
      addPax(day, compat, zone);
      addPax(rt, compat, zone);
      day.revenue += (bk.total||0);
      if(!day.bookings.includes(bk.id)) day.bookings.push(bk.id);
    }
  });
  return out;
}

// Intensity classes
function bkV2CellIntensity(total){
  if(total === 0) return 'empty';
  if(total <= 10) return 'lo';
  if(total <= 24) return 'mid';
  if(total <= 50) return 'hi';
  return 'peak';
}
function bkV2DayIntensity(total){
  if(total === 0) return 'empty';
  if(total <= 40) return 'lo';
  if(total <= 70) return 'mid';
  if(total <= 84) return 'hi';
  return 'peak';
}

// Normalize any v1 or v2 booking into a common shape for list rendering
function bkV2Norm(bk){
  if(bk.schemaVer === 2){
    // v2 native — handle both old (ad/chd) and new mixed (ad_fr/ad_th) shapes
    const totPax = (bk.trips||[]).reduce((s,t)=> s + bkV2PaxAllTot(t.pax||{}), 0);
    const foc = (bk.trips||[]).reduce((s,t)=> s + bkV2PaxTot(t.pax||{},'foc'), 0);
    const _isB2C = !!(bk.id && bk.id.indexOf('b2c_')===0);
    return {
      id: bk.id,
      schemaVer: 2,
      createdAt: bk.createdAt,
      agentName: bk.agentId ? (sbGetAgent(bk.agentId)?.name || (_isB2C?'B2C':bk.agentId)) : (_isB2C ? 'B2C' : (bk.b2cChannel ? (sbGetB2C(bk.b2cChannel)?.name || 'Direct') : '—')),
      agentSub: bk.rateTypeRef ? (SB_RATE_TYPES.find(r=>r.id===bk.rateTypeRef)?.code || bk.rateTypeRef) : ((_isB2C || bk.b2cChannel) ? 'B2C · Direct' : '—'),
      tripSummary: (bk.trips||[]).length === 1
        ? (ROUTES.find(r=>r.id===bk.trips[0].routeId)?.name || bk.trips[0].routeId)
        : `${(bk.trips||[]).length} trips · ${(bk.trips||[]).map(t=>(ROUTES.find(r=>r.id===t.routeId)?.name||'').split(' ')[0]).filter(Boolean).join(' + ')}`,
      travelDate: (bk.trips||[])[0]?.date || bk.createdAt || '',   // fall back to created date when a trip has no travel date (e.g. B2C rows missing travel_date)
      paxTotal: totPax,
      paxBreak: (function(){
        const ad = (bk.trips||[]).reduce((s,t)=>s+bkV2PaxTot(t.pax||{},'ad'),0);
        const chd = (bk.trips||[]).reduce((s,t)=>s+bkV2PaxTot(t.pax||{},'chd'),0);
        const inf = (bk.trips||[]).reduce((s,t)=>s+bkV2PaxTot(t.pax||{},'inf'),0);
        return `${ad}A · ${chd}C · ${inf}I` + (foc?` · ${foc} FOC`:'');
      })(),
      focCount: foc,
      focApproved: !!(bk.focApproval && bk.focApproval.status==='approved'),
      total: bk.total || bk.priceBreakdown?.total || 0,
      status: bk.status,
      payment: bk.paymentSnapshot?.method || '—',
      voucherRef: bk.voucherRef || '',
      leadPax: bk.leadPax || '',
      leadPhone: bk.leadPhone || ''
    };
  } else {
    // v1 legacy — best effort mapping
    let agentName = '—', agentSub = '—';
    if(bk.channelType === 'b2b'){
      const a = sbGetAgent(bk.channel);
      agentName = a?.name || bk.channel;
      agentSub = a?.rateTypeId ? (SB_RATE_TYPES.find(r=>r.id===a.rateTypeId)?.code || '') : 'B2B';
    } else {
      const c = sbGetB2C(bk.channel);
      agentName = bk.customerName || '—';
      agentSub = c?.name?.split('(')[0]?.trim() || 'B2C';
    }
    const tot = (bk.pax?.adult||0)+(bk.pax?.child||0)+(bk.pax?.infant||0);
    return {
      id: bk.id,
      schemaVer: 1,
      createdAt: bk.dateCreated,
      agentName: agentName,
      agentSub: agentSub,
      tripSummary: ROUTES.find(r=>r.id===bk.programId)?.name || bk.programId,
      travelDate: bk.travelDate,
      paxTotal: tot,
      paxBreak: `${bk.pax?.adult||0}A · ${bk.pax?.child||0}C · ${bk.pax?.infant||0}I`,
      focCount: 0,
      total: bk.total || 0,
      status: bk.status === 'pending' ? 'quote' : (bk.status || 'confirmed'),
      payment: bk.payment || '—',
      voucherRef: bk.voucherRef || '',
      leadPax: bk.customerName || '',
      leadPhone: bk.phone || bk.customerPhone || ''
    };
  }
}

function bkV2FmtTHB(n){ return new Intl.NumberFormat('en-US').format(Math.round(n||0)); }
function bkV2FmtDate(d){
  if(!d) return '—';
  const dt = typeof d === 'string' ? new Date(d.length <= 10 ? d + 'T00:00' : d) : d;
  if(isNaN(dt)) return '—';
  return dt.toLocaleDateString('en-GB', {day:'2-digit', month:'short'}).replace('.', '');
}
function bkV2StatusLabel(st){
  return ({
    'quote': 'Quote',
    'pending_foc': 'Pending FOC',
    'confirmed': 'Confirmed',
    'completed': 'Completed',
    'rejected': 'Rejected',
    'cancelled': 'Cancelled'
  })[st] || st;
}

// Main entry (called from renderBooking)
function bkV2Render(){
  const host = document.getElementById('bkv2-host');
  if(!host) return;
  try{
    // P3 · Detail view (read-only by default · Edit toggles into newBooking flow)
    if(_bkV2.detailId && !_bkV2.newBooking){
      host.innerHTML = `<div class="bkv2">${bkV2RenderBookingDetail()}</div>`;
      return;
    }
    // If New Booking form is open · render that instead of tabs
    if(_bkV2.newBooking){
      host.innerHTML = `<div class="bkv2">${bkV2RenderNewBooking()}</div>`;
      return;
    }
    host.innerHTML = `<div class="bkv2 bkv2-topcard">${bkV2RenderTopbar()}</div><div class="bkv2 bkv2-bodycard">${bkV2RenderTabBody()}</div>${bkV2RenderLockModal()}${(typeof bkV2LockOverlays==='function'?bkV2LockOverlays():'')}`;
    // Stack the sticky headers below the (sticky) day header · set LITERAL px offsets (no calc-in-custom-prop, which can fail to resolve)
    requestAnimationFrame(()=>{ try{
      const vb=document.getElementById('view-booking'); if(!vb) return;
      const h=0;   // day header is NOT sticky (scrolls away) - downstream sticky bars pin straight under the topbar
      const TOP=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--topbar'))||0;   // topbar height (0 after topbar removal · auto-reverts if bar restored)
      const vanOn=!!(typeof _bkV2!=='undefined'&&_bkV2&&_bkV2.vanAssignMode);
      // measure the actual van+grouping strip height (was hardcoded 96 → gap/overlap when real height differed)
      const vs=host.querySelector('.bkv2-vanstrip'); const VANGROUP=(vanOn&&vs)?vs.offsetHeight:0;
      vb.style.setProperty('--t2-vangroup-top', (TOP+h)+'px');
      vb.style.setProperty('--t2-head-top', (TOP+h+VANGROUP)+'px');
    }catch(_){} });
  }catch(e){
    console.error('[bkV2Render] render failed:', e);
    host.innerHTML = `<div class="bkv2" style="padding:24px"><div style="font-size:13px;color:#A32D2D;font-weight:600">⚠ Booking view render error</div><div style="font-size:12px;color:var(--ink-soft,#888);margin-top:6px;font-family:'DM Mono',monospace">${String((e&&e.message)||e).replace(/[<>&]/g,'')}</div><button onclick="_bkV2.detailId=null;_bkV2.newBooking=null;_bkV2.editingId=null;_bkV2.tab='cal';try{bkV2Render()}catch(_){}" style="margin-top:14px;background:#185FA5;color:#fff;border:none;font-family:inherit;font-size:12px;font-weight:600;padding:9px 16px;border-radius:9px;cursor:pointer">Reset to Calendar view</button></div>`;
  }
}

// New Booking form (P2 · single page · navy theme)
function bkV2RenderNewBooking(){
  const d = _bkV2.newBooking;
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);

  // Agent dropdown · group by market · only active
  const agentsByMarket = {};
  (SB_AGENTS||[]).forEach(a => {
    if(a.active === false) return;
    const m = a.market || 'other';
    if(!agentsByMarket[m]) agentsByMarket[m] = [];
    agentsByMarket[m].push(a);
  });
  const mktName = (mid) => {
    if(typeof SB_MARKETS === 'undefined') return mid;
    const m = SB_MARKETS.find(x => x.id === mid);
    return m?.name || mid;
  };
  // Build flat list for datalist · prefix with market label since datalist can't use optgroup
  const agentFlatList = Object.entries(agentsByMarket).sort((a,b) => mktName(a[0]).localeCompare(mktName(b[0]))).flatMap(([mid, agents]) => {
    return agents.map(a => ({
      id: a.id,
      label: `[${mktName(mid)}] ${a.code} · ${a.name}`
    }));
  });
  const agentDataList = agentFlatList.map(o => `<option value="${escapeHTML(o.label)}"></option>`).join('');
  const currentAgentLabel = (function(){
    if(!d.agentId) return '';
    const a = sbGetAgent(d.agentId);
    if(!a) return '';
    return `[${mktName(a.market)}] ${a.code} · ${a.name}`;
  })();

  // Rate Type preview (from selected agent)
  const rt = d.rateTypeRef ? (SB_RATE_TYPES||[]).find(r => r.id === d.rateTypeRef) : null;
  const agent = d.agentId ? sbGetAgent(d.agentId) : null;
  const isWalkin = !!(agent && (agent.code==='WALKIN' || agent.id==='a_walkin'));   // direct/walk-in house account
  const isStaff  = !!(agent && (agent.code==='STAFF'  || agent.id==='a_staff'));    // staff welfare/inspection house account
  const isHouse  = isWalkin || isStaff;   // house accounts → Sold-by/Staff picker + manual price option
  let rtPreview = '';
  if(rt){
    const routesCnt = (rt.routes||[]).length;
    const validFrom = rt.validFrom || '—';
    const validTo = rt.validTo || '—';
    rtPreview = `
      <div class="bkv2-nb-rt-preview">
        <div><strong>${escapeHTML(rt.code)} &middot; ${escapeHTML(rt.name)}</strong></div>
        <div class="meta">${routesCnt} route${routesCnt===1?'':'s'} covered &middot; valid ${validFrom} &rarr; ${validTo}</div>
      </div>
    `;
  } else if(typeof bkV2IsB2CBk==='function' && bkV2IsB2CBk(d)){
    // §b2cEdit · ใบ B2C ไม่ต้องมี Rate Type · ราคามาจากต้นทางโดยตรง · การไปผูกเรทให้เอเจนต์ B2C
    //   จะทำให้ระบบคิดราคาใหม่ทับยอดที่ลูกค้าจ่ายจริง ซึ่งผิดกว่าเดิม
    rtPreview = `<div class="bkv2-nb-rt-preview" style="background:#EEF5FF;border-color:#C3D8F2;color:#185FA5"><strong>ราคามาจาก B2C โดยตรง</strong><div class="meta">&#3647;${Number(d.manualTotal||0).toLocaleString()} &middot; ไม่ต้องผูก Rate Type &middot; ยอดเงิน ทริป และจำนวนคน แก้ที่ B2C เท่านั้น &middot; ที่แก้ได้ในหน้านี้คือจุดรับ-ส่ง ผู้ติดต่อ และข้อมูลปฏิบัติการ</div></div>`;
  } else if(d.agentId){
    rtPreview = `<div class="bkv2-nb-rt-preview" style="background:#FFF6E5;border-color:#EAD9B0;color:#633806"><strong>&#9888; No Rate Type bound</strong><div class="meta">This agent has no Rate Type assigned · go to Agent List to bind one before proceeding</div></div>`;
  }

  // Format created date
  const createdAt = new Date(d.createdAt);
  const createdStr = createdAt.toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' });

  // §b2cEdit · ใบ B2C ผ่านได้โดยไม่ต้องมีเรทและไม่ต้องมียอด (ใบ ฿0 ก็ยังต้องแก้จุดรับได้)
  const canContinue = d.agentId && d.leadPax && (d.rateTypeRef || (d.priceMode==='manual' && Number(d.manualTotal)>0)
    || (typeof bkV2IsB2CBk==='function' && bkV2IsB2CBk(d)));

  return `
    <div class="bkv2-nb">
      <div class="bkv2-nb-topbar">
        <button class="bkv2-nb-back" onclick="bkV2CloseNewBooking()">&larr; ${_bkV2.editingId?'Back to detail':'Back to list'}</button>
        <div class="bkv2-nb-h1">${_bkV2.editingId?'Edit Booking':'New Booking'}</div>
        <div style="font-family:'DM Mono',monospace;font-size:11px;color:var(--ink-soft);margin-left:6px">${_bkV2.editingId?d.id:d.code}</div>
        <div class="bkv2-nb-draft" style="${_bkV2.editingId?'background:#dbeafe;color:#1e40af':''}"><span class="dot" style="${_bkV2.editingId?'background:#1e40af':''}"></span>${_bkV2.editingId?'Editing':'Draft'}</div>
      </div>

      <div style="display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:12px;background:transparent;min-height:calc(100vh - 80px)">
       <div>

      <div class="bkv2-nb-sec">
        <div class="bkv2-nb-sec-h">&#9679; Agent &amp; Voucher</div>
        <div class="bkv2-nb-row" style="grid-template-columns:minmax(0,2.2fr) minmax(0,1fr)">
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Agent * <em style="font-weight:500;color:#b4b2a9;font-style:normal">· type to search</em></label>
            <div class="bkv2-nb-ddwrap">
              <input id="bkv2-agent-input" class="bkv2-nb-input" type="text" placeholder="Type code, name, or market..." value="${escapeHTML(currentAgentLabel)}" autocomplete="off" oninput="bkV2AgentDDFilter(this.value)" onfocus="bkV2AgentDDShow()" onkeydown="bkV2AgentDDKey(event)" style="text-overflow:ellipsis">
              <div id="bkv2-agent-dd" class="bkv2-nb-dd"></div>
            </div>
          </div>
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Voucher ref <em style="font-weight:500;color:#b4b2a9;font-style:normal">· from agent</em></label>
            <input class="bkv2-nb-input" type="text" placeholder="e.g. AT-VC-25060042" value="${escapeHTML(d.voucherRef||'')}" oninput="bkV2SetBookingField('voucherRef', this.value);bkV2VoucherLiveCheck(this.value)">
            <div id="bkv2-voucher-dup-warn" style="margin-top:4px">${(typeof bkV2VoucherDupHtml==='function')?bkV2VoucherDupHtml(d.voucherRef||''):''}</div>
          </div>
        </div>
        <div class="bkv2-nb-row" style="grid-template-columns:${isHouse?'1fr 1fr 1fr 1fr':'1fr 1fr 1fr'}">
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Booking date <em style="font-weight:500;color:#b4b2a9;font-style:normal">· default today</em></label>
            <input class="bkv2-nb-input" type="date" value="${escapeHTML(d.bookingDate||new Date().toISOString().slice(0,10))}" onchange="bkV2SetBookingField('bookingDate', this.value)">
          </div>
          ${isWalkin ? `<div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Sold by <em style="font-weight:500;color:#b4b2a9;font-style:normal">· sales credit</em></label>
            <select class="bkv2-nb-input" onchange="bkV2SetBookingField('soldBy', this.value)"><option value="">— select sales —</option>${(typeof SB_SALES!=='undefined'?SB_SALES:[]).map(s=>`<option value="${s.id}" ${d.soldBy===s.id?'selected':''}>${escapeHTML(s.name)}</option>`).join('')}</select>
          </div>` : ''}
          ${isStaff ? (function(){ const yr=(d.bookingDate||'').slice(0,4)||String(new Date().getFullYear()); const sp=d.staffPurpose||'welfare'; const rem=d.staffId?staffRemaining(d.staffId,yr):null;
            return `<div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Purpose <em style="font-weight:500;color:#b4b2a9;font-style:normal">· staff trip</em></label>
            <select class="bkv2-nb-input" onchange="bkV2SetBookingField('staffPurpose', this.value)"><option value="welfare" ${sp==='welfare'?'selected':''}>สวัสดิการ · Welfare (ใช้โควต้า)</option><option value="inspection" ${sp==='inspection'?'selected':''}>ตรวจงาน · Inspection (ไม่ใช้โควต้า)</option></select>
          </div>
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Staff member <em style="font-weight:500;color:#b4b2a9;font-style:normal">· ${sp==='inspection'?'inspection':'welfare'}</em></label>
            <select class="bkv2-nb-input" onchange="bkV2SetBookingField('staffId', this.value)"><option value="">— select staff —</option>${(typeof SB_STAFF!=='undefined'?SB_STAFF:[]).filter(s=>s.active).map(s=>`<option value="${s.id}" ${d.staffId===s.id?'selected':''}>${escapeHTML(s.name||s.code)}</option>`).join('')}</select>
            ${d.staffId&&sp==='welfare'?`<div style="font-size:10.5px;margin-top:3px;color:${rem<=0?'#A32D2D':'#0F6E56'}">โควต้าฟรีเหลือ ${rem} ที่นั่ง (ปี ${yr})</div>`:''}
            ${sp==='welfare'?`<div style="font-size:10px;margin-top:3px;color:#8a8a82;line-height:1.4">ใช้สิทธิ์ฟรี → ใส่เป็น <b>FOC</b> (หักโควต้า) · เกินโควต้า/จ่ายเงิน → ใส่เป็น <b>ผู้ใหญ่/เด็ก</b> คิดตามเรท <b>Staff Welfare</b></div>`:''}
            ${sp==='inspection'?`<div style="font-size:10.5px;margin-top:3px;color:#6c5ce7">ตรวจงาน · นับที่นั่งใน manifest · ไม่หักโควต้า</div>`:''}
          </div>`; })() : ''}
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Submitted by</label>
            <input class="bkv2-nb-input" type="text" placeholder="name / initials" value="${escapeHTML(d.createdBy||'')}" oninput="bkV2SetBookingField('createdBy', this.value)">
          </div>
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Confirmed by <span style="font-weight:400;color:#9aa">· auto = ผู้ล็อกอิน</span></label>
            <input class="bkv2-nb-input" type="text" placeholder="auto = ผู้ล็อกอิน" value="${escapeHTML(d.confirmedBy||'')}" oninput="bkV2SetBookingField('confirmedBy', this.value)">
          </div>
        </div>
        ${rtPreview}
        ${isHouse ? `<div style="margin-top:10px;display:flex;align-items:center;gap:12px;flex-wrap:wrap">
          <span class="bkv2-nb-label" style="margin:0">Pricing</span>
          <div style="display:inline-flex;gap:3px;background:var(--sand-mid);border-radius:9px;padding:3px">
            <button type="button" onclick="bkV2SetBookingField('priceMode','rate')" style="border:none;border-radius:7px;padding:5px 12px;font-size:11px;font-weight:600;cursor:pointer;font-family:inherit;${d.priceMode!=='manual'?'background:var(--bk-navy);color:#fff':'background:transparent;color:var(--ink-soft)'}">Rate type</button>
            <button type="button" onclick="bkV2SetBookingField('priceMode','manual')" style="border:none;border-radius:7px;padding:5px 12px;font-size:11px;font-weight:600;cursor:pointer;font-family:inherit;${d.priceMode==='manual'?'background:var(--bk-navy);color:#fff':'background:transparent;color:var(--ink-soft)'}">Manual · walk-in</button>
          </div>
          ${d.priceMode==='manual' ? `<div style="display:flex;align-items:center;gap:6px"><span class="bkv2-nb-label" style="margin:0">Total &#3647;</span><input class="bkv2-nb-input" type="number" min="0" style="width:130px" value="${escapeHTML(String(d.manualTotal||0))}" onchange="bkV2SetBookingField('manualTotal', this.value)"></div>` : ''}
        </div>` : ''}
      </div>

      ${bkV2HasAvailableAddOns() ? `
        <div class="bkv2-nb-sec">
          <div style="display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:20px">
            <div>
              <div class="bkv2-nb-sec-h">&#9679; Trips &amp; Pax</div>
              ${bkV2RenderTripsSection()}
            </div>
            <div>
              <div class="bkv2-nb-sec-h">&#9679; Add-ons</div>
              ${bkV2RenderAddOnsSection()}
            </div>
          </div>
        </div>
      ` : `
        <div class="bkv2-nb-sec">
          <div class="bkv2-nb-sec-h">&#9679; Trips &amp; Pax</div>
          ${bkV2RenderTripsSection()}
        </div>
      `}

      <div class="bkv2-nb-sec">
        <div class="bkv2-nb-sec-h">&#9679; Guests <em style="font-weight:500;color:#b4b2a9;font-style:normal;font-size:11px;text-transform:none;letter-spacing:0">&middot; lead + auto-sized to Adult pax</em><button type="button" onclick="bkV2GroupPasteOpen()" title="Paste a whole group (30-40 pax) at once" style="margin-left:auto;display:inline-flex;align-items:center;gap:5px;background:#E6F1FB;color:#185FA5;border:1px solid #C5D8EA;border-radius:8px;font-family:inherit;font-size:11px;font-weight:600;padding:5px 11px;cursor:pointer;text-transform:none;letter-spacing:0">&#128203; Paste group list</button></div>
        <!-- Unified guest table · Lead = #1 with badge · additional passengers #2+ -->
        <div style="background:#fafafa;border:1px solid var(--border);border-radius:var(--r-sm);overflow:visible">
          <table style="width:100%;border-collapse:collapse;table-layout:fixed">
            <colgroup>
              <col style="width:38px">
              <col>
              <col style="width:180px">
              <col style="width:62px">
            </colgroup>
            <thead><tr style="background:#f5f3ef">
              <th style="padding:6px;text-align:left;font-size:9px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em">#</th>
              <th style="padding:6px;text-align:left;font-size:9px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em">Full Name</th>
              <th style="padding:6px;text-align:left;font-size:9px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em">Nationality</th>
              <th style="padding:6px;text-align:center;font-size:9px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em"></th>
            </tr></thead>
            <tbody>
              <!-- Lead pax row (#1) -->
              <tr style="background:var(--bk-navy-50)">
                <td style="padding:6px 6px;vertical-align:middle">
                  <div style="font-family:'DM Mono',monospace;font-size:10px;color:var(--bk-navy);font-weight:700;line-height:1.1">#1</div>
                  <div style="background:var(--bk-navy);color:#fff;font-size:7px;font-weight:700;padding:1px 4px;border-radius:2px;letter-spacing:.08em;display:inline-block;margin-top:2px">LEAD</div>
                  ${(d.leadType&&d.leadType!=='AD')?`<div style="background:${d.leadType==='FOC'?'#FCE9B5':'#E6F1FB'};color:${d.leadType==='FOC'?'#7A5A12':'#185FA5'};font-size:7px;font-weight:700;padding:1px 4px;border-radius:2px;letter-spacing:.06em;display:inline-block;margin-top:2px">${d.leadType}</div>`:''}
                  ${((d.trips||[]).some(t=>bkV2PaxTot(t.pax,'foc')>0))?`<div onclick="event.stopPropagation();bkV2ToggleLeadFoc()" title="${d.leadFoc?'Lead เป็น FOC · คลิกเพื่อยกเลิก':'ตั้ง Lead เป็น FOC (ฟรี · ไม่ต้องมี Adult)'}" style="cursor:pointer;font-size:13px;line-height:1;margin-top:3px;color:${d.leadFoc?'#D9A400':'#cfcabd'}">${d.leadFoc?'★':'☆'} <span style="font-size:7px;color:#a8a59e;vertical-align:1px;letter-spacing:.04em">FOC</span></div>`:''}
                </td>
                <td style="padding:5px 6px">
                  <input class="bkv2-nb-input" type="text" placeholder="Lead pax name *" value="${escapeHTML(d.leadPax)}" oninput="bkV2SetBookingField('leadPax', this.value)" onblur="bkV2Render()" style="padding:6px 8px;font-size:12px;width:100%;box-sizing:border-box">
                </td>
                <td style="padding:5px 6px">
                  <div class="bkv2-nb-ddwrap">
                    <input id="bkv2-nat-input-lead" class="bkv2-nb-input" type="text" placeholder="Type or pick…" autocomplete="off" value="${d.leadNationality ? escapeHTML(bkV2NatDDLabel(d.leadNationality)) : ''}" oninput="bkV2NatDDFilter('lead', this.value)" onfocus="bkV2NatDDShow('lead')" onkeydown="bkV2NatDDKey(event,'lead')" onblur="bkV2NatDDBlur('lead')" style="padding:6px 8px;font-size:12px;width:100%;box-sizing:border-box">
                    <div id="bkv2-nat-dd-lead" class="bkv2-nb-dd"></div>
                  </div>
                </td>
                <td style="padding:5px 6px;text-align:center">${d.leadNationality && bkV2GuessNationality(d.leadPax||'') === d.leadNationality ? '<span style="background:#E1F5EE;color:#0F6E56;font-size:8px;padding:1px 5px;border-radius:3px;font-weight:600;letter-spacing:.06em">GUESS</span>' : ''}</td>
              </tr>
              <!-- Lead contact sub-row · phone + email -->
              <tr style="background:var(--bk-navy-50);border-bottom:1px solid var(--bk-navy-light)">
                <td></td>
                <td colspan="3" style="padding:0 6px 8px">
                  <div style="display:grid;grid-template-columns:1fr 1.6fr;gap:8px;margin-top:-2px">
                    <input class="bkv2-nb-input" type="text" placeholder="📞 Phone · +66 ..." value="${escapeHTML(d.leadPhone)}" oninput="bkV2SetBookingField('leadPhone', this.value)" style="padding:5px 8px;font-size:11px;box-sizing:border-box">
                    <input class="bkv2-nb-input" type="email" placeholder="✉️ Email · lead@example.com" value="${escapeHTML(d.leadEmail)}" oninput="bkV2SetBookingField('leadEmail', this.value)" style="padding:5px 8px;font-size:11px;box-sizing:border-box">
                  </div>
                </td>
              </tr>
              ${bkV2RenderPassengerRows()}
            </tbody>
          </table>
        </div>
      </div>

      <div class="bkv2-nb-sec">
        <div class="bkv2-nb-sec-h">&#9679; Pickup &amp; Drop-off</div>
        ${bkV2RenderPickupSection()}
      </div>

      <!-- Combined: Dietary + Guides in ONE card -->
      <div class="bkv2-nb-sec">
        <div class="bkv2-nb-sec-h">&#9679; Dietary, Luggage &amp; Guides</div>
        ${bkV2RenderDietaryLuggageSection()}
        <div style="height:1px;background:var(--border);margin:14px 0 12px"></div>
        ${(() => {
          const g = d.guides || { english:false, russian:false, chinese:false, otherLang:'' };
          const guidePill = (key, on, lbl, flagSvg) =>
            `<label style="display:inline-flex;align-items:center;gap:7px;padding:6px 12px;background:${on?'#E1F5EE':'var(--white)'};border:1px solid ${on?'#9FE1CB':'var(--border)'};border-radius:14px;cursor:pointer;font-size:11.5px;font-weight:600;color:${on?'#0F6E56':'var(--ink-soft)'}"><input type="checkbox" ${on?'checked':''} onchange="bkV2ToggleGuide('${key}',this.checked)" style="accent-color:#0F6E56;margin:0;width:14px;height:14px">${flagSvg}<span>${lbl}</span></label>`;
          return `
            <div style="display:flex;flex-wrap:wrap;align-items:center;gap:7px;margin-bottom:10px">
              <span style="font-size:10px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin-right:3px">Guide</span>
              ${guidePill('english', g.english, 'English', bkV2FlagSVG('uk'))}
              ${guidePill('russian', g.russian, 'Russian', bkV2FlagSVG('ru'))}
              ${guidePill('chinese', g.chinese, 'Chinese', bkV2FlagSVG('cn'))}
              <input type="text" placeholder="+ other language…" value="${(g.otherLang||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c])}" oninput="bkV2SetGuideOther(this.value)" style="flex:1;min-width:140px;padding:6px 12px;font-family:inherit;font-size:11.5px;background:var(--white);border:1px solid var(--border);border-radius:14px;color:var(--ink)">
            </div>
          `;
        })()}
        <label class="bkv2-nb-label">Notes / Special Request</label>
        <textarea class="bkv2-nb-input" rows="3" placeholder="e.g. VIP family · prefers speedboat · notify guide for life vest sizes" style="width:100%;box-sizing:border-box;font-family:inherit;resize:vertical;margin-top:4px" oninput="bkV2SetBookingField('notes', this.value)">${(d.notes||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c])}</textarea>
      </div>

      <!-- Combined: Payment + Cash on Tour in ONE card -->
      ${bkV2RenderPaymentSection()}

      ${bkV2RenderFocSection()}

       </div>
       <div class="bkv2-review-cell">
         <div class="bkv2-review-sticky">
           <div class="bkv2-review-inner">
             <div class="bkv2-nb-sec-h" style="margin-bottom:10px;color:var(--bk-navy)">&#9679; Booking Review</div>
             ${bkV2RenderReviewPanel()}
             <div style="height:1px;background:var(--border);margin:14px 0 12px"></div>
             ${bkV2RenderAttachSection()}
             <div style="margin-bottom:10px">${bkV2RenderActionMeta()}</div>
             <div style="display:flex;flex-direction:column;gap:6px">
               ${bkV2RenderSubmitButton()}
               <button class="bkv2-nb-btn" onclick="bkV2SaveDraft()" ${!d.agentId?'disabled':''} style="width:100%">Save Draft</button>
               <button class="bkv2-nb-btn ghost" onclick="bkV2CloseNewBooking()" style="width:100%">Cancel</button>
             </div>
           </div>
         </div>
       </div>
      </div>
      ${bkV2RenderCharterConfirmModal()}
    </div>
  `;
}

// ── Render sub-sections ──
function bkV2RenderPickupSection(){
  const d = _bkV2.newBooking;
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  // Group areas by zone
  const grouped = {};
  (SB_PICKUP_AREAS||[]).forEach(a => {
    if(!grouped[a.zone]) grouped[a.zone] = [];
    grouped[a.zone].push(a);
  });
  const zoneLabel = z => z==='PK'?'PK · Phuket':z==='KL'?'KL · Khao Lak':'No Transfer';
  // Flat list for datalist · prefix area name with zone label
  const areaFlat = ['PK','KL','NoTransfer'].filter(z => grouped[z]?.length).flatMap(z => grouped[z].map(a => ({ id:a.id, label:`[${zoneLabel(z)}] ${a.name}` })));
  const areaDataList = areaFlat.map(o => `<option value="${escapeHTML(o.label)}"></option>`).join('');
  const labelFromId = (aid) => {
    if(!aid) return '';
    const a = bkV2GetArea(aid);
    if(!a) return '';
    return `[${zoneLabel(a.zone)}] ${a.name}`;
  };
  const pickupLabel = labelFromId(d.pickupAreaId);
  const dropoffLabel = labelFromId(d.dropoffAreaId);
  const area = bkV2GetArea(d.pickupAreaId);
  // Private Van → real hotel pickup (NOT self-arrive) even though the SEAT is No-Transfer
  const _hasPrivVan = (d.trips||[]).some(t => bkV2TripPrivateVan(d, t));
  const _pickIsNT = !_hasPrivVan && ((area && (area.zone==='NoTransfer'||area.zone==='NT')) || d.pickupZoneFilter==='NoTransfer');
  const dropoffArea = bkV2GetArea(d.dropoffAreaId);

  // Per-trip pickup time table
  let pickupTimeRows = '';
  if(area && d.trips.some(t => t.routeId)){
    pickupTimeRows = d.trips.filter(t => t.routeId).map((t, idx) => {
      const autoTime = bkV2GetPickupTime(t.routeId, d.pickupAreaId, t.date);
      const displayTime = t.pickupTime || autoTime || '';
      const isEdited = t.pickupTimeEdited;
      const routeName = (typeof ROUTES!=='undefined' && ROUTES.find(r=>r.id===t.routeId)?.name) || t.routeId;
      const tripIdx = d.trips.indexOf(t);
      return `
        <tr>
          <td style="padding:6px 0;font-family:'DM Mono',monospace;font-size:10px;color:var(--ink-soft)">${t.date||'—'}</td>
          <td style="padding:6px 8px;font-size:11px">${escapeHTML(routeName)}</td>
          <td style="padding:6px 0;text-align:right">
            <input type="text" value="${escapeHTML(displayTime)}" style="font-family:'DM Mono',monospace;font-size:11px;font-weight:700;color:var(--bk-navy);background:transparent;border:1px solid transparent;border-radius:3px;padding:3px 6px;width:120px;text-align:right" onchange="bkV2SetTripPickupTime(${tripIdx}, this.value)" placeholder="—">
            ${displayTime ? (isEdited
              ? `<span style="background:#FAEEDA;color:#633806;font-size:8px;padding:1px 5px;border-radius:3px;font-weight:600;margin-left:4px">EDITED</span> <button onclick="bkV2ResetTripPickupTime(${tripIdx})" style="background:none;border:none;color:var(--ink-soft);font-size:9px;cursor:pointer;text-decoration:underline">reset</button>`
              : `<span style="background:#E1F5EE;color:#0F6E56;font-size:8px;padding:1px 5px;border-radius:3px;font-weight:600;margin-left:4px">AUTO</span>`) : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  return `
    <!-- Row 1: ZONE pills (left, narrow) + PICKUP AREA input (right, filtered) -->
    <div class="bkv2-nb-row" style="grid-template-columns:auto minmax(0,1fr)">
      <div class="bkv2-nb-field">
        <label class="bkv2-nb-label">Zone <em style="font-weight:500;color:#b4b2a9;font-style:normal">· from trip above</em></label>
        ${(() => {
          const tripsZones = [...new Set((d.trips||[]).filter(t => t.zone).map(t => bkV2EffZone(d, t)))];   // private van → its pickup zone, not the No-Transfer seat
          const effectiveZone = tripsZones[0] || d.pickupZoneFilter || 'PK';
          const zoneLbl = (z) => z==='PK'?'PK · Phuket' : z==='KL'?'KL · Khao Lak' : 'No Transfer';
          const mixed = tripsZones.length > 1;
          return `<div style="padding:8px 12px;background:var(--white);border:1px solid var(--border);border-radius:var(--r-sm);font-size:12px;font-weight:600;color:var(--ink);display:flex;align-items:center;gap:7px;height:34px;box-sizing:border-box">
            <span style="flex:1">${zoneLbl(effectiveZone)}${mixed?` <span style="font-size:9px;color:#a32d2d;font-weight:600;margin-left:4px">⚠ trips have mixed zones</span>`:''}</span>
          </div>`;
        })()}
      </div>
      <div class="bkv2-nb-field">
        <label class="bkv2-nb-label">Pickup area * <em style="font-weight:500;color:#b4b2a9;font-style:normal">· type to search</em></label>
        ${(d.pickupZoneFilter==='NoTransfer' && d.pickupAreaId)
          ? `<div style="padding:8px 11px;background:#E1F5EE;border:1px solid #9FE1CB;border-radius:var(--r-sm);font-size:12px;color:#0F6E56;font-weight:600;height:34px;display:flex;align-items:center;gap:7px;box-sizing:border-box"><span style="font-size:11px">✓ AUTO</span><span style="font-family:'DM Mono',monospace;font-size:11px">${escapeHTML(pickupLabel)}</span></div>`
          : `<div class="bkv2-nb-ddwrap">
              <input id="bkv2-area-input-pickup" class="bkv2-nb-input" type="text" placeholder="Type or pick an area..." value="${escapeHTML(pickupLabel)}" autocomplete="off" oninput="bkV2AreaDDFilter('pickup', this.value)" onfocus="bkV2AreaDDShow('pickup')" onkeydown="bkV2AreaDDKey(event, 'pickup')">
              <div id="bkv2-area-dd-pickup" class="bkv2-nb-dd"></div>
            </div>`}
      </div>
    </div>
    ${area ? `
      <!-- Row 2: Hotel / Pickup Location (wider) + Room # (narrower) on same line -->
      <div class="bkv2-nb-row" style="grid-template-columns:minmax(0,2.2fr) minmax(0,1fr)">
        <div class="bkv2-nb-field">
          <label class="bkv2-nb-label">${_pickIsNT?`Note <em style="font-weight:500;color:#b4b2a9;font-style:normal">· optional · self-arrival</em>`:`Hotel / Pickup Location`}</label>
          <div class="bkv2-nb-ddwrap" style="position:relative">
            <input id="bkv2-hotel-input" class="bkv2-nb-input" type="text" autocomplete="off" placeholder="${_pickIsNT?'optional note · guest arrives on their own':'e.g. Thavorn Beach Village · Patong main road · etc.'}" value="${escapeHTML(d.hotelName||'')}" oninput="bkV2HotelDDFilter(this.value)" onfocus="bkV2HotelDDShow()" onkeydown="bkV2HotelDDKey(event)">
            <div id="bkv2-hotel-dd" class="bkv2-nb-dd"></div>
          </div>
          ${pickupTimeRows ? `<div style="margin-top:6px;display:flex;flex-direction:column;gap:3px">
            ${d.trips.filter(t => t.routeId).map(t => {
              const autoTime = bkV2GetPickupTime(t.routeId, d.pickupAreaId, t.date);
              const displayTime = t.pickupTime || autoTime || '';
              const isEdited = t.pickupTimeEdited;
              const routeName = (typeof ROUTES!=='undefined' && ROUTES.find(r=>r.id===t.routeId)?.name) || t.routeId;
              if(!displayTime && !t.date) return '';
              return `<div style="display:flex;align-items:center;gap:10px;padding:4px 9px;background:#F4F8F5;border:1px solid #E5EDE7;border-radius:6px;font-size:11px">
                <span style="font-family:'DM Mono',monospace;color:var(--ink-soft);min-width:80px">${t.date || '—'}</span>
                <span style="flex:1;color:var(--ink);font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escapeHTML(routeName)}</span>
                <span style="font-family:'DM Mono',monospace;font-weight:700;color:#0F6E56">${displayTime || '—'}</span>
                ${displayTime ? `<span style="background:${isEdited?'#FAEEDA':'#DDF0E5'};color:${isEdited?'#633806':'#0F6E56'};font-size:8px;padding:1px 5px;border-radius:3px;font-weight:600;letter-spacing:.06em">${isEdited?'EDITED':'AUTO'}</span>` : ''}
              </div>`;
            }).join('')}
          </div>` : ''}
        </div>
        <div class="bkv2-nb-field">
          <label class="bkv2-nb-label">Room #</label>
          <input class="bkv2-nb-input" type="text" placeholder="A-205" value="${escapeHTML(d.roomNumber||'')}" oninput="bkV2SetBookingField('roomNumber', this.value)">
        </div>
      </div>
    ` : ''}
    <!-- Pickup time table moved inline under Hotel/Pickup Location · per request -->
    <label style="display:flex;align-items:center;gap:8px;padding:7px 11px;background:${d.pickupSelf?'#F6F2FE':'var(--white)'};border:1px solid ${d.pickupSelf?'#C7B8E8':'var(--border)'};border-radius:var(--r-sm);cursor:pointer;margin-top:10px">
      <input type="checkbox" ${d.pickupSelf?'checked':''} onchange="bkV2TogglePickupSelf()" style="accent-color:#5B289A">
      <span style="font-size:11px;color:${d.pickupSelf?'#5B289A':'var(--ink)'};font-weight:600">&#128694; ขารับ: ลูกค้ามาเองที่ท่าเรือ (self-arrive · เก็บเรทเต็ม)</span>
    </label>
    ${(d.pickupSelf && (d.hotelName||'').trim())?`<div style="margin-top:6px;padding:7px 11px;background:#FCEBEB;border:1px solid #F0C4C4;border-radius:var(--r-sm);font-size:10.5px;color:#A32D2D;line-height:1.45">&#9888; ติ๊ก self-arrive (ลูกค้ามาเอง) แต่กรอกโรงแรม "<b>${escapeHTML(d.hotelName)}</b>" ไว้ — booking นี้จะ<b>ไม่ขึ้นในใบงานรถขาไป</b> · ถ้าลูกค้าให้ไปรับที่โรงแรม อย่าติ๊กช่องนี้</div>`:''}
    <label style="display:flex;align-items:center;gap:8px;padding:7px 11px;background:${d.dropoffSame?'var(--bk-navy-50)':'var(--white)'};border:1px solid ${d.dropoffSame?'var(--bk-navy-mid)':'var(--border)'};border-radius:var(--r-sm);cursor:pointer;margin-top:10px">
      <input type="checkbox" ${d.dropoffSame?'checked':''} onchange="bkV2ToggleDropoffSame()" style="accent-color:var(--bk-navy)">
      <span style="font-size:11px;color:${d.dropoffSame?'var(--bk-navy)':'var(--ink)'};font-weight:600">Drop-off same as pickup</span>
    </label>
    ${!d.dropoffSame ? `
      <div class="bkv2-nb-row" style="margin-top:10px;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr)">
        <div class="bkv2-nb-field">
          <label class="bkv2-nb-label">Drop-off area <em style="font-weight:500;color:#b4b2a9;font-style:normal">· zone</em></label>
          <div class="bkv2-nb-ddwrap">
            <input id="bkv2-area-input-dropoff" class="bkv2-nb-input" type="text" placeholder="Type or pick an area..." value="${escapeHTML(dropoffLabel)}" autocomplete="off" oninput="bkV2AreaDDFilter('dropoff', this.value)" onfocus="bkV2AreaDDShow('dropoff')" onkeydown="bkV2AreaDDKey(event, 'dropoff')">
            <div id="bkv2-area-dd-dropoff" class="bkv2-nb-dd"></div>
          </div>
        </div>
        <div class="bkv2-nb-field">
          <label class="bkv2-nb-label">Drop-off Location</label>
          <input class="bkv2-nb-input" type="text" placeholder="e.g. Airport · Hotel name · Patong main road" value="${escapeHTML(d.dropoffHotelName||'')}" oninput="bkV2SetBookingField('dropoffHotelName', this.value)">
        </div>
      </div>
    ` : ''}
    ${(() => {
      // §altPickups · รับหลายจุดในบุคกิ้งเดียว (บางคนรับคนละที่กับ pickup หลัก)
      // แถวละ: เลือกชื่อ → เลือกจุดรับ (Pickup area · โซนเด้ง auto) → ใส่ชื่อ Location
      const alt = Array.isArray(d.altPickups) ? d.altPickups : [];
      const _zShort = z => z==='PK'?'PK · Phuket':z==='KL'?'KL · Khao Lak':z==='NoTransfer'?'No Transfer':'';
      // dropdown จุดรับ · จัดกลุ่มตามโซน (แหล่งเดียวกับ Pickup area หลัก)
      const areaOptGroups = ['PK','KL','NoTransfer'].filter(z=>grouped[z]&&grouped[z].length)
        .map(z=>`<optgroup label="${zoneLabel(z)}">${grouped[z].map(ar=>`<option value="${ar.id}">${escapeHTML(ar.name)}</option>`).join('')}</optgroup>`).join('');
      // รายชื่อจากส่วน Guests (lead + passengers ที่มีชื่อ) · ให้เลือก (พิมพ์เองได้ด้วย เช่น "2 คน")
      const guestNames = [...new Set([d.leadPax, ...((d.passengers)||[]).map(p=>p&&p.name)].map(s=>String(s||'').trim()).filter(Boolean))];
      const nameOpts = guestNames.map(n=>`<option value="${escapeHTML(n)}"></option>`).join('');
      // headcount ของกลุ่ม = ทริปที่คนเยอะสุด (แขกเป็นกลุ่มเดียวข้ามทริป) · ใช้คำนวณจำนวนที่จุดรับหลัก
      const _hc = (d.trips||[]).reduce((m,t)=>Math.max(m,(typeof bkV2PaxAllTot==='function'?bkV2PaxAllTot(t.pax||{}):0)),0);
      const _altTot = alt.reduce((s,a)=>s+bkPaxSum(bkAltPax(a)),0);
      const _mainQty = _hc - _altTot;
      // ยอดของบุ๊กกิ้งแยกประเภท (ทริปที่คนเยอะสุด) → เอาไว้เช็คว่าแยกเด็ก/ทารกเกินที่มีจริงไหม
      let _bkBd={ad:0,chd:0,inf:0,foc:0};
      (d.trips||[]).forEach(t=>{ const p=bkPaxOfTrip(t); if(bkPaxSum(p)>bkPaxSum(_bkBd)) _bkBd=p; });
      const _altBd = alt.reduce((acc,a)=>bkPaxAdd(acc,bkAltPax(a)), {ad:0,chd:0,inf:0,foc:0});
      const _mainBd = bkPaxSub(_bkBd,_altBd);
      const _badK = PAX_K.filter(k=>_altBd[k] > _bkBd[k]);   // แยกประเภทไหนเกินยอดที่มีจริง
      const _over = (_hc>0 && _altTot>_hc) || _badK.length>0;
      const _gcols = 'minmax(0,0.9fr) 206px minmax(0,1.05fr) minmax(0,1.05fr) auto';
      const rows = alt.map((a,i) => {
        const _ar = a.areaId ? bkV2GetArea(a.areaId) : null;
        const _zone = _ar ? _ar.zone : '';
        const _areaSel = areaOptGroups.replace(`<option value="${a.areaId}">`, `<option value="${a.areaId}" selected>`);
        const zoneChip = _zone
          ? `<div style="margin-top:3px"><span style="font-size:9px;font-weight:700;color:#5B289A;background:#EDE7FB;padding:1px 7px;border-radius:4px">โซน ${_zShort(_zone)} · auto</span></div>`
          : `<div style="margin-top:3px;font-size:9px;color:#b4b2a9;font-style:italic">เลือกจุดรับ → โซนมาอัตโนมัติ</div>`;
        return `
        <div class="bkv2-nb-row" style="grid-template-columns:${_gcols};align-items:start;gap:7px;margin-top:6px">
          <input class="bkv2-nb-input" list="bkv2-altpick-names" type="text" placeholder="เลือก/พิมพ์ชื่อ" value="${escapeHTML(a.who||'')}" oninput="bkV2SetAltPickup(${i},'who',this.value)">
          <div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px">${PAX_K.map(k=>{const _v=bkAltPax(a)[k]; const _bad=_altBd[k]>_bkBd[k]; return `<input class="bkv2-nb-input bkv2-pax-box" type="number" min="0" step="1" value="${_v}" onchange="bkV2SetAltPickupPax(${i},'${k}',this.value)" title="${PAX_LBL[k]} ที่จุดนี้ (กลุ่มนี้มีทั้งหมด ${_bkBd[k]})"${_bad?' style="border-color:#E0857E;background:#FDECEA"':(_v?'':' style="color:#c4c1b8"')}>`;}).join('')}</div>
          <div>
            <select class="bkv2-nb-input" onchange="bkV2SetAltPickupArea(${i},this.value)" style="cursor:pointer"><option value="">— เลือกจุดรับ —</option>${_areaSel}</select>
            ${zoneChip}
          </div>
          <input class="bkv2-nb-input" type="text" placeholder="ชื่อโรงแรม / Location" value="${escapeHTML(a.place||'')}" oninput="bkV2SetAltPickup(${i},'place',this.value)">
          <button onclick="bkV2RemoveAltPickup(${i})" title="ลบ" style="border:none;background:transparent;cursor:pointer;color:var(--ink-soft);font-size:16px;line-height:1;padding:6px 6px">&times;</button>
        </div>`; }).join('');
      const summary = alt.length ? `<div style="margin-top:9px;padding:7px 10px;border-radius:7px;background:${_over?'#FDECEA':'#F0EBFA'};border:1px solid ${_over?'#F5C9C4':'#DDD1F2'};font-size:10.5px;color:${_over?'#A32D2D':'#5B289A'};line-height:1.5">
        จุดรับหลัก (ด้านบน · รวม Lead): <b>${Math.max(0,_mainQty)} คน</b> <span style="opacity:.75">(${PAX_K.filter(k=>_mainBd[k]>0).map(k=>_mainBd[k]+' '+PAX_LBL[k]).join(' · ')||'—'})</span>
        &nbsp;·&nbsp; แยกไปจุดอื่น: <b>${_altTot} คน</b> <span style="opacity:.75">(${PAX_K.filter(k=>_altBd[k]>0).map(k=>_altBd[k]+' '+PAX_LBL[k]).join(' · ')||'—'})</span>
        &nbsp;·&nbsp; กลุ่มทั้งหมด: <b>${_hc} คน</b> <span style="opacity:.75">(${PAX_K.filter(k=>_bkBd[k]>0).map(k=>_bkBd[k]+' '+PAX_LBL[k]).join(' · ')||'—'})</span>
        ${_badK.length?('<div style="margin-top:3px">&#9888; แยก '+_badK.map(k=>PAX_LBL[k]+' '+_altBd[k]+' คน แต่กลุ่มนี้มี '+_bkBd[k]).join(' · ')+'</div>'):(_hc>0&&_altTot>_hc?('<div style="margin-top:3px">&#9888; แยกเกินจำนวนกลุ่ม ('+_altTot+'>'+_hc+')</div>'):'')}
      </div>` : '';
      return `
        <datalist id="bkv2-altpick-names">${nameOpts}</datalist>
        <div style="margin-top:10px;padding:9px 11px;background:${alt.length?'#F6F2FE':'var(--white)'};border:1px solid ${alt.length?'#C7B8E8':'var(--border)'};border-radius:var(--r-sm)">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
            <span style="font-size:11px;color:${alt.length?'#5B289A':'var(--ink)'};font-weight:600">&#128652; รับหลายจุด (บางคนรับคนละที่)${alt.length?` · ${alt.length} จุด`:''}</span>
            <button onclick="bkV2AddAltPickup()" style="font-size:11px;font-weight:600;color:#5B289A;background:#EDE7FB;border:1px solid #C7B8E8;border-radius:6px;padding:4px 10px;cursor:pointer;font-family:inherit">+ เพิ่มจุดรับ</button>
          </div>
          ${alt.length?`<div style="display:grid;grid-template-columns:${_gcols};gap:7px;margin-top:8px;font-size:8.5px;font-weight:700;letter-spacing:.05em;color:#8a7db0;text-transform:uppercase"><span>ชื่อ (จากรายชื่อด้านบน)</span><span style="text-align:center">AD · CHD · INF · FOC</span><span>จุดรับ · Pickup area</span><span>ชื่อโรงแรม / Location</span><span></span></div>`:''}
          ${rows}
          ${summary}
          ${alt.length?'<div style="font-size:9.5px;color:#8a7db0;margin-top:6px">จุดรับหลักด้านบน = คนส่วนใหญ่ (รวม Lead) · รายการนี้ = คนที่รับคนละที่ · โซนมาจากจุดรับที่เลือกอัตโนมัติ · จำนวน "จุดรับหลัก" คำนวณอัตโนมัติ = กลุ่มทั้งหมด − ที่แยกไป</div>':''}
        </div>`;
    })()}
  `;
}

function bkV2RenderTripsSection(){
  const d = _bkV2.newBooking;
  const rt = bkV2GetRT();
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);

  if(!rt){
    // §b2cEdit · ใบ B2C ไม่มี Rate Type และไม่ควรมี · แสดงทริปจริงแบบอ่านอย่างเดียว
    if(typeof bkV2IsB2CBk==='function' && bkV2IsB2CBk(d)) return bkV2RenderB2CTripsRO(d);
    return `<div style="font-size:12px;color:var(--ink-soft);font-style:italic;padding:12px 0">Pick an agent first to enable trip selection.</div>`;
  }

  // Routes covered by this rate type · with full name
  const coveredRoutes = (rt.routes || []).map(rid => {
    const r = (typeof ROUTES !== 'undefined') ? ROUTES.find(rr => rr.id === rid) : null;
    return r ? { id:rid, name:r.name } : null;
  }).filter(Boolean);

  const zones = ['PK', 'KL', 'NoTransfer'];
  const zoneLabel = z => z === 'PK' ? 'PK · Phuket' : z === 'KL' ? 'KL · Khao Lak' : 'No transfer';

  // Compact pax stepper · used in 2x4 mixed grid
  const stepper = (idx, key, val) => `
    <div style="display:inline-flex;align-items:center;gap:1px;background:var(--white);border:1px solid var(--border);border-radius:999px;padding:1px 2px">
      <button onclick="bkV2BumpPax(${idx},'${key}',-1)" style="width:18px;height:18px;border:none;background:transparent;color:var(--ink-soft);font-weight:700;cursor:pointer;font-family:inherit;font-size:12px;line-height:1;padding:0;border-radius:50%">&minus;</button>
      <span style="min-width:17px;text-align:center;font-family:'DM Mono',monospace;font-weight:700;font-size:11px;font-variant-numeric:tabular-nums;color:${val>0?'var(--ink)':'#c7c5bb'}">${val}</span>
      <button onclick="bkV2BumpPax(${idx},'${key}',1)" style="width:18px;height:18px;border:none;background:transparent;color:var(--ink-soft);font-weight:700;cursor:pointer;font-family:inherit;font-size:12px;line-height:1;padding:0;border-radius:50%">+</button>
    </div>
  `;

  // Bundle helper · detect free/paid longtail bundle for a route
  const bundleInfo = (rId) => {
    const b = rt.routeBundles?.[rId]?.longtail;
    if(!b) return null;
    return { mode: b.mode, adult: b.adult||0, child: b.child||0 };
  };
  const routeDataList = coveredRoutes.map(r => `<option value="${escapeHTML(r.name)}"></option>`).join('');
  const tripRows = d.trips.map((t, idx) => {
    const subtotal = bkV2TripSubtotal(t);
    const totAd  = bkV2PaxTot(t.pax,'ad');
    const totChd = bkV2PaxTot(t.pax,'chd');
    const totInf = bkV2PaxTot(t.pax,'inf');
    const totFoc = bkV2PaxTot(t.pax,'foc');
    const currentRouteLabel = t.routeId ? (coveredRoutes.find(r=>r.id===t.routeId)?.name || '') : '';
    const bi = (t.routeId && _rtBundleAppliesTo(rt.routeBundles?.[t.routeId]?.longtail, t.bookingMode==='charter')) ? bundleInfo(t.routeId) : null;
    const bundleBadge = bi
      ? (bi.mode === 'free'
          ? `<div style="margin-top:6px;padding:5px 9px;background:#E1F5EE;border:1px solid #B8E5D2;border-radius:var(--r-sm);font-size:10px;color:#0F6E56;font-weight:700;display:flex;align-items:center;gap:6px"><span style="background:#0F6E56;color:#fff;padding:1px 5px;border-radius:3px;font-size:9px;letter-spacing:.06em">BUNDLED</span>Longtail Join included (free) · auto-applied</div>`
          : `<div style="margin-top:6px;padding:5px 9px;background:#FFF6E5;border:1px solid #EAD9B0;border-radius:var(--r-sm);font-size:10px;color:#633806;font-weight:700;display:flex;align-items:center;gap:6px"><span style="background:#ba7517;color:#fff;padding:1px 5px;border-radius:3px;font-size:9px;letter-spacing:.06em">BUNDLED</span>Longtail Join · auto +฿${bi.adult}/A &middot; +฿${bi.child}/C</div>`)
      : '';
    // Allotment status badge · only if route + date selected
    let allotBadge = '';
    if(t.routeId && t.date && typeof getAllotment === 'function'){
      const al = getAllotment(t.routeId, t.date, _bkV2.editingId || null);   // exclude this booking's own seats when editing
      const totPaxThisTrip = bkV2PaxAllTot(t.pax);
      const styles = {
        'open':          { bg:'#E1F5EE', border:'#B8E5D2', color:'#0F6E56', tag:'OPEN'  },
        'tight':         { bg:'#FFF6E5', border:'#EAD9B0', color:'#A05A1A', tag:'TIGHT' },
        'full':          { bg:'#FDE7E7', border:'#F5B7B7', color:'#a32d2d', tag:'FULL'  },
        'all-chartered': { bg:'#F4E8FB', border:'#D7B5F0', color:'#6B289A', tag:'CHARTERED' },
        'no-allotment':  { bg:'#fafafa', border:'#d3d1c7', color:'#5A5A52', tag:'PROVISIONAL', dashed:true }
      };
      const s = styles[al.state] || styles['no-allotment'];
      let msg = '';
      if(al.state === 'open' || al.state === 'tight'){
        msg = `<strong style="font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">${al.seatsAvailable}</strong> seat${al.seatsAvailable===1?'':'s'} available · ${al.assignedBoats.length} boat${al.assignedBoats.length===1?'':'s'} (${al.seatsConsumed}/${al.availableCapacity} booked${al.charteredBoats.length?` · ${al.charteredBoats.length} chartered`:''})`;
      } else if(al.state === 'full'){
        msg = `Sold out · all ${al.availableCapacity} seats booked. Ask dispatcher to add more boats in Boat Operation.`;
      } else if(al.state === 'all-chartered'){
        msg = `All ${al.assignedBoats.length} boat${al.assignedBoats.length===1?'':'s'} chartered for this date · no seats available.`;
      } else {
        msg = `No boat assigned yet · this booking will be <strong>provisional</strong>. Confirmed once dispatcher assigns a boat in Boat Operation.`;
      }
      // Over-capacity warning if pax exceeds available
      let warn = '';
      if(al.hasAllotment && totPaxThisTrip > al.seatsAvailable && totPaxThisTrip > 0){
        warn = `<div style="margin-top:4px;padding:4px 8px;background:#FDE7E7;color:#a32d2d;border:1px solid #F5B7B7;border-radius:3px;font-size:10px;font-weight:600">⚠ Over capacity · ${totPaxThisTrip} pax requested · only ${al.seatsAvailable} seat${al.seatsAvailable===1?'':'s'} left. Booking can be saved but needs dispatcher action.</div>`;
      }
      allotBadge = `<div style="margin-top:6px;padding:5px 9px;background:${s.bg};border:${s.dashed?'1px dashed':'1px solid'} ${s.border};border-radius:var(--r-sm);font-size:10px;color:${s.color};font-weight:600;display:flex;align-items:center;gap:6px;flex-wrap:wrap"><span style="background:${s.color};color:#fff;padding:1px 5px;border-radius:3px;font-size:9px;letter-spacing:.06em;font-weight:700;flex-shrink:0">${s.tag}</span><span style="flex:1;min-width:0">${msg}</span></div>${warn}`;
    }
    const isCharter = t.bookingMode === 'charter';
    // Charter boat picker · only boats assigned to route+date · filter availability
    let charterPickerHtml = '';
    if(isCharter && t.routeId && t.date && typeof getAssignedBoatsForRouteDate === 'function'){
      const assigned = getAssignedBoatsForRouteDate(t.routeId, t.date);
      const charterRatesByType = rt.charterRates?.[t.routeId] || {};
      const opts = assigned.map(a => {
        const bt = (a.boat?.type || '').toLowerCase();
        const hasCharterRate = !!charterRatesByType[bt];
        const alreadyChartered = !!a.charterBookingId;
        // seats currently booked on this boat (cannot derive per-boat directly · check route+date seatsConsumed > 0)
        const hasSeats = (typeof getSeatsConsumed === 'function') && getSeatsConsumed(t.routeId, t.date) > 0;
        let label = `${a.boat.name} · ${a.boat.cap} cap · ${a.boat.type}`;
        let disabled = false;
        let note = '';
        if(alreadyChartered){ note = ' · ALREADY CHARTERED'; disabled = true; }
        else if(!hasCharterRate){ note = ' · no charter rate set'; disabled = true; }
        else if(hasSeats){ note = ' · has existing seat bookings (will need confirm)'; }
        return `<option value="${a.boatId}" ${t.charterBoatId===a.boatId?'selected':''} ${disabled?'disabled':''}>${escapeHTML(label+note)}</option>`;
      }).join('');
      const noBoats = assigned.length === 0;
      const noAvailable = assigned.length > 0 && !assigned.some(a => !a.charterBookingId && charterRatesByType[(a.boat?.type||'').toLowerCase()]);
      charterPickerHtml = `
        <div class="bkv2-nb-row" style="margin-top:8px">
          <div class="bkv2-nb-field" style="grid-column:1/-1">
            <label class="bkv2-nb-label">Charter boat <em style="font-weight:500;color:#b4b2a9;font-style:normal">· pick from boats assigned in Boat Operation</em></label>
            ${noBoats ? `<div style="padding:8px 11px;background:#FFF6E5;border:1px dashed #EAD9B0;color:#633806;font-size:11px;border-radius:var(--r-sm)">No boat assigned for this route+date yet · go to Boat Operation to assign first</div>` :
              noAvailable ? `<div style="padding:8px 11px;background:#FDE7E7;border:1px solid #F5B7B7;color:#a32d2d;font-size:11px;border-radius:var(--r-sm)">All assigned boats are chartered or have no charter rate set</div>` :
              `<select class="bkv2-nb-input" onchange="bkV2SetTripCharterBoat(${idx}, this.value || null)">
                <option value="">&mdash; pick a boat &mdash;</option>
                ${opts}
              </select>`}
          </div>
        </div>
      `;
    }
    // Charter price · Rate (auto) or Flexible (manual) · when charter mode + boat picked
    let charterBreakdownHtml = '';
    if(isCharter && subtotal.isCharter && t.charterBoatId && !subtotal.error){
      const totPax = bkV2PaxAllTot(t.pax);
      const manual = t.charterPriceMode === 'manual';
      const seg = `
        <div style="display:inline-flex;background:#fff;border:1px solid #D7B5F0;border-radius:5px;overflow:hidden">
          <button onclick="bkV2SetTripCharterPriceMode(${idx},'rate')" style="border:none;cursor:pointer;font-family:inherit;font-size:10px;font-weight:700;padding:3px 9px;background:${!manual?'#6B289A':'#fff'};color:${!manual?'#fff':'#6B289A'}">RATE</button>
          <button onclick="bkV2SetTripCharterPriceMode(${idx},'manual')" style="border:none;cursor:pointer;font-family:inherit;font-size:10px;font-weight:700;padding:3px 9px;background:${manual?'#6B289A':'#fff'};color:${manual?'#fff':'#6B289A'}">FLEXIBLE</button>
        </div>`;
      const body = manual ? `
          <div style="display:flex;align-items:center;gap:7px;margin-top:6px">
            <span style="font-size:11px;color:#6B289A;font-weight:600">Charter price ฿</span>
            <input type="number" min="0" value="${(Number(t.charterPriceManual)||0)||''}" onchange="bkV2SetTripCharterManual(${idx}, this.value)" placeholder="0" style="width:110px;font-size:13px;font-weight:700;padding:5px 8px;text-align:right;font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums;border:1px solid #D7B5F0;border-radius:5px">
            <span style="font-size:10px;color:${subtotal.manualDelta===0?'#6B289A':(subtotal.manualDelta<0?'#0F7A5A':'#A05A1A')}">rate ฿${subtotal.rateTotal.toLocaleString()}${subtotal.manualDelta!==0?` · ${subtotal.manualDelta<0?'&minus;':'+'}฿${Math.abs(subtotal.manualDelta).toLocaleString()}`:''}</span>
          </div>
          <input value="${escapeHTML(t.charterPriceNote||'')}" oninput="bkV2SetTripCharterNote(${idx}, this.value)" placeholder="Reason / note · e.g. repeat charter discount" style="margin-top:6px;width:100%;box-sizing:border-box;font-size:11px;padding:5px 8px;border:1px solid #D7B5F0;border-radius:5px;color:#6B289A">
      ` : `
          <div style="display:flex;justify-content:space-between;gap:6px;margin-top:6px"><span>Starter (first ${subtotal.starterIncludes} pax)</span><span style="font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">฿${subtotal.starterPrice.toLocaleString()}</span></div>
          ${subtotal.extras > 0 ? `<div style="display:flex;justify-content:space-between;gap:6px"><span>+ ${subtotal.extras} extra pax × ฿${subtotal.extraRate.toLocaleString()}</span><span style="font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">฿${subtotal.extraTotal.toLocaleString()}</span></div>` : ''}
          <div style="display:flex;justify-content:space-between;gap:6px;border-top:1px solid #D7B5F0;padding-top:3px;margin-top:3px;font-weight:700"><span>Total · ${totPax} pax</span><span style="font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">฿${subtotal.total.toLocaleString()}</span></div>
      `;
      charterBreakdownHtml = `
        <div style="margin-top:6px;padding:7px 10px;background:#F4E8FB;border:1px solid #D7B5F0;border-radius:var(--r-sm);font-size:10px;color:#6B289A;line-height:1.5">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:2px"><span style="font-weight:700;letter-spacing:.06em;font-size:9px">CHARTER PRICE</span><span style="margin-left:auto">${seg}</span></div>
          ${body}
        </div>
      `;
    } else if(isCharter && t.charterBoatId && subtotal.error){
      charterBreakdownHtml = `<div style="margin-top:6px;padding:6px 10px;background:#FDE7E7;color:#a32d2d;font-size:10px;border:1px solid #F5B7B7;border-radius:var(--r-sm)">⚠ ${escapeHTML(subtotal.error)} for this boat type · check Rate Type charter rates</div>`;
    }
    // ── Seat-lock draw banner (Step 3c · seat mode · pick which sub-group to draw from) ──
    let lockBannerHtml = '';
    if(!isCharter && t.routeId && t.date && d.agentId && typeof bkV2DrawSources==='function'){
      const srcs = bkV2DrawSources(t.routeId, t.date, d.agentId);
      const remTotal = srcs.reduce((s,x)=>s+x.remaining,0);
      if(remTotal > 0){
        const pax = bkV2PaxAllTot(t.pax);
        const sel = t.lockDrawSel || {};
        const drawnTot = srcs.reduce((s,x)=> s + Math.min(Number(sel[x.lockId])||0, x.remaining), 0);
        const general = Math.max(0, pax - drawnTot);
        const undrawn = pax>0 && drawnTot===0;   // has lock but hasn't used it → LOUD reminder
        const accent = undrawn ? '#B45309' : '#2952C8';
        const stepBtn = `width:22px;height:22px;border:1px solid ${undrawn?'#EAD9B0':'#C7D8F7'};background:#fff;border-radius:5px;cursor:pointer;color:${accent};font-weight:700`;
        const srcRows = srcs.map(x=>{
          const v = Math.min(Number(sel[x.lockId])||0, x.remaining);
          const canInc = drawnTot < pax && v < x.remaining;
          return `
            <div style="display:flex;align-items:center;gap:6px;margin-top:5px">
              <span style="font-size:10.5px;color:${accent};flex:1;min-width:120px">${escapeHTML(x.label)} <span style="opacity:.7">· เหลือ ${x.remaining}</span></span>
              <button onclick="bkV2SetTripLockDraw(${idx},'${x.lockId}',${Math.max(0,v-1)})" ${v<=0?'disabled':''} style="${stepBtn}">&minus;</button>
              <span style="font-family:Manrope,sans-serif;font-weight:800;color:${accent};min-width:18px;text-align:center;font-variant-numeric:tabular-nums">${v}</span>
              <button onclick="bkV2SetTripLockDraw(${idx},'${x.lockId}',${v+1})" ${canInc?'':'disabled'} style="${stepBtn}">+</button>
            </div>`;
        }).join('');
        lockBannerHtml = undrawn ? `
          <div style="margin-top:8px;padding:10px 12px;background:#FFF6E5;border:1.5px solid #E0A93B;border-radius:var(--r-sm);box-shadow:0 0 0 3px rgba(224,169,59,.15)">
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
              <span style="font-size:14px">⚠</span>
              <span style="font-size:11.5px;font-weight:800;color:#8A4B0A;flex:1;min-width:150px">อย่าลืมใช้ seat lock · มี <b>${remTotal}</b> ที่ว่างของเอเจนต์นี้</span>
              <button onclick="bkV2AutoDrawLocks(${idx})" style="font-size:11px;font-weight:800;color:#fff;background:#B45309;border:none;border-radius:6px;padding:6px 11px;cursor:pointer;font-family:inherit">⚡ ใช้ lock ก่อน (ดึง ${Math.min(remTotal,pax)})</button>
            </div>
            <div style="margin-top:2px;font-size:10px;color:#8A4B0A">กด "ใช้ lock ก่อน" เพื่อดึงอัตโนมัติ หรือเลือกกรุ๊ปเองด้านล่าง</div>
            ${srcRows}
          </div>` : `
          <div style="margin-top:8px;padding:9px 11px;background:#EAF1FE;border:1px solid #C7D8F7;border-radius:var(--r-sm)">
            <div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap">
              <span style="font-size:13px">🔒</span>
              <span style="font-size:11px;font-weight:700;color:#2952C8">${remTotal} locked seat${remTotal===1?'':'s'} · เลือกดึงจากกรุ๊ป</span>
            </div>
            ${srcRows}
            <div style="margin-top:6px;font-size:10px;color:#2952C8">ดึงจากล็อค <b>${drawnTot}</b> ที่ (ไม่กระทบ pool) + <b>${general}</b> ที่นั่งใหม่ · ยืนยันตอนบันทึก</div>
          </div>`;
      }
    }
    return `
      <div class="bkv2-nb-trip">
        <div class="bkv2-nb-trip-h" style="display:flex;align-items:center;gap:8px">
          <span style="font-size:11px;font-weight:700;color:var(--ink-soft);letter-spacing:.06em">TRIP ${idx+1}</span>
          <div style="display:inline-flex;background:#f5f3ef;border-radius:4px;padding:2px;margin-left:6px">
            <button onclick="bkV2SetTripBookingMode(${idx},'seat')" style="padding:3px 10px;font-size:10px;font-weight:700;border:none;background:${!isCharter?'#fff':'transparent'};color:${!isCharter?'var(--bk-navy)':'var(--ink-soft)'};border-radius:3px;cursor:pointer;font-family:inherit;letter-spacing:.06em;${!isCharter?'box-shadow:0 1px 2px rgba(0,0,0,.06)':''}">SEAT</button>
            <button onclick="bkV2SetTripBookingMode(${idx},'charter')" style="padding:3px 10px;font-size:10px;font-weight:700;border:none;background:${isCharter?'#fff':'transparent'};color:${isCharter?'#6B289A':'var(--ink-soft)'};border-radius:3px;cursor:pointer;font-family:inherit;letter-spacing:.06em;${isCharter?'box-shadow:0 1px 2px rgba(0,0,0,.06)':''}">CHARTER</button>
          </div>
          ${t.ovnLeg ? `<span style="margin-left:auto;font-size:9px;font-weight:800;letter-spacing:.04em;color:#5B289A;background:#EDE7FB;border-radius:8px;padding:4px 11px;white-space:nowrap">&#127769; OVN ขากลับ · กันที่นั่ง</span>` : `<div style="margin-left:auto;display:inline-flex;background:#f5f3ef;border-radius:5px;padding:2px;gap:2px">
            ${[['','Day Trip'],['return','OVN'],['self','OVN o/w']].map(([v,lbl])=>{ const on=(t.ovn||'')===v; const onbg=v==='return'?'#EDE7FB':v==='self'?'#FBEAD5':'#fff'; const onc=v==='return'?'#5B289A':v==='self'?'#9A5B00':'var(--bk-navy)'; return `<button type="button" onclick="bkV2SetTripOvn(${idx},'${v}')" title="${v===''?'ทริปไป-กลับวันเดียว':v==='return'?'ค้างคืน · เรารับกลับวันอื่น (กันที่นั่ง+จัดรถกลับ)':'ค้างคืน · ลูกค้ากลับเอง (one-way)'}" style="padding:3px 11px;font-size:10px;font-weight:700;border:none;background:${on?onbg:'transparent'};color:${on?onc:'var(--ink-soft)'};border-radius:3px;cursor:pointer;font-family:inherit;letter-spacing:.04em;white-space:nowrap;${on?'box-shadow:0 1px 2px rgba(0,0,0,.06)':''}">${lbl}</button>`; }).join('')}
          </div>`}
          ${d.trips.length > 1 ? `<button onclick="bkV2RemoveTrip(${idx})" style="background:transparent;border:none;color:#a32d2d;font-size:11px;cursor:pointer;font-family:inherit;margin-left:8px">&times; Remove</button>` : ''}
        </div>
        ${t.ovn?`<div style="margin-bottom:9px;background:${t.ovn==='return'?'#F6F2FE':'#FCF6EC'};border:1px solid ${t.ovn==='return'?'#E4D7FB':'#F0E0C4'};border-radius:8px;padding:9px 11px">
          <div style="font-size:9.5px;color:${t.ovn==='return'?'#5B289A':'#9A5B00'};margin-bottom:7px">${t.ovn==='return'?'🌙 OVN · ขากลับค้างคืน · กันที่นั่งวันกลับ + จัดรถกลับ · ขึ้นเรือท่าเกาะ':'🌙 OVN o/w · ค้างคืน · ลูกค้ากลับเอง (one-way) · ไม่กันที่นั่งกลับ ไม่จัดรถ'}</div>
          <div style="display:grid;grid-template-columns:${t.ovn==='return'?'1fr 1fr':'1fr'};gap:8px;align-items:end">
            ${t.ovn==='return'?`<div><label class="bkv2-nb-label" style="color:#5B289A">วันกลับ (OVN) *</label>${t.date?`<input class="bkv2-nb-input" type="date" min="${escapeHTML(t.date)}" value="${escapeHTML(t.ovnReturnDate||'')}" onchange="bkV2SetTripField(${idx},'ovnReturnDate',this.value)" style="width:100%;box-sizing:border-box">`:`<div class="bkv2-nb-input" style="width:100%;box-sizing:border-box;color:#b4b2a9;background:#f3f1ec;cursor:not-allowed;font-size:11px;display:flex;align-items:center">&#9888; เลือก DATE (วันไป) ก่อน</div>`}</div>`:''}
            <div><label class="bkv2-nb-label" style="color:#854F0B">ค่าค้างคืน (Extra) &#3647;</label><input class="bkv2-nb-input" type="number" min="0" value="${Number(t.ovnCharge)||0}" onchange="bkV2SetTripField(${idx},'ovnCharge',this.value)" placeholder="0" style="width:100%;box-sizing:border-box;text-align:right;font-variant-numeric:tabular-nums"></div>
          </div>
        </div>`:''}
        <div class="bkv2-nb-row">
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Route <em style="font-weight:500;color:#b4b2a9;font-style:normal">· type to search</em></label>
            <div class="bkv2-nb-ddwrap">
              <input id="bkv2-route-input-${idx}" class="bkv2-nb-input" type="text" placeholder="Type or pick route..." value="${escapeHTML(currentRouteLabel)}" autocomplete="off" oninput="bkV2RouteDDFilter(${idx}, this.value)" onfocus="bkV2RouteDDShow(${idx})" onkeydown="bkV2RouteDDKey(event, ${idx})">
              <div id="bkv2-route-dd-${idx}" class="bkv2-nb-dd"></div>
            </div>
          </div>
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Date</label>
            <div class="bkv2-cal-wrap">
              <div id="bkv2-cal-trig-${idx}" class="bkv2-nb-input bkv2-cal-trig" onclick="bkV2CalOpen(${idx})" tabindex="0" style="user-select:none">
                <span style="font-family:'DM Mono',monospace;${t.date?'':'color:#b4b2a9'}">${t.date || 'dd/mm/yyyy'}</span>
              </div>
              <div id="bkv2-cal-pop-${idx}" class="bkv2-cal-pop"></div>
            </div>
            ${(() => {
              if(!t.routeId || typeof ROUTES === 'undefined') return '';
              const route = ROUTES.find(r => r.id === t.routeId);
              if(!route) return '';
              const fmtD = s => s ? new Date(s).toLocaleDateString('en-GB', {day:'numeric', month:'short', year:'2-digit'}) : '—';
              const upcoming = (route.seasons||[]).filter(s => s.type === 'closed' && s.to >= (TODAY_STR||'')).sort((a,b) => a.from.localeCompare(b.from))[0];
              const tripDateStatus = t.date ? (typeof getDayStatus === 'function' ? getDayStatus(route, t.date) : null) : null;
              const isCurDateClosed = tripDateStatus && tripDateStatus.type === 'closed';
              if(isCurDateClosed){
                return `<div style="margin-top:4px;padding:5px 9px;background:#FDECEA;color:#A32D2D;border-radius:5px;font-size:10px;font-weight:600">⚠ Selected date is in a closed period · pick another date</div>`;
              }
              if(upcoming){
                return `<div style="margin-top:4px;font-size:10px;color:var(--ink-soft)"><span style="color:#A05A1A">⚠ Closed period:</span> ${fmtD(upcoming.from)} → ${fmtD(upcoming.to)}</div>`;
              }
              return '';
            })()}
          </div>
        </div>
        ${charterPickerHtml}
        ${charterBreakdownHtml}
        ${lockBannerHtml}
        ${allotBadge}
        ${(!isCharter && d.priceMode!=='manual' && subtotal?.noRate && t.routeId && t.zone) ? `<div style="margin-top:6px;padding:7px 10px;background:#FDECEA;border:1.5px dashed #C44A36;border-radius:var(--r-sm);font-size:11px;color:#A32D2D;font-weight:600;display:flex;align-items:center;gap:7px"><span style="background:#C44A36;color:#fff;padding:2px 7px;border-radius:3px;font-size:9px;letter-spacing:.06em;font-weight:700">NO RATE</span><span style="flex:1">Rate Type doesn't cover ${t.zone === 'NoTransfer' ? 'No-Transfer' : t.zone} on this route · cannot save until fixed or zone changed</span></div>` : ''}
        ${bundleBadge}
        <div class="bkv2-nb-row">
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Pickup zone *</label>
            ${(() => {
              const rt = bkV2GetRT();
              const zoneAvailable = (z) => {
                if(t.ovnLeg) return true;   // OVN return leg · ราคา 0 · เลือกได้ทุกโซน (โดยเฉพาะ No Transfer · ขึ้นเรือที่ท่าเกาะ)
                if(!t.routeId || !rt) return true;
                const sr = rt.seatRates?.[t.routeId]?.[z];
                if(!sr) return false;
                return (sr['adult-fr']||0) > 0 || (sr['adult-thai']||0) > 0;
              };
              return `<div style="display:inline-flex;background:#f5f3ef;border-radius:var(--r-sm);padding:3px;height:34px;align-items:center;width:100%;box-sizing:border-box;gap:1px">
                ${['PK','KL','NoTransfer'].map(z => {
                  const lbl = z==='PK'?'PK · Phuket' : z==='KL'?'KL · Khao Lak' : 'No Transfer';
                  const on = (t.zone||'PK') === z;
                  const available = zoneAvailable(z);
                  if(!available){
                    return `<button type="button" disabled title="No rate for ${lbl} in this agent's Rate Type" style="flex:1;padding:4px 8px;font-size:10.5px;font-weight:700;border:none;background:transparent;color:#c4c2bb;border-radius:4px;cursor:not-allowed;font-family:inherit;letter-spacing:.02em;text-decoration:line-through;text-decoration-color:#c4c2bb80;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${lbl}</button>`;
                  }
                  return `<button type="button" onclick="bkV2SetTripField(${idx},'zone','${z}')" style="flex:1;padding:4px 8px;font-size:10.5px;font-weight:700;border:none;background:${on?'var(--white)':'transparent'};color:${on?'var(--bk-navy)':'var(--ink-soft)'};border-radius:4px;cursor:pointer;font-family:inherit;letter-spacing:.02em;${on?'box-shadow:0 1px 2px rgba(0,0,0,.06)':''};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${lbl}</button>`;
                }).join('')}
              </div>`;
            })()}
          </div>
          <div class="bkv2-nb-field">
            <label class="bkv2-nb-label">Subtotal${d.priceMode==='manual'?' · <span style="color:#A05A1A;font-weight:700">overridden</span>':''}</label>
            <div style="padding:8px 11px;font-family:Manrope,sans-serif;font-size:15px;font-weight:700;${d.priceMode==='manual'?'color:var(--ink-soft);text-decoration:line-through;opacity:.65':'color:var(--bk-navy)'};background:#f8f7f3;border:1px solid var(--border);border-radius:var(--r-sm);text-align:right;font-variant-numeric:tabular-nums;letter-spacing:-.01em" title="${d.priceMode==='manual'?'Rate-type reference only — Manual total is used':''}">&#3647;${(subtotal.total||0).toLocaleString()}${subtotal.bundle?` <span style="font-size:9px;color:var(--ink-soft);font-weight:500;font-family:'DM Sans',sans-serif">incl. ฿${subtotal.bundle.toLocaleString()} bundle</span>`:''}</div>
            ${d.priceMode==='manual'?`<div style="font-size:9.5px;color:#A05A1A;margin-top:4px;text-align:right;font-family:'DM Sans',sans-serif">ใช้ราคา Manual &#3647;${(Number(d.manualTotal)||0).toLocaleString()} ทั้งใบ · ตัวเลขบนเป็นเรทอ้างอิง</div>`:''}
          </div>
        </div>
        <div style="margin-top:8px">
          <div style="font-size:8px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;margin-bottom:3px">PAX &middot; FR + TH mixed</div>
          <table style="width:100%;border-collapse:separate;border-spacing:1px;font-size:10px">
            <thead><tr>
              <th style="background:#f5f3ef;padding:3px 6px;text-align:left;font-size:8px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;border-radius:7px 0 0 7px;width:62px"></th>
              <th style="background:#f5f3ef;padding:3px 0;text-align:center;font-size:8px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em">AD</th>
              <th style="background:#f5f3ef;padding:3px 0;text-align:center;font-size:8px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em">CHD</th>
              <th style="background:#f5f3ef;padding:3px 0;text-align:center;font-size:8px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em">INF</th>
              <th style="background:#f5f3ef;padding:3px 0;text-align:center;font-size:8px;color:#ba7517;font-weight:700;letter-spacing:.06em;border-radius:0 7px 7px 0">FOC</th>
            </tr></thead>
            <tbody>
              ${( (rt&&typeof rtNatScopeOf==='function'?rtNatScopeOf(rt):'both')!=='thai' || ((t.pax.ad_fr||0)+(t.pax.chd_fr||0)+(t.pax.inf_fr||0)+(t.pax.foc_fr||0))>0 ) ? `<tr>
                <td style="background:var(--white);padding:3px 6px;font-weight:600;font-size:10px">🌐 FR</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'ad_fr',t.pax.ad_fr||0)}</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'chd_fr',t.pax.chd_fr||0)}</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'inf_fr',t.pax.inf_fr||0)}</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'foc_fr',t.pax.foc_fr||0)}</td>
              </tr>` : ''}
              ${( (rt&&typeof rtNatScopeOf==='function'?rtNatScopeOf(rt):'both')!=='fr' || ((t.pax.ad_th||0)+(t.pax.chd_th||0)+(t.pax.inf_th||0)+(t.pax.foc_th||0))>0 ) ? `<tr>
                <td style="background:var(--white);padding:3px 6px;font-weight:600;font-size:10px">🇹🇭 TH</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'ad_th',t.pax.ad_th||0)}</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'chd_th',t.pax.chd_th||0)}</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'inf_th',t.pax.inf_th||0)}</td>
                <td style="background:var(--white);padding:2px 0;text-align:center">${stepper(idx,'foc_th',t.pax.foc_th||0)}</td>
              </tr>` : ''}
              <tr style="background:var(--bk-navy-50)">
                <td style="padding:3px 6px;font-size:8px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;border-radius:0 0 0 7px">SUB</td>
                <td style="text-align:center;font-family:'DM Mono',monospace;font-weight:700;font-variant-numeric:tabular-nums;color:${totAd>0?'var(--bk-navy)':'#c7c5bb'};font-size:11px">${totAd}</td>
                <td style="text-align:center;font-family:'DM Mono',monospace;font-weight:700;font-variant-numeric:tabular-nums;color:${totChd>0?'var(--bk-navy)':'#c7c5bb'};font-size:11px">${totChd}</td>
                <td style="text-align:center;font-family:'DM Mono',monospace;font-weight:700;font-variant-numeric:tabular-nums;color:${totInf>0?'var(--bk-navy)':'#c7c5bb'};font-size:11px">${totInf}</td>
                <td style="text-align:center;font-family:'DM Mono',monospace;font-weight:700;font-variant-numeric:tabular-nums;color:${totFoc?'#ba7517':'#c7c5bb'};font-size:11px;border-radius:0 0 7px 0">${totFoc}</td>
              </tr>
            </tbody>
          </table>
        </div>
        ${(t.ovn==='return' && t.date && t.ovnReturnDate)?((d.trips||[]).some(x=>x.ovnLeg&&x.routeId===t.routeId&&x.date===t.ovnReturnDate)?`<div style="margin-top:9px;font-size:10.5px;color:#0F6E56;font-weight:600;background:#E9F7EF;border-radius:7px;padding:8px 11px">&#10003; สร้าง trip ขากลับวัน ${escapeHTML(t.ovnReturnDate||'')} แล้ว · กันที่นั่งเรียบร้อย (ดู TRIP ถัดไป)</div>`:`<button type="button" onclick="bkV2CreateOvnReturnLeg(${idx})" style="margin-top:9px;width:100%;background:#5B289A;color:#fff;border:none;border-radius:8px;padding:9px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit">&#128679; สร้าง trip ขากลับ (${escapeHTML(t.ovnReturnDate||'')}) + กันที่นั่ง</button>`):''}
      </div>
    `;
  }).join('');

  return `
    ${tripRows}
    <button onclick="bkV2AddTrip()" style="margin-top:8px;width:100%;background:transparent;border:1px dashed var(--border);color:var(--ink-soft);padding:9px;border-radius:var(--r-sm);cursor:pointer;font-family:inherit;font-size:12px;font-weight:600">+ Add another trip</button>
  `;
}

function bkV2RenderAddOnsSection(){
  const d = _bkV2.newBooking;
  if(!Array.isArray(d.addOns)) d.addOns = [];   // ponytail: legacy bookings have no addOns array → edit crashed on .find/.some
  const rt = bkV2GetRT();
  if(!rt){
    // §b2cEdit · add-on ของใบ B2C ถูกลบแล้วใส่ใหม่ทุกรอบ sync · โชว์ของที่มีจริงแบบอ่านอย่างเดียว
    if(typeof bkV2IsB2CBk==='function' && bkV2IsB2CBk(d)){
      var _e=function(x){ return String(x||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); };
      var _li=(d.addOns||[]).map(function(a){
        return '<div style="display:flex;justify-content:space-between;gap:10px;padding:5px 0;font-size:11.5px">'
          +'<span>'+_e(a.label||a.type)+(a.qty>1?(' &times; '+a.qty):'')+'</span>'
          +'<span style="font-family:\'DM Mono\',monospace">&#3647;'+(Number(a.amount)||0).toLocaleString()+'</span></div>';
      }).join('');
      return '<div style="font-size:11.5px;color:var(--ink-soft);padding:4px 0">'
        +(_li||'<span style="font-style:italic">ไม่มี add-on</span>')
        +'<div style="font-size:10.5px;color:#8a7a58;margin-top:6px">มาจาก B2C &middot; แก้ที่ B2C เท่านั้น</div></div>';
    }
    return `<div style="font-size:12px;color:var(--ink-soft);font-style:italic;padding:12px 0">Pick an agent first to see available add-ons.</div>`;
  }

  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const checked = type => d.addOns.some(a => a.type === type);
  const opts = [];

  // Check if any selected trip route has bundled longtail · disable Longtail Join in that case
  const bundledRoutes = d.trips
    .filter(t => t.routeId && _rtBundleAppliesTo(rt.routeBundles?.[t.routeId]?.longtail, t.bookingMode==='charter'))
    .map(t => ({ rid: t.routeId, mode: rt.routeBundles[t.routeId].longtail.mode, name: (typeof ROUTES!=='undefined' ? ROUTES.find(r=>r.id===t.routeId)?.name : t.routeId) }));

  // Filter longtail by applies[] · per-route pricing (Option A) · only show if a trip route applies
  const tripRouteIds = d.trips.map(t => t.routeId).filter(Boolean);
  const ltn = (typeof _rtNormalizeLongtail==='function') ? _rtNormalizeLongtail(rt.addOns?.longtail) : null;
  const ltApplyIds = ltn ? (ltn.applies.length ? tripRouteIds.filter(r=>ltn.applies.includes(r)) : tripRouteIds) : [];
  const longtailApplicable = !!(ltn && ltApplyIds.length);
  const ltJoinRoutes = longtailApplicable ? ltApplyIds.map(r=>(ltn.byRoute[r]||{join:ltn.join}).join||{}).filter(j=>j.adult||j.child) : [];
  if(longtailApplicable && ltJoinRoutes.length){
    const info = bkV2AddOnInfo('longtail-join');
    const locked = bundledRoutes.length > 0;
    const uniq = [...new Set(ltJoinRoutes.map(j=>`${j.adult||0}/${j.child||0}`))];
    const priceSub = uniq.length===1 ? `฿${ltJoinRoutes[0].adult||0}/A · ฿${ltJoinRoutes[0].child||0}/C` : `ราคาตามเส้นทาง`;
    opts.push({
      type:'longtail-join',
      label:`Longtail Join`,
      sub: locked ? `Locked &middot; bundled in ${bundledRoutes.map(b=>b.name).join(' &middot; ')}` : priceSub,
      amount: info.total,
      locked
    });
  }
  const ltCharterRoutes = longtailApplicable ? ltApplyIds.map(r=>(ltn.byRoute[r]||{charter:ltn.charter}).charter||{}).filter(c=>c.price) : [];
  if(longtailApplicable && ltCharterRoutes.length){
    const info = bkV2AddOnInfo('longtail-charter');
    const uniq = [...new Set(ltCharterRoutes.map(c=>`${c.price}/${c.capacity||6}`))];
    const sub = uniq.length===1 ? `฿${ltCharterRoutes[0].price}/boat · max ${ltCharterRoutes[0].capacity||6} pax` : `ราคาตามเส้นทาง · per boat`;
    opts.push({ type:'longtail-charter', label:`Longtail Charter`, sub, amount: info.total });
  }
  // Private Van (เหมารถ) · offered for EVERY pickup zone the rate prices (PK/KL), independent of the seat
  // zone. A PK/KL seat price already bundles a SHARED transfer, so a private van must sit on a No-Transfer
  // seat (+ this charge) or the transfer is paid twice — bkV2ToggleAddOn switches the seat to No-Transfer
  // when a private van is added. Selectable in multiples (qty · rare) and dedicated (not shared).
  // Van ops (By-trip / assignment / job order) is wired in Phase 2.
  const ptMap = rt.addOns?.privateTransfer || {};
  d.trips.forEach(t => {
    if(!t.routeId) return;
    const routePt = ptMap[t.routeId];
    if(!routePt || typeof routePt !== 'object') return;
    const rName = (typeof ROUTES!=='undefined' ? (ROUTES.find(r=>r.id===t.routeId)||{}).name : t.routeId) || t.routeId;
    Object.entries(routePt).forEach(([zone, zoneOpts]) => {
      if(!zoneOpts || typeof zoneOpts !== 'object') return;   // route map = zone→{vehicle:price}
      const zLabel = zone==='PK' ? 'Phuket' : zone==='KL' ? 'Khao Lak' : zone;
      Object.entries(zoneOpts).forEach(([vehicle, price]) => {
        if(!price) return;                                    // 0 = not offered (e.g. sedan)
        const type = `transfer-${t.routeId}-${zone}-${vehicle}`;
        if(opts.some(o => o.type === type)) return;
        opts.push({ type, label:`Private ${vehicle.charAt(0).toUpperCase()+vehicle.slice(1)} · ${zLabel}`, sub:`เหมารถรับ ${zLabel} · ${rName} · ฿${price}/คัน · dedicated (ไม่แชร์)`, amount: price });
      });
    });
  });

  if(opts.length === 0) return `<div style="font-size:12px;color:var(--ink-soft);font-style:italic;padding:12px 0">No add-ons available for this rate type · or pick trips first to enable transfer options.</div>`;

  return `
    <div class="bkv2-nb-addons">
      ${opts.map(o => { const _sel=d.addOns.find(x=>x.type===o.type); const _q=_sel?(_sel.qty||1):1; const _isChtr=o.type==='longtail-charter'; const _isVan=o.type.indexOf('transfer-')===0; const _isQty=_isChtr||_isVan; const _on=checked(o.type)&&!o.locked; const _amt=(o.amount||0)*((_isQty&&_on)?_q:1); const _btn='width:22px;height:22px;border-radius:6px;border:1px solid var(--border);background:#fff;color:var(--bk-navy);font-size:13px;font-weight:700;cursor:pointer;line-height:1;font-family:inherit'; const _qLbl=_isChtr?'ลำ':'คัน'; return `
        <label class="bkv2-nb-addon ${checked(o.type)?'on':''}" style="${o.locked?'opacity:.55;cursor:not-allowed;background:#fafafa':''}">
          <input type="checkbox" ${checked(o.type) && !o.locked?'checked':''} ${o.locked?'disabled':''} onchange="${o.locked?'':`bkV2ToggleAddOn('${o.type}')`}">
          <div style="flex:1;min-width:0">
            <div style="font-weight:600;font-size:12px;color:var(--ink)">${escapeHTML(o.label)} ${o.locked?'<span style="background:#0F6E56;color:#fff;font-size:8px;padding:1px 5px;border-radius:3px;font-weight:700;letter-spacing:.06em;margin-left:4px;vertical-align:middle">LOCKED</span>':''}</div>
            <div style="font-size:10px;color:var(--ink-soft);margin-top:1px;font-family:'DM Mono',monospace">${o.sub}</div>
            ${(_isQty&&_on)?`<div onclick="event.preventDefault();event.stopPropagation()" style="display:inline-flex;align-items:center;gap:7px;margin-top:7px;background:#F4F8FC;border:1px solid #DCE7F2;border-radius:8px;padding:4px 8px"><span style="font-size:10px;font-weight:600;color:var(--bk-navy)">จำนวน${_qLbl}</span><button type="button" onclick="event.preventDefault();event.stopPropagation();bkV2SetAddOnQty('${o.type}',${_q-1})" style="${_btn}">&minus;</button><span style="font-size:13px;font-weight:700;min-width:16px;text-align:center;font-variant-numeric:tabular-nums">${_q}</span><button type="button" onclick="event.preventDefault();event.stopPropagation();bkV2SetAddOnQty('${o.type}',${_q+1})" style="${_btn}">+</button><span style="font-size:10px;color:var(--ink-soft)">${_qLbl}</span></div>`:''}
            ${(_on&&(o.type==='longtail-join'||o.type==='longtail-charter'))?`<div onclick="event.preventDefault();event.stopPropagation()" style="margin-top:7px"><input type="text" value="${escapeHTML((_sel&&_sel.note)||'')}" oninput="bkV2SetAddOnNote('${o.type}',this.value)" placeholder="หมายเหตุหางยาว · เช่น จุดลงเรือ / เวลานัด / ผู้ติดต่อ" style="width:100%;box-sizing:border-box;height:28px;border:1px solid #DCE7F2;border-radius:7px;padding:0 9px;font-size:11px;font-family:inherit;background:#fff;color:var(--ink)"></div>`:''}
          </div>
          <div style="font-family:Manrope,sans-serif;font-weight:700;color:${o.locked?'var(--ink-soft)':'var(--bk-navy)'};font-size:14px;font-variant-numeric:tabular-nums;letter-spacing:-.01em">${o.locked?'—':`฿${_amt.toLocaleString()}`}</div>
        </label>
      `; }).join('')}
    </div>
  `;
}

// ── Passenger list (rows = total AD - 1 · lead handled separately) ──
// Charter displacement confirmation modal · shown when chartering a boat with existing seat bookings
function bkV2RenderCharterConfirmModal(){
  const c = _bkV2CharterConfirm;
  if(!c) return '';
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[ch]);
  const route = (typeof ROUTES !== 'undefined') ? ROUTES.find(r => r.id === c.routeId) : null;
  const isOversold = c.oversold > 0;
  return `
    <div style="position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:200;display:flex;align-items:flex-start;justify-content:center;padding:40px 20px;overflow-y:auto" onclick="if(event.target===this)bkV2CancelCharterConfirm()">
      <div style="background:#fff;border-radius:8px;width:580px;max-width:100%;box-shadow:0 20px 60px rgba(0,0,0,.25);overflow:hidden">
        <div style="padding:16px 22px;background:#F4E8FB;border-bottom:1px solid #D7B5F0;display:flex;align-items:center;gap:12px">
          <div style="font-size:24px">⚠️</div>
          <div style="flex:1">
            <div style="font-size:9px;color:#6B289A;font-weight:700;letter-spacing:.08em">CHARTER CONFIRMATION REQUIRED</div>
            <div style="font-size:15px;font-weight:700;color:#1a1a1a;margin-top:2px">Existing seat bookings will be affected</div>
          </div>
        </div>
        <div style="padding:18px 22px">
          <div style="font-size:12px;color:#5A5A52;line-height:1.6;margin-bottom:14px">
            You're chartering <strong style="color:#1a1a1a">${escapeHTML(c.boatName)}</strong> (${c.boatCapacity} cap) on <strong style="font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">${escapeHTML(c.date)}</strong> for <strong style="color:#1a1a1a">${escapeHTML(route?.name||c.routeId)}</strong>.
            This will <strong style="color:#6B289A">reduce seat capacity</strong> for existing bookings on this route+date.
          </div>

          <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px">
            <div style="background:#fafafa;border:1px solid var(--border);border-radius:5px;padding:9px 11px">
              <div style="font-size:8px;color:var(--ink-soft);font-weight:700;letter-spacing:.08em;text-transform:uppercase">Pool before</div>
              <div style="font-family:Manrope,sans-serif;font-size:17px;font-weight:700;color:#1a1a1a;font-variant-numeric:tabular-nums;margin-top:3px">${c.currentAvailable}</div>
              <div style="font-size:10px;color:var(--ink-soft);font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">${c.seatsConsumed} booked</div>
            </div>
            <div style="background:#F4E8FB;border:1px solid #D7B5F0;border-radius:5px;padding:9px 11px">
              <div style="font-size:8px;color:#6B289A;font-weight:700;letter-spacing:.08em;text-transform:uppercase">Charter removes</div>
              <div style="font-family:Manrope,sans-serif;font-size:17px;font-weight:700;color:#6B289A;font-variant-numeric:tabular-nums;margin-top:3px">−${c.boatCapacity}</div>
              <div style="font-size:10px;color:#6B289A">${escapeHTML(c.boatName)}</div>
            </div>
            <div style="background:${isOversold?'#FDE7E7':'#E1F5EE'};border:1px solid ${isOversold?'#F5B7B7':'#B8E5D2'};border-radius:5px;padding:9px 11px">
              <div style="font-size:8px;color:${isOversold?'#a32d2d':'#0F6E56'};font-weight:700;letter-spacing:.08em;text-transform:uppercase">Pool after</div>
              <div style="font-family:Manrope,sans-serif;font-size:17px;font-weight:700;color:${isOversold?'#a32d2d':'#0F6E56'};font-variant-numeric:tabular-nums;margin-top:3px">${c.availAfter}</div>
              <div style="font-size:10px;color:${isOversold?'#a32d2d':'#0F6E56'}">${isOversold?`OVERSOLD by ${c.oversold}`:'still ok'}</div>
            </div>
          </div>

          ${isOversold ? `
            <div style="background:#FDE7E7;border:1px solid #F5B7B7;border-radius:5px;padding:10px 13px;margin-bottom:14px;font-size:11px;color:#a32d2d;line-height:1.5">
              <strong>⚠ Capacity oversold by ${c.oversold} seat${c.oversold===1?'':'s'}.</strong>
              After this charter, existing seat bookings (${c.seatsConsumed} pax) exceed remaining pool (${c.availAfter} seats). Dispatcher must <strong>move some bookings to another boat</strong> or <strong>add a rental boat</strong> in Boat Operation before this date.
            </div>
          ` : `
            <div style="background:#E1F5EE;border:1px solid #B8E5D2;border-radius:5px;padding:10px 13px;margin-bottom:14px;font-size:11px;color:#0F6E56;line-height:1.5">
              ✓ Remaining pool (${c.availAfter} seats) still covers existing bookings (${c.seatsConsumed} pax). Safe to charter.
            </div>
          `}

          <div style="font-size:9px;color:var(--ink-soft);font-weight:700;letter-spacing:.08em;text-transform:uppercase;margin-bottom:6px">Affected bookings · ${c.affectedBookings.length}</div>
          <div style="background:#fafafa;border:1px solid var(--border);border-radius:5px;max-height:200px;overflow-y:auto">
            ${c.affectedBookings.length === 0 ? '<div style="padding:14px;text-align:center;color:var(--ink-soft);font-style:italic;font-size:11px">No existing bookings affected</div>' :
              c.affectedBookings.map(bk => `
                <div style="padding:8px 12px;border-bottom:1px solid #f5f3ef;display:flex;align-items:center;gap:10px;font-size:11px">
                  <div style="font-family:'DM Mono',monospace;font-size:9px;color:var(--ink-soft);min-width:90px">${escapeHTML(bk.bookingId)}</div>
                  <div style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">
                    <div style="font-weight:600;color:#1a1a1a" title="${escapeHTML(bk.customerName)}">${escapeHTML(bk.customerName)}</div>
                    <div style="font-size:10px;color:var(--ink-soft)">${escapeHTML(bk.agentName)} ${bk.voucherRef?'· '+escapeHTML(bk.voucherRef):''}</div>
                  </div>
                  <div style="font-family:Manrope,sans-serif;font-weight:700;font-size:13px;color:var(--bk-navy);font-variant-numeric:tabular-nums">${bk.pax} pax</div>
                  <div style="background:${bk.status==='confirmed'?'#E1F5EE':'#FFF6E5'};color:${bk.status==='confirmed'?'#0F6E56':'#A05A1A'};font-size:8px;padding:2px 6px;border-radius:3px;font-weight:700;letter-spacing:.04em">${escapeHTML(bk.status||'').toUpperCase()}</div>
                </div>
              `).join('')}
          </div>
        </div>
        <div style="padding:13px 22px;background:#fafafa;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:8px">
          <button onclick="bkV2CancelCharterConfirm()" style="padding:8px 16px;font-size:12px;font-weight:600;background:transparent;border:1px solid rgba(0,0,0,.15);border-radius:5px;cursor:pointer;font-family:inherit;color:#5A5A52">Cancel</button>
          <button onclick="bkV2ConfirmCharter()" style="padding:8px 16px;font-size:12px;font-weight:700;background:#6B289A;border:1px solid #6B289A;border-radius:5px;cursor:pointer;font-family:inherit;color:#fff">${isOversold ? 'Confirm anyway · Notify dispatcher' : 'Confirm charter'}</button>
        </div>
      </div>
    </div>
  `;
}

// True if the current rate type offers any add-ons applicable to the trips
function bkV2HasAvailableAddOns(){
  const d = _bkV2.newBooking;
  const rt = bkV2GetRT();
  if(!rt) return false;
  const tripRoutes = d.trips.map(t => t.routeId).filter(Boolean);
  if(tripRoutes.length === 0) return false;
  // Longtail · only if at least one trip route is in applies[] (or applies undefined = legacy)
  const lt = rt.addOns?.longtail;
  if(lt){
    const ltn = (typeof _rtNormalizeLongtail==='function') ? _rtNormalizeLongtail(lt) : null;
    if(ltn){
      const ids = ltn.applies.length ? tripRoutes.filter(r=>ltn.applies.includes(r)) : tripRoutes;
      const ok = ids.some(r=>{ const e=ltn.byRoute[r]||{join:ltn.join,charter:ltn.charter}; return (e.join&&(e.join.adult||e.join.child))||(e.charter&&e.charter.price); });
      if(ok) return true;
    }
  }
  // Private transfer · check if any trip route has matching zone+vehicle
  const ptMap = rt.addOns?.privateTransfer || {};
  return d.trips.some(t => {
    if(!t.routeId || !t.zone || t.zone === 'NoTransfer') return false;
    const zoneOpts = ptMap[t.routeId]?.[t.zone];
    return zoneOpts && Object.values(zoneOpts).some(v => v);
  });
}

// Right-column live Review · summarizes what's been filled
function bkV2RenderReviewPanel(){
  const d = _bkV2.newBooking;
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  if(!d.agentId){
    return `<div style="background:#fafafa;border:1px dashed var(--border);border-radius:var(--r-sm);padding:18px 14px;font-size:11px;color:var(--ink-soft);font-style:italic;text-align:center">Pick an agent to see live booking review</div>`;
  }
  const agent = sbGetAgent(d.agentId);
  const q = bkV2CalcQuote();
  const totPax = d.trips.reduce((s,t) => s + bkV2PaxAllTot(t.pax), 0);
  const totAd = d.trips.reduce((s,t) => s + bkV2PaxTot(t.pax,'ad'), 0);
  const pickupArea = bkV2GetArea(d.pickupAreaId);
  const dropArea = d.dropoffSame ? null : bkV2GetArea(d.dropoffAreaId);

  const fmtMoney = n => `<span style="font-family:Manrope,sans-serif;font-weight:700;font-variant-numeric:tabular-nums">฿${(n||0).toLocaleString()}</span>`;
  const fmtNum = n => `<span style="font-family:Manrope,sans-serif;font-weight:600;font-variant-numeric:tabular-nums">${n||0}</span>`;

  // Trips block · with allotment summary
  const tripsHtml = d.trips.filter(t => t.routeId).map((t, i) => {
    const route = (typeof ROUTES!=='undefined') ? ROUTES.find(r => r.id === t.routeId) : null;
    const tp = bkV2PaxAllTot(t.pax);
    const sub = bkV2TripSubtotal(t);
    // Allotment chip
    let allotChip = '';
    if(t.date && typeof getAllotment === 'function'){
      const al = getAllotment(t.routeId, t.date, _bkV2.editingId || null);   // exclude own seats when editing
      const isOver = al.hasAllotment && tp > al.seatsAvailable && tp > 0;
      if(!al.hasAllotment){
        allotChip = `<span style="background:#fafafa;border:1px dashed #d3d1c7;color:#5A5A52;font-size:9px;padding:1px 5px;border-radius:3px;font-weight:600">PROVISIONAL</span>`;
      } else if(isOver){
        allotChip = `<span style="background:#FDE7E7;color:#a32d2d;font-size:9px;padding:1px 5px;border-radius:3px;font-weight:700">OVER ${tp}/${al.seatsAvailable}</span>`;
      } else if(al.state === 'full'){
        allotChip = `<span style="background:#FDE7E7;color:#a32d2d;font-size:9px;padding:1px 5px;border-radius:3px;font-weight:700">FULL</span>`;
      } else if(al.state === 'tight'){
        allotChip = `<span style="background:#FFF6E5;color:#A05A1A;font-size:9px;padding:1px 5px;border-radius:3px;font-weight:600">${al.seatsAvailable} left</span>`;
      } else {
        allotChip = `<span style="background:#E1F5EE;color:#0F6E56;font-size:9px;padding:1px 5px;border-radius:3px;font-weight:600">${al.seatsAvailable} free</span>`;
      }
    }
    const modeChip = t.bookingMode === 'charter'
      ? `<span style="background:#F4E8FB;color:#6B289A;font-size:9px;padding:1px 5px;border-radius:3px;font-weight:700;letter-spacing:.04em">CHARTER${sub.boatName?' · '+escapeHTML(sub.boatName):''}</span>`
      : '';
    return `
      <div style="padding:6px 0;border-bottom:1px solid #f5f3ef;font-size:11px;line-height:1.4">
        <div style="display:flex;align-items:baseline;justify-content:space-between;gap:6px">
          <div style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600;color:var(--ink)" title="${escapeHTML(route?.name||t.routeId)}">${i+1}. ${escapeHTML(route?.name||t.routeId)}</div>
          ${(function(){ /* §b2cEdit · ใบ B2C ยอดรายทริปเป็นของจริง ไม่ต้องขีดฆ่า */
            var _b2c=(typeof bkV2IsB2CBk==='function')&&bkV2IsB2CBk(d);
            if(_b2c) return `<div>${fmtMoney(Number(t.subtotal)||0)}</div>`;
            return `<div ${d.priceMode==='manual'?'style="text-decoration:line-through;opacity:.5" title="Rate-type reference — Manual total used"':''}>${fmtMoney(sub.total)}</div>`;
          })()}
        </div>
        <div style="font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums;display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:3px">
          <span style="font-size:11.5px;font-weight:700;color:var(--ink)">${t.date ? escapeHTML(t.date) : '<span style="color:#a32d2d">no date</span>'}</span>
          <span style="color:var(--ink-soft)">&middot;</span>
          <span style="font-size:11.5px;font-weight:700;color:var(--ink)">${tp} pax</span>
          <span style="font-size:9px;font-weight:600;color:var(--ink-soft);background:#efece6;padding:1px 6px;border-radius:4px;letter-spacing:.02em">${escapeHTML(t.zone)}</span>
          ${modeChip} ${allotChip}
        </div>
      </div>
    `;
  }).join('');

  // Add-ons block
  const addOnsHtml = d.addOns.length > 0 ? `
    <div class="rv-section">
      <div class="rv-lab">Add-ons (${fmtNum(d.addOns.length)})</div>
      ${d.addOns.map(a => {
        const info = bkV2AddOnInfo(a.type);
        const q = a.qty||1; const amt = info.total*q;
        const ql = (a.type==='longtail-charter'&&q>1)?` <span style="color:var(--bk-navy);font-weight:700">× ${q} ลำ</span>`:'';
        const _nt=(a.note||'').trim();
        return `<div style="display:flex;justify-content:space-between;gap:6px;font-size:11px;color:var(--ink-soft);margin-top:2px">
          <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1">${escapeHTML(info.label||a.type)}${ql}${_nt?` <span style="color:#9A5B00" title="${escapeHTML(_nt)}">&#128221; ${escapeHTML(_nt)}</span>`:''}</span>
          <span>${fmtMoney(amt)}</span>
        </div>`;
      }).join('')}
    </div>
  ` : '';

  // Special meals
  const m = d.specialMeals || {};
  const mealCount = (m.veg||0) + (m.vegan||0) + (m.halal||0);
  const _allergTxtRv=(typeof bkV2AllergyText==='function')?bkV2AllergyText(m):(m.allergies||'').trim();
  const mealHtml = (mealCount > 0 || _allergTxtRv || (d.largeLuggage||0) > 0) ? `
    <div class="rv-section">
      <div class="rv-lab">Special</div>
      ${m.veg ? `<div style="font-size:11px;color:var(--ink-soft);margin-top:2px">🥬 ${fmtNum(m.veg)} vegetarian</div>` : ''}
      ${m.vegan ? `<div style="font-size:11px;color:var(--ink-soft);margin-top:2px">🌱 ${fmtNum(m.vegan)} vegan</div>` : ''}
      ${m.halal ? `<div style="font-size:11px;color:var(--ink-soft);margin-top:2px">🕌 ${fmtNum(m.halal)} halal</div>` : ''}
      ${_allergTxtRv ? `<div style="font-size:10px;color:var(--ink-soft);margin-top:2px;font-style:italic;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escapeHTML(_allergTxtRv)}">⚠ ${escapeHTML(_allergTxtRv)}</div>` : ''}
      ${d.largeLuggage ? `<div style="font-size:11px;color:var(--ink-soft);margin-top:2px">🧳 ${fmtNum(d.largeLuggage)} large bag${d.largeLuggage===1?'':'s'}</div>` : ''}
    </div>
  ` : '';

  // Cash on Tour
  const cotHtml = d.cashOnTour ? `
    <div class="rv-section" style="background:#FFF6E5;border:1px solid #EAD9B0;border-radius:var(--r-sm);padding:6px 9px;margin-top:8px">
      <div style="font-size:9px;color:#633806;font-weight:700;letter-spacing:.06em">💰 CASH ON TOUR</div>
      <div id="bkv2-cot-rv-amt" style="font-size:11px;color:#633806;font-weight:700;margin-top:2px;font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">${escapeHTML(d.cashOnTour.currency||'THB')} ${(d.cashOnTour.amount||0).toLocaleString()}</div>
      <div style="font-size:9px;color:#633806;margin-top:1px">${d.cashOnTour.handling === 'deduct' ? 'Deduct from invoice' : 'Keep separate'}</div>
      <div id="bkv2-cot-rv-note" style="font-size:9.5px;color:#7a5a14;margin-top:3px;line-height:1.35;border-top:1px dashed #EAD9B0;padding-top:3px;display:${(d.cashOnTour.note||'').trim()?'block':'none'}">${(d.cashOnTour.note||'').trim()?'📝 '+escapeHTML(d.cashOnTour.note):''}</div>
    </div>
  ` : '';

  return `
    <style>
      #view-booking .rv-card{background:#fafafa;border:1px solid var(--border);border-radius:var(--r-sm);padding:12px 14px;font-family:'DM Sans',sans-serif}
      #view-booking .rv-section{padding:8px 0;border-bottom:1px solid #f5f3ef}
      #view-booking .rv-section:last-child{border-bottom:none}
      #view-booking .rv-lab{font-size:9px;color:var(--ink-soft);font-weight:700;letter-spacing:.08em;text-transform:uppercase;margin-bottom:3px}
      #view-booking .rv-val{font-size:12px;color:var(--ink);font-weight:600}
      #view-booking .rv-sub{font-size:10px;color:var(--ink-soft);margin-top:1px;font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums}
      #view-booking .rv-total{padding:10px 12px;background:var(--bk-navy-50);border:1px solid var(--bk-navy-light);border-radius:var(--r-sm);margin-top:10px;display:flex;align-items:baseline;justify-content:space-between;gap:8px}
      #view-booking .rv-total-lab{font-size:10px;color:var(--bk-navy);font-weight:700;letter-spacing:.08em}
      #view-booking .rv-total-amt{font-family:Manrope,sans-serif;font-size:18px;font-weight:700;color:#0F6E56;font-variant-numeric:tabular-nums;letter-spacing:-.01em}
    </style>
    <div class="rv-card">
      <div class="rv-section">
        <div class="rv-lab">Agent</div>
        <div class="rv-val">${escapeHTML(agent?.name||'—')}</div>
        ${d.voucherRef ? `<div class="rv-sub">Voucher: ${escapeHTML(d.voucherRef)}</div>` : ''}
      </div>
      ${d.trips.some(t=>t.routeId) ? `
        <div class="rv-section">
          <div class="rv-lab">Trips · ${fmtNum(d.trips.filter(t=>t.routeId).length)}</div>
          ${tripsHtml}
        </div>
      ` : ''}
      ${totPax > 0 ? `
        <div class="rv-section">
          <div class="rv-lab">Guests · ${fmtNum(totPax)} pax</div>
          <div class="rv-val">${d.leadPax ? escapeHTML(d.leadPax) : '<span style="color:#a32d2d;font-style:italic">no lead name</span>'}</div>
          ${d.leadPhone ? `<div class="rv-sub">📞 ${escapeHTML(d.leadPhone)}</div>` : ''}
          ${totAd > 1 ? `<div class="rv-sub">+ ${fmtNum(totAd - 1)} additional adult${totAd>2?'s':''}</div>` : ''}
        </div>
      ` : ''}
      ${pickupArea ? `
        <div class="rv-section">
          <div class="rv-lab">Pickup</div>
          ${d.hotelName
            ? `<div class="rv-val" style="font-size:13.5px;line-height:1.3">${escapeHTML(d.hotelName)}</div>
               <div class="rv-sub" style="text-transform:none">${escapeHTML(pickupArea.name)}${d.roomNumber?' · Room '+escapeHTML(d.roomNumber):''}</div>`
            : `<div class="rv-val" style="font-size:13.5px;line-height:1.3">${escapeHTML(pickupArea.name)}</div>
               ${d.roomNumber?`<div class="rv-sub">Room ${escapeHTML(d.roomNumber)}</div>`:''}`}
          ${dropArea ? `<div class="rv-sub">↪ Drop: ${escapeHTML(dropArea.name)}</div>` : ''}
        </div>
      ` : ''}
      ${(Array.isArray(d.altPickups) && d.altPickups.some(a=>(a.who||'').trim()||(a.place||'').trim())) ? `
        <div class="rv-section">
          <div class="rv-lab">🚌 รับหลายจุด</div>
          ${d.altPickups.filter(a=>(a.who||'').trim()||(a.place||'').trim()||a.areaId).map(a=>{const _ar=a.areaId&&typeof bkV2GetArea==='function'?bkV2GetArea(a.areaId):null;const _z=(a.zone||(_ar?_ar.zone:''));const _zl=(_z==='PK'?'PK':_z==='KL'?'KL':_z==='NoTransfer'?'NT':'');const _loc=(a.place||'').trim()||(_ar?_ar.name:'')||'—';const _q=Math.max(1,parseInt(a.qty)||1);return `<div class="rv-sub" style="text-transform:none;color:#5B289A"><b>${_q} คน</b> · ${escapeHTML((a.who||'').trim()||'—')}${_zl?` <span style="font-size:8px;font-weight:700;background:#EDE7FB;padding:0 4px;border-radius:3px">${_zl}</span>`:''} · ${escapeHTML(_loc)}</div>`;}).join('')}
        </div>
      ` : ''}
      ${addOnsHtml}
      ${mealHtml}
      ${cotHtml}
      ${(() => {
        const esc = escapeHTML;
        const rows = (d.adjustments||[]).map((a,i) => {
          const disc = a.kind === 'discount';
          const v = Number(a.value) || 0;
          const amt = disc ? (a.mode === 'percent' ? Math.round(q.base * v / 100) : Math.round(v)) : Math.round(v);
          const col = disc ? '#A32D2D' : '#0F7A5A';
          return `
            <div style="background:#fff;border:1px solid var(--border);border-radius:6px;padding:6px 8px;margin-top:6px;display:flex;align-items:center;gap:5px;flex-wrap:wrap">
              <span style="font-size:8px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:${col};background:${disc?'#FDECEA':'#E1F5EE'};padding:2px 5px;border-radius:4px">${disc?'Disc':'Extra'}</span>
              <input value="${esc(a.label)}" oninput="bkV2SetAdjustment(${i},'label',this.value)" placeholder="Label" style="flex:1;min-width:70px;font-size:11px;padding:3px 6px">
              ${disc?`<span style="display:inline-flex;border:1px solid var(--border);border-radius:5px;overflow:hidden">
                <button onclick="bkV2SetAdjustment(${i},'mode','amount')" style="border:none;cursor:pointer;font-family:inherit;font-size:11px;padding:3px 7px;background:${a.mode!=='percent'?'var(--bk-navy)':'#fff'};color:${a.mode!=='percent'?'#fff':'var(--ink-soft)'}">฿</button>
                <button onclick="bkV2SetAdjustment(${i},'mode','percent')" style="border:none;cursor:pointer;font-family:inherit;font-size:11px;padding:3px 7px;background:${a.mode==='percent'?'var(--bk-navy)':'#fff'};color:${a.mode==='percent'?'#fff':'var(--ink-soft)'}">%</button>
              </span>`:''}
              <input type="number" min="0" value="${v||''}" onchange="bkV2SetAdjustment(${i},'value',this.value)" placeholder="0" style="width:64px;font-size:12px;padding:3px 6px;text-align:right;font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">
              <span style="min-width:62px;text-align:right;font-family:Manrope,sans-serif;font-weight:700;font-variant-numeric:tabular-nums;color:${col}">${disc?'&minus;':'+'}฿${amt.toLocaleString()}</span>
              <button onclick="bkV2RemoveAdjustment(${i})" title="Remove" style="border:none;background:transparent;cursor:pointer;color:var(--ink-soft);font-size:15px;line-height:1">&times;</button>
              <input value="${esc(a.note)}" oninput="bkV2SetAdjustment(${i},'note',this.value)" placeholder="Note (optional)" style="flex:1 1 100%;font-size:11px;padding:3px 6px;color:var(--ink-soft)">
            </div>`;
        }).join('');
        return `
          <div class="rv-section">
            <div class="rv-lab">Adjustments</div>
            ${rows}
            <div style="display:flex;gap:7px;margin-top:7px">
              <button onclick="bkV2AddAdjustment('discount')" style="font-size:11px;font-weight:600;color:#A32D2D;background:#FDECEA;border:1px solid #F5C9C4;border-radius:6px;padding:5px 10px;cursor:pointer;font-family:inherit">+ Discount</button>
              <button onclick="bkV2AddAdjustment('extra')" style="font-size:11px;font-weight:600;color:#0F7A5A;background:#E1F5EE;border:1px solid #B8E5D2;border-radius:6px;padding:5px 10px;cursor:pointer;font-family:inherit">+ Extra charge</button>
            </div>
          </div>`;
      })()}
      ${(q.totalDiscount>0||q.totalExtra>0) ? `
        <div style="display:grid;grid-template-columns:1fr auto;gap:3px 10px;font-size:11px;padding:8px 0 0">
          <span style="color:var(--ink-soft)">Subtotal</span><span style="text-align:right;font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">฿${q.base.toLocaleString()}</span>
          ${q.totalDiscount>0?`<span style="color:#A32D2D">Discount</span><span style="text-align:right;font-family:Manrope,sans-serif;color:#A32D2D;font-variant-numeric:tabular-nums">&minus;฿${q.totalDiscount.toLocaleString()}</span>`:''}
          ${q.totalExtra>0?`<span style="color:#0F7A5A">Extra charge</span><span style="text-align:right;font-family:Manrope,sans-serif;color:#0F7A5A;font-variant-numeric:tabular-nums">+฿${q.totalExtra.toLocaleString()}</span>`:''}
        </div>` : ''}
      <div class="rv-total">
        <span class="rv-total-lab">QUOTE TOTAL</span>
        <span class="rv-total-amt">฿${q.grandTotal.toLocaleString()}</span>
      </div>
      ${q.totalFoc > 0 ? `<div style="font-size:10px;color:#A05A1A;margin-top:6px;text-align:center;font-style:italic">${q.totalFoc} FOC · ฿${q.focDiscount.toLocaleString()} forgone</div>` : ''}
    </div>
  `;
}

// Returns <tr> rows only · for use inside the unified Guests table
function bkV2RenderPassengerRows(){
  const d = _bkV2.newBooking;
  bkV2SyncPassengers();
  if(d.passengers.length === 0){
    return `<tr><td colspan="4" style="padding:8px 12px;font-size:10px;color:var(--ink-soft);font-style:italic">Only lead · bump AD/CHD/INF/FOC in Trips to add more guests.</td></tr>`;
  }
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const typeStyle = t => ({
    AD:  {bg:'#f5f3ef',color:'#5A5A52'},
    CHD: {bg:'#E8F4DE',color:'#3B6D11'},
    INF: {bg:'#FBEAF0',color:'#993556'},
    FOC: {bg:'#FAEEDA',color:'#A05A1A'}
  })[t] || {bg:'#f5f3ef',color:'#5A5A52'};
  const _totFoc = (d.trips||[]).reduce((s,t)=> s + ((typeof bkV2PaxTot==='function')?bkV2PaxTot(t.pax,'foc'):0), 0);
  return d.passengers.map((p, i) => {
    const seqNum = i + 2; // pax #2, #3, ... (lead is #1)
    const isGuess = p.nationality && bkV2GuessNationality(p.name||'') === p.nationality;
    const ts = typeStyle(p.type);
    return `
      <tr style="border-bottom:1px solid #f5f3ef">
        <td style="padding:5px 6px;vertical-align:middle">
          <div style="font-family:'DM Mono',monospace;font-size:10px;color:var(--ink-soft);font-weight:700;line-height:1.1">#${seqNum}</div>
          <div style="background:${ts.bg};color:${ts.color};font-size:7px;font-weight:700;padding:1px 4px;border-radius:2px;letter-spacing:.08em;display:inline-block;margin-top:2px">${p.type||'AD'}</div>
          ${_totFoc>0?`<div onclick="event.stopPropagation();bkV2TogglePassengerFoc(${i})" title="${p.type==='FOC'?'FOC · คลิกเพื่อเอาออก':'เลือกเป็น FOC (ฟรี)'}" style="cursor:pointer;font-size:13px;line-height:1;margin-top:3px;color:${p.type==='FOC'?'#D9A400':'#cfcabd'}">${p.type==='FOC'?'★':'☆'}</div>`:''}
        </td>
        <td style="padding:5px 6px"><input class="bkv2-nb-input" type="text" placeholder="${p.type==='INF'?'Infant':p.type==='CHD'?'Child':p.type==='FOC'?'FOC':'Pax'} ${seqNum} name" value="${escapeHTML(p.name||'')}" oninput="bkV2SetPassenger(${i},'name',this.value)" onblur="bkV2SyncPassengers();bkV2Render()" style="padding:6px 8px;font-size:12px;width:100%;box-sizing:border-box"></td>
        <td style="padding:5px 6px">
          <div class="bkv2-nb-ddwrap">
            <input id="bkv2-nat-input-p${i}" class="bkv2-nb-input" type="text" placeholder="Type or pick…" autocomplete="off" value="${p.nationality ? escapeHTML(bkV2NatDDLabel(p.nationality)) : ''}" oninput="bkV2NatDDFilter('p${i}', this.value)" onfocus="bkV2NatDDShow('p${i}')" onkeydown="bkV2NatDDKey(event,'p${i}')" onblur="bkV2NatDDBlur('p${i}')" style="padding:6px 8px;font-size:12px;width:100%;box-sizing:border-box">
            <div id="bkv2-nat-dd-p${i}" class="bkv2-nb-dd"></div>
          </div>
        </td>
        <td style="padding:5px 6px;text-align:center">${isGuess ? '<span style="background:#E1F5EE;color:#0F6E56;font-size:8px;padding:1px 5px;border-radius:3px;font-weight:600;letter-spacing:.06em">GUESS</span>' : ''}</td>
      </tr>
    `;
  }).join('');
}

// ── SVG icon helpers for booking ──
function bkV2DietIcon(name, color){
  const c = color||'currentColor';
  const map = {
    veg:    '<path d="M12 22c-4 0-8-3-8-9 0-4 3-7 7-7 1.5 0 3 .5 4 1.5C16 6.5 18 5 20 5c0 5-3 9-7 10v7z"/>',
    vegan:  '<path d="M12 2C7 7 4 10 4 14a8 8 0 0 0 16 0c0-4-3-7-8-12z"/><line x1="12" y1="22" x2="12" y2="14"/>',
    halal:  '<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>',
    luggage:'<rect x="5" y="7" width="14" height="13" rx="2"/><path d="M9 7V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v3"/><line x1="5" y1="13" x2="19" y2="13"/>'
  };
  const p = map[name] || map.luggage;
  return `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="${c}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0">${p}</svg>`;
}

// ── Flag SVG helpers (simple stylized · matches BuildAxis aesthetic) ──
function bkV2FlagSVG(code){
  const flags = {
    uk: `<svg width="14" height="10" viewBox="0 0 30 20" style="border-radius:2px"><rect width="30" height="20" fill="#012169"/><path d="M0,0 L30,20 M30,0 L0,20" stroke="#FFF" stroke-width="3"/><path d="M0,0 L30,20 M30,0 L0,20" stroke="#C8102E" stroke-width="1.5"/><path d="M15,0 V20 M0,10 H30" stroke="#FFF" stroke-width="5"/><path d="M15,0 V20 M0,10 H30" stroke="#C8102E" stroke-width="3"/></svg>`,
    ru: `<svg width="14" height="10" viewBox="0 0 30 20" style="border-radius:2px"><rect width="30" height="6.67" y="0" fill="#FFF"/><rect width="30" height="6.67" y="6.67" fill="#0039A6"/><rect width="30" height="6.67" y="13.33" fill="#D52B1E"/></svg>`,
    cn: `<svg width="14" height="10" viewBox="0 0 30 20" style="border-radius:2px"><rect width="30" height="20" fill="#DE2910"/><polygon points="5,3 6,5.5 8.5,5.5 6.5,7 7.5,9.5 5,8 2.5,9.5 3.5,7 1.5,5.5 4,5.5" fill="#FFDE00"/></svg>`
  };
  return flags[code] || '';
}

// ── Dietary + Luggage ── (1-line · SVG icons · compact)
function bkV2RenderDietaryLuggageSection(){
  const d = _bkV2.newBooking;
  const m = d.specialMeals || (d.specialMeals = { veg:0, vegan:0, halal:0, allergies:'' });
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const luggage = d.largeLuggage || 0;
  // Compact pill style · all 4 items in 1 row
  const pill = (on, val, label, color, iconKey, onToggleStmt, onSetQtyStmt) => `
    <label style="display:inline-flex;align-items:center;gap:8px;padding:7px 12px;background:${on?color+'14':'var(--white)'};border:1px solid ${on?color+'55':'var(--border)'};border-radius:14px;cursor:pointer;font-size:11.5px;font-weight:600;color:${on?color:'var(--ink)'}">
      <input type="checkbox" ${on?'checked':''} onchange="${onToggleStmt}" style="accent-color:${color};width:14px;height:14px;margin:0;flex-shrink:0">
      ${bkV2DietIcon(iconKey, on?color:'#94A3B8')}
      <span>${label}</span>
      ${on ? `<span onclick="event.stopPropagation()" style="display:inline-flex;align-items:center;gap:4px;margin-left:2px"><input type="number" min="1" max="99" value="${val}" oninput="${onSetQtyStmt}" style="width:40px;height:22px;font-size:12px;font-weight:700;text-align:center;font-variant-numeric:tabular-nums;border:1px solid ${color}55;border-radius:4px;padding:0 3px;background:#fff;color:${color};font-family:inherit"></span>` : ''}
    </label>
  `;
  const totalSpecial = (m.veg||0) + (m.vegan||0) + (m.halal||0);
  const luggageWarn = luggage >= 3 ? `<div style="background:#FFF6E5;border:1px solid #EAD9B0;border-radius:var(--r-sm);padding:7px 11px;margin-top:8px;font-size:11px;color:#633806">&#9888; ${luggage} large bag(s) may require van seat reduction · check with dispatcher</div>` : '';
  return `
    <div style="display:flex;flex-wrap:wrap;align-items:center;gap:6px">
      <span style="font-size:10px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin-right:3px">Diet</span>
      ${pill((m.veg||0)>0, m.veg||0, 'Vegetarian', '#246b43', 'veg', "bkV2ToggleMealOn('veg',this.checked)", "bkV2SetMealQty('veg',this)")}
      ${pill((m.vegan||0)>0, m.vegan||0, 'Vegan', '#1f8a4a', 'vegan', "bkV2ToggleMealOn('vegan',this.checked)", "bkV2SetMealQty('vegan',this)")}
      ${pill((m.halal||0)>0, m.halal||0, 'Halal', '#8a5b1f', 'halal', "bkV2ToggleMealOn('halal',this.checked)", "bkV2SetMealQty('halal',this)")}
      <span style="width:1px;height:18px;background:var(--border);margin:0 4px"></span>
      ${pill(luggage>0, luggage, 'Large luggage', '#5A4F2A', 'luggage', "bkV2ToggleLuggageOn(this.checked)", "bkV2SetLuggageQty(this.value)")}
    </div>
    ${luggageWarn}
    <div style="margin-top:10px">
      <label class="bkv2-nb-label">Food allergies ${(typeof bkV2AllergyCount==='function'&&bkV2AllergyCount(m)>0)?`<em style="font-weight:600;color:#A32D2D;font-style:normal">· &#9888; ${bkV2AllergyCount(m)} ราย</em>`:''}</label>
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:5px;align-items:center">
        ${(Array.isArray(m.allergyList)?m.allergyList:[]).map((a,i)=>`<span style="display:inline-flex;align-items:center;gap:5px;background:#FCEBEB;border:1px solid #F0C9C9;color:#A32D2D;border-radius:12px;padding:4px 5px 4px 11px;font-size:11.5px;font-weight:700">${escapeHTML(a.name)} &times;<input type="number" min="1" max="99" value="${Math.floor(+a.qty||1)}" onchange="bkV2AllergySetQty(${i},this.value)" onclick="event.stopPropagation()" style="width:36px;height:21px;text-align:center;border:1px solid #E6B8B8;border-radius:4px;font-size:11px;font-weight:700;color:#A32D2D;font-family:inherit;background:#fff"><span onclick="bkV2AllergyRemove(${i})" style="cursor:pointer;color:#C77;font-size:14px;padding:0 3px;line-height:1" title="ลบ">&times;</span></span>`).join('')}
        <input id="bkv2-allerg-name" placeholder="เพิ่มสิ่งที่แพ้ เช่น Peanut" onkeydown="if(event.key==='Enter'){event.preventDefault();bkV2AllergyAdd();}" style="flex:1;min-width:150px;height:30px;box-sizing:border-box;border:1px solid var(--border);border-radius:8px;padding:0 9px;font-size:12px;font-family:inherit">
        <input id="bkv2-allerg-qty" type="number" min="1" max="99" value="1" title="จำนวนคน" style="width:48px;height:30px;box-sizing:border-box;text-align:center;border:1px solid var(--border);border-radius:8px;font-size:12px;font-weight:700;font-family:inherit">
        <button type="button" onclick="bkV2AllergyAdd()" style="height:30px;background:#A32D2D;color:#fff;border:none;border-radius:8px;padding:0 13px;font-size:11.5px;font-weight:700;cursor:pointer;font-family:inherit">+ เพิ่ม</button>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:5px;margin-top:6px">
        ${['Peanut','Tree nuts','Shellfish','Fish','Egg','Milk/Lactose','Gluten','Soy'].map(p=>`<button type="button" onclick="bkV2AllergyAddPreset('${p}')" style="font-size:10.5px;color:#7a4a4a;background:#FBF1F1;border:1px solid #EAD2D2;border-radius:11px;padding:3px 9px;cursor:pointer;font-family:inherit">+ ${p}</button>`).join('')}
      </div>
    </div>
  `;
}

// ── Cash on Tour ──
function bkV2RenderCashOnTourSection(){
  const d = _bkV2.newBooking;
  const cot = d.cashOnTour;
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  return `
    <label style="display:flex;align-items:center;gap:8px;padding:7px 11px;background:${cot?'#FFF6E5':'var(--white)'};border:1px solid ${cot?'#EAD9B0':'var(--border)'};border-radius:var(--r-sm);cursor:pointer">
      <input type="checkbox" ${cot?'checked':''} onchange="bkV2ToggleCashOnTour(this.checked)" style="accent-color:#ba7517">
      <span style="font-size:12px;color:${cot?'#633806':'var(--ink)'};font-weight:600">💰 Collect cash on tour</span>
      <span style="font-size:10px;color:var(--ink-soft);margin-left:auto">guide collects from guest on tour day</span>
    </label>
    ${cot ? `
      <div class="bkv2-nb-row" style="margin-top:10px">
        <div class="bkv2-nb-field">
          <label class="bkv2-nb-label">Amount to collect</label>
          <input class="bkv2-nb-input" type="number" min="0" step="100" placeholder="0" value="${cot.amount||''}" oninput="bkV2SetCashOnTour('amount', Number(this.value)||0)">
        </div>
        <div class="bkv2-nb-field">
          <label class="bkv2-nb-label">Currency</label>
          <select class="bkv2-nb-input" onchange="bkV2SetCashOnTour('currency', this.value)">
            ${['THB','USD','EUR','RUB','CNY','GBP','AUD'].map(c => `<option value="${c}" ${cot.currency===c?'selected':''}>${c}</option>`).join('')}
          </select>
        </div>
      </div>
      <div style="margin-top:8px">
        <div style="font-size:10px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;margin-bottom:5px">HANDLING</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
          <label style="display:flex;align-items:flex-start;gap:8px;padding:8px 11px;background:${cot.handling==='deduct'?'var(--bk-navy-50)':'var(--white)'};border:1px solid ${cot.handling==='deduct'?'var(--bk-navy-mid)':'var(--border)'};border-radius:var(--r-sm);cursor:pointer">
            <input type="radio" name="cot-handling" ${cot.handling==='deduct'?'checked':''} onchange="bkV2SetCashOnTour('handling','deduct')" style="accent-color:var(--bk-navy);margin-top:2px">
            <div><div style="font-size:11px;font-weight:700;color:${cot.handling==='deduct'?'var(--bk-navy)':'var(--ink)'}">Deduct from invoice</div><div style="font-size:9px;color:var(--ink-soft);margin-top:1px">Reduces total owed by agent</div></div>
          </label>
          <label style="display:flex;align-items:flex-start;gap:8px;padding:8px 11px;background:${cot.handling==='separate'?'var(--bk-navy-50)':'var(--white)'};border:1px solid ${cot.handling==='separate'?'var(--bk-navy-mid)':'var(--border)'};border-radius:var(--r-sm);cursor:pointer">
            <input type="radio" name="cot-handling" ${cot.handling==='separate'?'checked':''} onchange="bkV2SetCashOnTour('handling','separate')" style="accent-color:var(--bk-navy);margin-top:2px">
            <div><div style="font-size:11px;font-weight:700;color:${cot.handling==='separate'?'var(--bk-navy)':'var(--ink)'}">Keep separate</div><div style="font-size:9px;color:var(--ink-soft);margin-top:1px">Full invoice still owed</div></div>
          </label>
        </div>
      </div>
      <div style="margin-top:10px">
        <div style="font-size:10px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;margin-bottom:5px">NOTE <span style="font-weight:400;text-transform:none">· แสดงในตัวสรุป</span></div>
        <input class="bkv2-nb-input" style="width:100%;box-sizing:border-box" placeholder="เช่น เก็บค่า Longtail / สปีดโบ๊ทเพิ่ม · รายละเอียดเก็บเงิน" value="${escapeHTML(cot.note||'')}" oninput="bkV2SetCashOnTour('note', this.value)">
      </div>
    ` : ''}
  `;
}

function bkV2RenderQuoteSection(){
  const d = _bkV2.newBooking;
  const rt = bkV2GetRT();
  if(!rt) return '';
  const q = bkV2CalcQuote();
  const hasTrip = d.trips.some(t => t.routeId && t.date);
  if(!hasTrip) return '';

  const esc = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const adjRows = (d.adjustments||[]).map((a,i) => {
    const disc = a.kind === 'discount';
    const v = Number(a.value) || 0;
    const amt = disc ? (a.mode === 'percent' ? Math.round(q.base * v / 100) : Math.round(v)) : Math.round(v);
    const col = disc ? '#A32D2D' : '#0F7A5A';
    return `
      <div style="background:var(--white);border:1px solid var(--border);border-radius:var(--r-sm);padding:7px 9px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
        <span style="font-size:8px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:${col};background:${disc?'#FDECEA':'#E1F5EE'};padding:2px 6px;border-radius:4px">${disc?'Discount':'Extra'}</span>
        <input value="${esc(a.label)}" oninput="bkV2SetAdjustment(${i},'label',this.value)" placeholder="${disc?'Discount label':'Charge label'}" style="flex:1;min-width:90px;font-size:11px;padding:4px 7px">
        ${disc?`<span style="display:inline-flex;border:1px solid var(--border);border-radius:5px;overflow:hidden">
          <button onclick="bkV2SetAdjustment(${i},'mode','amount')" style="border:none;cursor:pointer;font-family:inherit;font-size:11px;padding:4px 8px;background:${a.mode!=='percent'?'var(--bk-navy)':'var(--white)'};color:${a.mode!=='percent'?'#fff':'var(--ink-soft)'}">฿</button>
          <button onclick="bkV2SetAdjustment(${i},'mode','percent')" style="border:none;cursor:pointer;font-family:inherit;font-size:11px;padding:4px 8px;background:${a.mode==='percent'?'var(--bk-navy)':'var(--white)'};color:${a.mode==='percent'?'#fff':'var(--ink-soft)'}">%</button>
        </span>`:''}
        <input type="number" min="0" value="${v||''}" onchange="bkV2SetAdjustment(${i},'value',this.value)" placeholder="0" style="width:74px;font-size:12px;padding:4px 7px;text-align:right;font-family:Manrope,sans-serif;font-variant-numeric:tabular-nums">
        <span style="min-width:74px;text-align:right;font-family:Manrope,sans-serif;font-weight:700;font-variant-numeric:tabular-nums;color:${col}">${disc?'&minus;':'+'}฿${amt.toLocaleString()}</span>
        <button onclick="bkV2RemoveAdjustment(${i})" title="Remove" style="border:none;background:transparent;cursor:pointer;color:var(--ink-soft);font-size:15px;line-height:1;padding:0 2px">&times;</button>
        <input value="${esc(a.note)}" oninput="bkV2SetAdjustment(${i},'note',this.value)" placeholder="Note (optional)" style="flex:1 1 100%;font-size:11px;padding:4px 7px;color:var(--ink-soft)">
      </div>`;
  }).join('');

  return `
    <div class="bkv2-nb-sec" style="background:var(--bk-navy-50)">
      <div class="bkv2-nb-sec-h">&#9679; Quote Summary</div>
      <div style="display:grid;grid-template-columns:1fr 130px;gap:6px 14px;font-size:12px;line-height:1.6">
        <div style="color:var(--ink-soft)">Seat rates (${d.trips.filter(t=>t.routeId).length} trip${d.trips.filter(t=>t.routeId).length===1?'':'s'})</div>
        <div style="text-align:right;font-family:Manrope,sans-serif;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums">฿${q.totalSeat.toLocaleString()}</div>
        ${q.totalAddOn>0?`<div style="color:var(--ink-soft)">Add-ons (${d.addOns.length})</div><div style="text-align:right;font-family:Manrope,sans-serif;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums">฿${q.totalAddOn.toLocaleString()}</div>`:''}
        ${q.totalFoc>0?`<div style="color:#ba7517">FOC × ${q.totalFoc} <span style="font-size:10px">· not charged · ฿${q.focDiscount.toLocaleString()} forgone</span></div><div style="text-align:right;font-family:Manrope,sans-serif;font-weight:600;color:#ba7517;font-variant-numeric:tabular-nums">&minus;฿${q.focDiscount.toLocaleString()}</div>`:''}
        ${q.totalDiscount>0?`<div style="color:#A32D2D">Discount</div><div style="text-align:right;font-family:Manrope,sans-serif;font-weight:600;color:#A32D2D;font-variant-numeric:tabular-nums">&minus;฿${q.totalDiscount.toLocaleString()}</div>`:''}
        ${q.totalExtra>0?`<div style="color:#0F7A5A">Extra charge</div><div style="text-align:right;font-family:Manrope,sans-serif;font-weight:600;color:#0F7A5A;font-variant-numeric:tabular-nums">+฿${q.totalExtra.toLocaleString()}</div>`:''}
        <div style="border-top:2px solid var(--bk-navy);padding-top:8px;margin-top:4px;color:var(--ink);font-weight:700;font-size:13px">Total</div>
        <div style="border-top:2px solid var(--bk-navy);padding-top:8px;margin-top:4px;text-align:right;font-family:Manrope,sans-serif;font-weight:700;color:var(--bk-navy);font-size:20px;font-variant-numeric:tabular-nums;letter-spacing:-.02em">฿${q.grandTotal.toLocaleString()}</div>
      </div>
      ${adjRows?`<div style="display:flex;flex-direction:column;gap:6px;margin-top:10px">${adjRows}</div>`:''}
      <div style="display:flex;gap:8px;margin-top:8px">
        <button onclick="bkV2AddAdjustment('discount')" style="font-size:11px;font-weight:600;color:#A32D2D;background:#FDECEA;border:1px solid #F5C9C4;border-radius:var(--r-sm);padding:6px 11px;cursor:pointer;font-family:inherit">+ Add discount</button>
        <button onclick="bkV2AddAdjustment('extra')" style="font-size:11px;font-weight:600;color:#0F7A5A;background:#E1F5EE;border:1px solid #B8E5D2;border-radius:var(--r-sm);padding:6px 11px;cursor:pointer;font-family:inherit">+ Add extra charge</button>
      </div>
    </div>
  `;
}

function bkV2RenderPaymentSection(){
  const d = _bkV2.newBooking;
  if(!d.agentId) return '';
  const agent = sbGetAgent(d.agentId);
  if(!agent) return '';
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);

  const method = agent.payType === 'invoice' ? 'Credit · Invoice' : 'Prepaid';
  const netDays = agent.creditDays || 0;
  const limit = agent.creditLimit || 0;
  const balance = agent.creditBalance || 0;

  return `
    <div class="bkv2-nb-sec">
      <div class="bkv2-nb-sec-h">&#9679; Payment &amp; Cash on Tour <span style="background:var(--sand-mid);color:var(--ink-soft);font-size:9px;padding:1px 7px;border-radius:3px;letter-spacing:.06em;margin-left:6px">FROM CONTRACT</span></div>
      <div style="background:var(--bk-navy-50);border:1px solid var(--bk-navy-light);border-radius:var(--r-sm);padding:11px 14px;margin-bottom:12px">
        <div style="display:flex;justify-content:space-between;font-size:13px;font-weight:600;color:var(--ink);margin-bottom:3px">
          <span>${method}${netDays?` &middot; Net ${netDays}`:''}</span>
          <span style="font-family:'DM Mono',monospace;color:var(--bk-navy)">${escapeHTML(agent.contractVersion||'no contract')}</span>
        </div>
        <div style="font-size:10px;color:var(--ink-soft);font-family:'DM Mono',monospace">
          ${limit?`Credit limit ฿${limit.toLocaleString()} · used ฿${balance.toLocaleString()} · available ฿${Math.max(0,limit-balance).toLocaleString()}`:'No credit limit set'}
        </div>
      </div>
      <div style="height:1px;background:var(--border);margin:0 0 12px"></div>
      <div style="font-size:10px;color:var(--ink-soft);font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin-bottom:6px">Cash on Tour <em style="font-weight:500;color:#b4b2a9;font-style:normal;font-size:10px;text-transform:none;letter-spacing:0">&middot; optional</em></div>
      ${bkV2RenderCashOnTourSection()}
    </div>
  `;
}

function bkV2RenderFocSection(){
  const d = _bkV2.newBooking;
  const q = bkV2CalcQuote();
  if(q.totalFoc <= 0) return '';
  const escapeHTML = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  return `
    <div class="bkv2-nb-sec" style="background:#FFF6E5;border-top:1px solid #EAD9B0">
      <div class="bkv2-nb-sec-h" style="color:#633806">&#9888; FOC Approval Required</div>
      <div style="font-size:12px;color:#633806;line-height:1.55;margin-bottom:10px">
        <strong>${q.totalFoc} FOC pax</strong> across trips &middot; ฿${q.focDiscount.toLocaleString()} forgone revenue &middot; booking will start as <strong>Pending FOC Approval</strong> until reviewed.
      </div>
      <textarea class="bkv2-nb-input" rows="3" placeholder="Reason for FOC · e.g. VIP returning client · comp for last trip issue" oninput="bkV2SetFocReason(this.value)" style="border-color:#BA7517">${escapeHTML(d.focReason)}</textarea>
    </div>
  `;
}

function bkV2RenderActionMeta(){
  const d = _bkV2.newBooking;
  const q = bkV2CalcQuote();
  const hasTrips = d.trips.some(t => t.routeId && t.date);
  if(!d.agentId) return `<div class="meta">Pick an agent to begin</div>`;
  if(!hasTrips) return `<div class="meta">Add at least 1 trip with route + date</div>`;
  const totPax = d.trips.reduce((s, t) => s + bkV2PaxAllTot(t.pax), 0);
  return `<div class="meta"><strong style="color:var(--ink)">${totPax} pax · ${d.trips.filter(t=>t.routeId).length} trip${d.trips.filter(t=>t.routeId).length===1?'':'s'}</strong> &middot; <span style="font-family:Manrope,sans-serif;color:var(--bk-navy);font-weight:700;font-variant-numeric:tabular-nums;font-size:14px;letter-spacing:-.01em">฿${q.grandTotal.toLocaleString()}</span></div>`;
}

// Detect trips with no rate for the picked route × zone combination
function bkV2NoRateTrips(){
  const d = _bkV2.newBooking;
  if(!d) return [];
  if(d.priceMode === 'manual') return [];   // manual price · rate-coverage not required
  const out = [];
  d.trips.forEach((t, i) => {
    if(!t.routeId || !t.zone) return;
    const sub = bkV2TripSubtotal(t);
    if(sub?.noRate) out.push({ idx: i, trip: t, reason: sub.reason });
  });
  return out;
}
function bkV2RenderSubmitButton(){
  const d = _bkV2.newBooking;
  if(!d) return '';
  const q = bkV2CalcQuote();
  const hasTrips = d.trips.some(t => t.routeId && t.date);
  const hasFoc = q.totalFoc > 0;
  const focOk = !hasFoc || (d.focReason||'').trim().length > 0;
  // Block save if any trip has no rate for its route×zone combo
  const noRateTrips = bkV2NoRateTrips();
  const ratesOk = noRateTrips.length === 0;
  // §rate · ใบที่ราคามาจากต้นทาง (B2C) หรือตั้งราคาเอง ไม่มีและไม่ต้องมี Rate Type
  //   ของเดิมบังคับ rateTypeRef ทุกใบ → ปุ่มนี้ปิดตายกับใบ B2C ทั้งหมด
  //   เหลือทางเดียวคือ Save Draft ที่เขียนสถานะเป็น quote (ดู §down)
  const _mnPrice = (d.priceMode==='manual') || ((typeof bkV2IsB2CBk==='function') && bkV2IsB2CBk(d));
  const ready = d.agentId && d.leadPax && (d.rateTypeRef || _mnPrice) && hasTrips && focOk && ratesOk;
  if(!ratesOk){
    return `<button class="bkv2-nb-btn" disabled title="Some trips have no rate · fix Rate Type or change route/zone" style="cursor:not-allowed;color:#A32D2D;border-color:#F5B5B5;background:#FDECEA">⚠ No rate · ${noRateTrips.length} trip${noRateTrips.length===1?'':'s'} · cannot save</button>`;
  }
  const isEdit = !!_bkV2.editingId;
  if(hasFoc){
    return `<button class="bkv2-nb-btn ${ready?'pri':''}" ${!ready?'disabled':''} onclick="bkV2SubmitBooking()" style="${ready?'background:#BA7517;border-color:#BA7517':''}">${isEdit?'Update · FOC review':'Submit · FOC review'}</button>`;
  }
  return `<button class="bkv2-nb-btn pri" ${!ready?'disabled':''} onclick="bkV2SubmitBooking()">${isEdit?'Update Booking':'Confirm Booking'} &check;</button>`;
}
// Backward-compat alias (renderBooking still calls bkV2RenderList)
function bkV2RenderList(){ bkV2Render(); }

function bkV2RenderTopbar(){
  const tab = _bkV2.tab;
  const view = _bkV2.view;
  const cur = _bkV2.cursor;
  const monthLbl = cur.toLocaleDateString('en-US', { month: 'short', year:'numeric' });
  return `
    <div class="bkv2-topbar2">
      <div class="bkv2-utabs">
        <button class="bkv2-utab ${tab==='cal'?'on':''}" onclick="bkV2SwitchTab('cal')">Calendar</button>
        <button class="bkv2-utab ${tab==='bytrip'?'on':''}" onclick="bkV2SwitchTab('bytrip')">By trip &middot; date</button>
        <button class="bkv2-utab ${tab==='all'?'on':''}" onclick="bkV2SwitchTab('all')">All bookings</button>
        <button class="bkv2-utab ${tab==='locks'?'on':''}" onclick="bkV2SwitchTab('locks')">Seat Locks</button>
        ${(function(){ const n=(SB_BOOKINGS||[]).filter(b=>b.status==='pending_approval').length; return `<button class="bkv2-utab ${tab==='approvals'?'on':''}" onclick="bkV2SwitchTab('approvals')" style="${n>0?'color:#A32D2D':''}">รออนุมัติ${n>0?` <span style="background:#A32D2D;color:#fff;border-radius:9px;padding:0 6px;font-size:10px;font-weight:700;font-family:'DM Mono',monospace">${n}</span>`:''}</button>`; })()}
        <button class="bkv2-utab ${tab==='cancel'?'on':''}" onclick="bkV2SwitchTab('cancel')">Cancellations</button>
      </div>
      ${tab==='cal' ? `
        <span class="bkv2-topdiv"></span>
        <div class="bkv2-vseg">
          <button class="bkv2-vsegbtn ${view==='cal'?'on':''}" onclick="bkV2SwitchView('cal')" title="Calendar view">&#9638;</button>
          <button class="bkv2-vsegbtn ${view==='mx'?'on':''}" onclick="bkV2SwitchView('mx')" title="Matrix view">&#9636;</button>
        </div>
        <div class="bkv2-datechip">
          <button class="bkv2-dcbtn" onclick="bkV2NavMonth(-1)">&lsaquo;</button>
          <span class="bkv2-dclbl">${monthLbl}</span>
          <button class="bkv2-dcbtn" onclick="bkV2NavMonth(1)">&rsaquo;</button>
        </div>
        <button class="bkv2-todaylink" onclick="bkV2Today()">Today</button>
      ` : ''}
      <div class="bkv2-topspacer"></div>
      <div class="bkv2-meta2">${bkV2TopbarMeta()}</div>
      <button class="bkv2-newbtn2" onclick="bkV2NewBooking()">+ New booking <span class="bkv2-kbd2">C</span></button>
    </div>
  `;
}

function bkV2TopbarMeta(){
  if(_bkV2.tab === 'cal'){
    const agg = bkV2Aggregate();
    const ym = `${_bkV2.cursor.getFullYear()}-${String(_bkV2.cursor.getMonth()+1).padStart(2,'0')}`;
    let total = 0; const bkSet = new Set();
    Object.entries(agg.byDate).forEach(([d,x]) => {
      if(d.startsWith(ym)){ total += x.total; x.bookings.forEach(id => bkSet.add(id)); }
    });
    return `${total} pax &middot; ${bkSet.size} bookings`;
  } else if(_bkV2.tab === 'bytrip'){
    if(_bkV2.filterRoute || _bkV2.filterDate){
      const r = _bkV2.filterRoute ? bkV2RouteShort(_bkV2.filterRoute) : 'any route';
      const d = _bkV2.filterDate ? bkV2FmtDate(_bkV2.filterDate) : 'any date';
      return `${r} &middot; ${d}`;
    }
    return 'no filter';
  } else if(_bkV2.tab === 'locks'){
    const active = SB_SEAT_LOCKS.filter(l=>l.status==='active' && !l.parentId);
    const dRem = active.filter(l=>!bkV2LockSpansDays(l)).reduce((s,l)=>s+bkV2LockHeldRemaining(l),0);
    const bRem = active.filter(l=>bkV2LockSpansDays(l)).reduce((s,l)=>s+(l.qty||0),0);
    return `${active.length} active &middot; ${dRem} seats held &middot; ${bRem}/รอบ`;
  } else if(_bkV2.tab === 'approvals'){
    const n = (SB_BOOKINGS||[]).filter(b=>b.status==='pending_approval').length;
    return `${n} รออนุมัติ`;
  } else if(_bkV2.tab === 'cancel'){
    const c = (SB_BOOKINGS||[]).filter(b=>b.status==='cancelled'||b.status==='cancelled_weather').length;
    return `${c} cancellation${c===1?'':'s'}`;
  } else {
    return `${SB_BOOKINGS.length} bookings total`;
  }
}

function bkV2RenderTabBody(){
  if(_bkV2.tab === 'cal'){
    return _bkV2.view === 'cal' ? bkV2RenderCalendar() : bkV2RenderMatrix();
  } else if(_bkV2.tab === 'bytrip'){
    return bkV2RenderTab2();
  } else if(_bkV2.tab === 'locks'){
    return bkV2RenderLocks();
  } else if(_bkV2.tab === 'approvals'){
    return bkV2RenderApprovals();
  } else if(_bkV2.tab === 'cancel'){
    return bkV2RenderCancelReport();
  } else {
    return bkV2RenderTab3();
  }
}
// ── Over-capacity Pending-approval queue (manager) ──
function bkV2RenderApprovals(){
  const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const pend=(SB_BOOKINGS||[]).filter(b=>b.status==='pending_approval');
  const recent=(SB_BOOKINGS||[]).filter(b=>b.approval && b.approval.status && b.approval.status!=='pending').sort((a,b)=>String(b.approval.approvedAt||'').localeCompare(String(a.approval.approvedAt||''))).slice(0,15);
  const card=(b)=>{
    const a=sbGetAgent(b.agentId); const ap=b.approval||{};
    const hasCap=(ap.over&&ap.over.length)||ap.totOver>0;
    const hasDisc=(ap.discount||0)>0;
    const accent=hasCap?'#A32D2D':'#A05A1A';
    const rows=(ap.over||[]).map(o=>`<tr><td style="padding:3px 8px">${esc(o.name)}</td><td style="padding:3px 8px;font-family:'DM Mono',monospace">${esc(o.date)}</td><td style="padding:3px 8px;text-align:center;font-family:'DM Mono',monospace">${o.need}</td><td style="padding:3px 8px;text-align:center;font-family:'DM Mono',monospace;color:#A05A1A">+${o.overBy}</td><td style="padding:3px 8px;text-align:center;font-family:'DM Mono',monospace;color:#0F6E56">${o.licFree} license</td></tr>`).join('');
    return `<div style="background:#fff;border:1px solid ${hasCap?'#F0D9D2':'#EAD9B0'};border-left:4px solid ${accent};border-radius:10px;padding:13px 15px;margin-bottom:10px">
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px">
        <span style="font-family:'DM Mono',monospace;font-weight:700;color:#1B2A55">${esc(b.id)}</span>
        <span style="font-size:12px;color:#555">${esc(b.leadPax||'—')} · ${esc(a?a.name:'')}</span>
        ${hasCap?`<span style="font-size:11px;font-weight:700;color:#A32D2D;background:#FCEBEB;border-radius:6px;padding:2px 9px">เกิน cap +${ap.totOver||0} ที่นั่ง</span>`:''}
        ${(!hasCap&&!hasDisc)?(function(){ const w=ap.reason||((typeof bkV2PendReason==='function')?bkV2PendReason(b):'');
            const cl=w==='closed_day'; return `<span style="font-size:11px;font-weight:700;color:${cl?'#A32D2D':'#7A4A00'};background:${cl?'#FCEBEB':'#FBF0DD'};border-radius:6px;padding:2px 9px" title="${cl?'ขายเข้ามาบนวันที่เส้นทางไม่ออก':'ระบบพักไว้อัตโนมัติตอน B2C sync'}">${esc(bkV2PendLabel(w))}</span>`; })():''}
        ${hasDisc?`<span style="font-size:11px;font-weight:700;color:#854F0B;background:#FAEEDA;border-radius:6px;padding:2px 9px" title="รอเซลล์${ap.saleName?(' ('+esc(ap.saleName)+')'):''}ยืนยันส่วนลด">ส่วนลด ฿${(ap.discount||0).toLocaleString()} · รอเซลล์ยืนยัน</span>`:''}
        <span style="margin-left:auto;font-size:10px;color:#999">ขอโดย ${esc(ap.requestedBy||'-')} · ${esc((ap.requestedAt||'').slice(0,10))}</span>
      </div>
      ${rows?`<table style="width:100%;border-collapse:collapse;font-size:11px;margin-bottom:10px"><thead><tr style="color:#999;font-size:9px;text-transform:uppercase"><th style="padding:3px 8px;text-align:left">Program</th><th style="padding:3px 8px;text-align:left">Date</th><th style="padding:3px 8px;text-align:center">Need</th><th style="padding:3px 8px;text-align:center">Over cap</th><th style="padding:3px 8px;text-align:center">Real seats left</th></tr></thead><tbody>${rows}</tbody></table>`:'<div style="height:4px"></div>'}
      <div style="display:flex;gap:8px;justify-content:flex-end">
        <button onclick="bkV2OpenDetail('${esc(b.id)}')" style="background:#fff;border:1px solid #ddd;border-radius:7px;padding:6px 12px;font-size:11px;cursor:pointer;font-family:inherit;color:#185FA5">ดูรายละเอียด</button>
        <button onclick="bkV2RejectBooking('${esc(b.id)}')" style="background:#fff;border:1px solid #E6C9C3;color:#A32D2D;border-radius:7px;padding:6px 12px;font-size:11px;font-weight:600;cursor:pointer;font-family:inherit">ไม่อนุมัติ</button>
        <button onclick="bkV2ApproveBooking('${esc(b.id)}')" style="background:#0F6E56;border:none;color:#fff;border-radius:7px;padding:6px 14px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit">&#10003; อนุมัติ</button>
      </div>
    </div>`;
  };
  const histRow=(b)=>{ const ap=b.approval||{}; const ok=ap.status==='approved'; return `<div style="display:flex;align-items:center;gap:9px;padding:6px 10px;border-top:1px solid #f0eee7;font-size:11px"><span style="font-family:'DM Mono',monospace;color:#1B2A55">${esc(b.id)}</span><span style="color:#666">${esc(b.leadPax||'—')}</span><span style="margin-left:auto;font-weight:700;color:${ok?'#0F6E56':'#A32D2D'}">${ok?'✓ อนุมัติ':'✕ ไม่อนุมัติ'}</span><span style="color:#999">${esc(ap.approvedBy||'')} · ${esc((ap.approvedAt||'').slice(0,10))}</span></div>`; };
  return `<div style="padding:16px 18px">
    <div style="display:flex;align-items:baseline;gap:10px;margin-bottom:14px">
      <span style="font-size:16px;font-weight:800;color:#A32D2D">รออนุมัติ</span>
      <span style="font-size:12px;color:#8a8a82">${pend.length} รายการ · ต้องอนุมัติก่อนบุคกิ้งจะ confirm</span>
    </div>
    <div style="font-size:11px;color:#8a8a82;background:#FBF3E2;border:1px solid #EAD9B0;border-radius:8px;padding:8px 11px;margin-bottom:14px"><b>เกิน Capacity</b> = เกินโควต้าบริษัท (ไม่เกินทะเบียนเรือ) → ผจก.อนุมัติ · <b>ส่วนลด</b> = มีส่วนลด → เซลล์ที่ดูแลยืนยันส่วนลดก่อน · ทั้งคู่จะ "ยังไม่ confirm" จนกว่าจะอนุมัติ</div>
    ${pend.length?pend.map(card).join(''):'<div style="text-align:center;color:#c7c5bb;font-size:13px;padding:30px">ไม่มีรายการรออนุมัติ</div>'}
    ${recent.length?`<div style="margin-top:18px"><div style="font-size:11px;font-weight:700;color:#8a8a82;text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">ประวัติล่าสุด</div>${recent.map(histRow).join('')}</div>`:''}
  </div>`;
}
// §pendNoApproval (2026-07-31) · ปุ่ม อนุมัติ / ไม่อนุมัติ กดแล้วเงียบ ไม่มีอะไรเกิดขึ้น
//   ทั้งสองฟังก์ชันขึ้นต้นด้วย  if(!b||!b.approval) return;  แต่รายการที่ b2c_sync พักไว้
//   ไม่เคยมี b.approval เลย — ฝั่งเซิร์ฟเวอร์ทำแค่ UPDATE sb_bookings SET status='pending_approval'
//   ไม่มี mapper ตัวไหนเขียนคอลัมน์ approval_* (ดูได้จากการ์ดที่ขึ้น "ขอโดย -" ว่างทั้งชื่อและวันที่)
//   รายการเข้ามาอยู่ในหน้านี้ได้เพราะลิสต์กรองด้วย status อย่างเดียว ไม่ได้เช็ค approval
//   → สร้าง approval ให้ตอนกดปุ่มแทนที่จะ return ทิ้ง · ของเดิมที่มี approval อยู่แล้วไม่ถูกแตะ
function bkV2PendReason(b){
  if(!b) return 'over_cap';
  var closed=(b.trips||[]).some(function(t){
    return t && t.date && t.routeId && typeof bkV2IsRouteOpenOn==='function' && !bkV2IsRouteOpenOn(t.routeId, t.date); });
  if(closed) return 'closed_day';
  return /^b2c_/.test(String(b.id||'')) ? 'b2c_hold' : 'over_cap';
}
function bkV2PendLabel(reason){
  return reason==='closed_day' ? 'ทริปไม่ออกวันนั้น'
       : reason==='b2c_hold'   ? 'B2C · ระบบพักไว้'
       : 'เกิน capacity';
}
function bkV2EnsureApproval(b){
  if(!b) return null;
  if(!b.approval || typeof b.approval!=='object'){
    var why=bkV2PendReason(b);
    b.approval={ status:'pending', reason:why,
      requestedBy:(/^b2c_/.test(String(b.id||''))?'B2C · ระบบพักไว้':'ระบบ'),
      requestedAt:(b.createdAt||b.bookingDate||new Date().toISOString()) };
  }
  return b.approval;
}
// §apprCap · ผลต่อที่นั่งถ้าอนุมัติใบนี้ · หักที่นั่งของใบเองออกก่อน จะได้เป็น "หลังอนุมัติ" ไม่ใช่ "ตอนนี้"
function bkV2ApprovalImpact(b){
  var out=[];
  if(!b || typeof getAllotment!=='function' || typeof bkV2PaxAllTot!=='function') return out;
  (b.trips||[]).forEach(function(t){
    if(!t || t.bookingMode==='charter' || !t.routeId || !t.date) return;
    var al=getAllotment(t.routeId, t.date, b.id);   // ไม่นับที่นั่งของใบนี้
    if(!al || !al.hasAllotment) return;
    var pax=bkV2PaxAllTot(t.pax);
    var need=pax - Math.min(Number(t.lockUse)||0, pax);
    var physFree=(al.seatsAvailable||0) + (al.lockedSeats||0);          // เพดานบริษัท ไม่สนล็อก
    var licFree=(al.licenseAvailable!=null)?al.licenseAvailable:physFree; // ที่นั่งจริงตามทะเบียนเรือ
    var r=(typeof ROUTES!=='undefined')?ROUTES.find(function(x){return x.id===t.routeId;}):null;
    out.push({ name:(r&&r.name)||t.routeId, date:t.date, need:need,
      sellable:(al.seatsAvailable||0), overCap:Math.max(0, need-physFree), overLic:Math.max(0, need-licFree) });
  });
  return out;
}
function bkV2ApprovalImpactText(imp){
  if(!imp.length) return '';
  return '\n\nที่นั่งหลังอนุมัติ:\n' + imp.map(function(o){
    return o.overLic>0 ? ('  \u26a0 '+o.name+' '+o.date+' \u00b7 '+o.need+' ที่ \u2014 เกินทะเบียนเรือ '+o.overLic+' ที่ (ไม่มีที่นั่งจริง)')
         : o.overCap>0 ? ('  \u26a0 '+o.name+' '+o.date+' \u00b7 '+o.need+' ที่ \u2014 เกินโควต้าบริษัท '+o.overCap+' ที่ (ยังอยู่ในทะเบียนเรือ)')
         : ('  \u2713 '+o.name+' '+o.date+' \u00b7 '+o.need+' ที่ \u2014 ที่นั่งพอ (เหลือ '+(o.sellable-o.need)+')');
  }).join('\n');
}
function bkV2ApproveBooking(id){
  const b=(SB_BOOKINGS||[]).find(x=>x.id===id); if(!b) return;
  bkV2EnsureApproval(b);
  const _r=b.approval.reason||''; const _isDisc=/discount/.test(_r);
  const _lbl=_isDisc?(/over_cap/.test(_r)?'เกิน cap + ส่วนลด':'ส่วนลด'):bkV2PendLabel(_r);
  // §apprCap · เกินทะเบียนเรือ = ไม่มีที่นั่งจริง · ถามซ้ำก่อน ไม่ให้กดผ่านโดยไม่ตั้งใจ
  const _imp=bkV2ApprovalImpact(b), _impTxt=bkV2ApprovalImpactText(_imp);
  const _noSeat=_imp.filter(function(o){ return o.overLic>0; });
  if(_noSeat.length && !confirm('\u26a0 ใบนี้ไม่มีที่นั่งจริงรองรับ\n'
      + _noSeat.map(function(o){ return o.name+' '+o.date+': เกินทะเบียนเรือ '+o.overLic+' ที่'; }).join('\n')
      + '\n\nอนุมัติได้ แต่ต้องเพิ่มเรือใน Boat Operation ก่อนวันเดินทาง\nยืนยันอนุมัติ?')) return;
  const by=prompt('อนุมัติบุคกิ้ง '+id+' ('+_lbl+')'+_impTxt+'\n\nชื่อผู้อนุมัติ ('+(_isDisc?'เซลล์ที่ดูแล':'ผจก.')+'):',''); if(by===null) return;
  if(!by.trim()){ alert('กรุณาใส่ชื่อผู้อนุมัติ'); return; }
  b.approval.status='approved'; b.approval.approvedBy=by.trim(); b.approval.approvedAt=new Date().toISOString();
  b.status = b.approval.targetStatus || 'confirmed';
  if(b.status==='confirmed' && !b.confirmedAt){ b.confirmedBy=by.trim(); b.confirmedAt=new Date().toISOString(); }
  if(typeof bkV2AddHistory==='function') bkV2AddHistory(b,'confirm',_lbl+' approved by '+by.trim(),'Approval');
  acctPersistBookings(); if(typeof bkV2Render==='function') bkV2Render();
  if(typeof laSaveToast==='function') laSaveToast({kind:'success', title:'อนุมัติแล้ว', id, status:(b.status||'').toUpperCase(), sub:'โดย '+by.trim()});
}
function bkV2RejectBooking(id){
  const b=(SB_BOOKINGS||[]).find(x=>x.id===id); if(!b) return;
  bkV2EnsureApproval(b);
  const _rr=b.approval.reason||'';
  const by=prompt('ไม่อนุมัติบุคกิ้ง '+id+' ('+bkV2PendLabel(_rr)+')\nชื่อผู้ไม่อนุมัติ:',''); if(by===null) return;
  if(!by.trim()){ alert('กรุณาใส่ชื่อผู้ไม่อนุมัติ'); return; }
  const note=prompt('เหตุผล (ไม่บังคับ):','')||'';
  b.approval.status='rejected'; b.approval.approvedBy=by.trim(); b.approval.approvedAt=new Date().toISOString(); b.approval.note=note.trim();
  b.status='rejected';
  if(typeof bkV2AddHistory==='function') bkV2AddHistory(b,'cancel','Over-capacity rejected by '+by.trim()+(note.trim()?(' · '+note.trim()):''),'Approval');
  acctPersistBookings(); if(typeof bkV2Render==='function') bkV2Render();
  if(typeof laSaveToast==='function') laSaveToast({kind:'error', title:'ไม่อนุมัติ (rejected)', id, status:'REJECTED', sub:'โดย '+by.trim()+(note.trim()?(' · '+note.trim()):'')});
}

// ── Cancellation report · stats off bk.cancelCategory / cancellation.group ──
function bkV2RenderCancelReport(){
  const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const fmt=n=>'฿'+Math.round(n||0).toLocaleString();
  const all=SB_BOOKINGS||[];
  const cancelled=all.filter(b=>b.status==='cancelled'||b.status==='cancelled_weather');
  const partials=[]; all.forEach(b=>(b.partialCancels||[]).forEach(pc=>partials.push({b,pc})));  // partial-cancel events
  const denom=all.filter(b=>b.status!=='rejected' && b.status!=='draft').length || 1;  // confirmed+completed+cancelled
  const paxOf=b=>(b.trips||[]).reduce((s,t)=>s+((typeof bkV2PaxAllTot==='function')?bkV2PaxAllTot(t.pax||{}):0),0);
  const REASONS=(typeof BKV2_CANCEL_REASONS!=='undefined')?BKV2_CANCEL_REASONS:[];
  const catLabel=code=> (typeof bkV2CancelLabel==='function')?bkV2CancelLabel(code):((REASONS.find(x=>x.code===code)?.en)||code||'—');
  const catGroup=code=> code==='weather'?'operator':(REASONS.find(x=>x.code===code)?.group)||'other';
  const codeOf=b=> b.status==='cancelled_weather'?'weather':(b.cancelCategory||(b.cancellation&&b.cancellation.category)||'unspecified');
  const feeOf=b=> Number((b.cancellation&&b.cancellation.chargeAmount)||0);
  // aggregate
  const byCat={}, byGroup={customer:0,operator:0,other:0}, byMonth={}, byAgent={};
  let totPax=0, totFee=0, noShow=0;
  cancelled.forEach(b=>{
    const code=codeOf(b), pax=paxOf(b), fee=feeOf(b);
    totPax+=pax; totFee+=fee; if(code==='no_show') noShow++;
    (byCat[code]=byCat[code]||{count:0,pax:0,fee:0}); byCat[code].count++; byCat[code].pax+=pax; byCat[code].fee+=fee;
    byGroup[catGroup(code)]=(byGroup[catGroup(code)]||0)+1;
    const at=(b.cancellation&&b.cancellation.at)||b.cancelledAt||''; const m=at.slice(0,7)||'—'; byMonth[m]=(byMonth[m]||0)+1;
    const aid=b.agentId||'B2C'; byAgent[aid]=(byAgent[aid]||0)+1;
  });
  // fold in partial-cancel events (pax-level · booking stays active)
  let partialPax=0;
  partials.forEach(({b,pc})=>{
    const code=pc.category||'unspecified', px=pc.count||0;
    partialPax+=px; totPax+=px; if(code==='no_show') noShow++;
    (byCat[code]=byCat[code]||{count:0,pax:0,fee:0}); byCat[code].count++; byCat[code].pax+=px;
    byGroup[catGroup(code)]=(byGroup[catGroup(code)]||0)+1;
    const at=pc.at||''; const m=at.slice(0,7)||'—'; byMonth[m]=(byMonth[m]||0)+1;
    const aid=b.agentId||'B2C'; byAgent[aid]=(byAgent[aid]||0)+1;
  });
  const pct=(n,d)=>d>0?Math.round(n/d*1000)/10:0;
  const noShowRate=pct(noShow,denom), cancelRate=pct(cancelled.length,denom);
  if(!cancelled.length && !partials.length){
    return `<div class="bkv2" style="padding:40px;text-align:center;color:var(--ink-soft,#888)"><div style="font-size:14px;font-weight:600;margin-bottom:4px">No cancellations yet</div><div style="font-size:12px">Cancelled bookings will be analysed here by reason, fault side, agent and month.</div></div>`;
  }
  const card=(inner,extra)=>`<div style="background:#fff;border:1px solid rgba(0,0,0,.08);border-radius:12px;padding:14px 16px;${extra||''}">${inner}</div>`;
  const kpi=(lab,val,sub,col)=>card(`<div style="font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#8a8a82">${lab}</div><div style="font-size:24px;font-weight:700;color:${col||'#1B2A55'};font-family:'DM Mono',monospace;margin-top:4px">${val}</div><div style="font-size:10.5px;color:#8a8a82;margin-top:1px">${sub||''}</div>`);
  const kpis=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px">
    ${kpi('Cancellations',cancelled.length,`${cancelRate}% of ${denom}${partials.length?` · +${partials.length} partial`:''}`,'#A32D2D')}
    ${kpi('Pax cancelled',totPax,partialPax?`${totPax-partialPax} full · ${partialPax} partial`:'seats released')}
    ${kpi('No-show rate',noShowRate+'%',`${noShow} no-show`,'#A05A1A')}
    ${kpi('Fees collected',fmt(totFee),'cancellation charges','#0F6E56')}
  </div>`;
  // by category bars
  const catRows=Object.entries(byCat).sort((a,b)=>b[1].count-a[1].count);
  const maxC=Math.max(...catRows.map(([,v])=>v.count),1);
  const grpColor=g=>g==='operator'?'#185FA5':g==='other'?'#8a8a82':'#A32D2D';
  const catHtml=card(`<div style="font-size:13px;font-weight:700;color:#1B2A55;margin-bottom:10px">By reason</div>`+catRows.map(([code,v])=>{
    const g=catGroup(code), w=Math.round(v.count/maxC*100);
    return `<div style="margin-bottom:9px"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:3px"><span>${esc(catLabel(code))} <span style="font-size:9px;color:#fff;background:${grpColor(g)};padding:1px 6px;border-radius:8px;text-transform:uppercase;letter-spacing:.03em">${g}</span></span><span style="font-family:'DM Mono',monospace;color:#5A5A52">${v.count} &middot; ${v.pax} pax &middot; ${fmt(v.fee)}</span></div><div style="height:7px;border-radius:4px;background:#f0eee8"><div style="width:${w}%;height:100%;border-radius:4px;background:${grpColor(g)}"></div></div></div>`;
  }).join(''));
  // fault split
  const gTot=Object.values(byGroup).reduce((a,b)=>a+b,0)||1;
  const faultHtml=card(`<div style="font-size:13px;font-weight:700;color:#1B2A55;margin-bottom:10px">Fault side</div><div style="display:flex;height:14px;border-radius:7px;overflow:hidden;margin-bottom:8px">
    <div style="width:${pct(byGroup.customer,gTot)}%;background:#A32D2D"></div><div style="width:${pct(byGroup.operator,gTot)}%;background:#185FA5"></div><div style="width:${pct(byGroup.other,gTot)}%;background:#8a8a82"></div></div>
    <div style="display:flex;gap:14px;font-size:11.5px;color:#5A5A52"><span><span style="color:#A32D2D">&#9632;</span> Customer ${byGroup.customer} (${pct(byGroup.customer,gTot)}%)</span><span><span style="color:#185FA5">&#9632;</span> Operator ${byGroup.operator} (${pct(byGroup.operator,gTot)}%)</span><span><span style="color:#8a8a82">&#9632;</span> Other ${byGroup.other}</span></div>`);
  // top agents
  const agentRows=Object.entries(byAgent).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const agName=aid=> aid==='B2C'?'B2C / Walk-in':((typeof sbGetAgent==='function'&&sbGetAgent(aid))?sbGetAgent(aid).name:aid);
  const agentsHtml=card(`<div style="font-size:13px;font-weight:700;color:#1B2A55;margin-bottom:10px">Top cancelling agents</div>`+agentRows.map(([aid,n])=>`<div style="display:flex;justify-content:space-between;font-size:12px;padding:5px 0;border-bottom:0.5px solid rgba(0,0,0,.05)"><span>${esc(agName(aid))}</span><span style="font-family:'DM Mono',monospace;font-weight:700;color:#A32D2D">${n}</span></div>`).join(''));
  // by month
  const monthRows=Object.entries(byMonth).sort((a,b)=>a[0]<b[0]?-1:1);
  const maxM=Math.max(...monthRows.map(([,n])=>n),1);
  const monthHtml=card(`<div style="font-size:13px;font-weight:700;color:#1B2A55;margin-bottom:10px">By month</div>`+monthRows.map(([m,n])=>`<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><span style="width:62px;font-size:11px;font-family:'DM Mono',monospace;color:#5A5A52">${esc(m)}</span><div style="flex:1;height:7px;border-radius:4px;background:#f0eee8"><div style="width:${Math.round(n/maxM*100)}%;height:100%;border-radius:4px;background:#185FA5"></div></div><span style="width:22px;text-align:right;font-size:11px;font-family:'DM Mono',monospace">${n}</span></div>`).join(''));
  return `<div class="bkv2" style="padding:18px">${kpis}<div style="display:grid;grid-template-columns:1.3fr 1fr;gap:12px;align-items:start;margin-bottom:12px">${catHtml}<div style="display:flex;flex-direction:column;gap:12px">${faultHtml}${agentsHtml}</div></div>${monthHtml}</div>`;
}

// ── Tab 1 · Calendar view (matches sidebar Calendar layout) ──
function bkV2RenderCalendar(){
  const cur = _bkV2.cursor;
  const year = cur.getFullYear();
  const month = cur.getMonth();
  const agg = bkV2Aggregate();
  const first = new Date(year, month, 1);
  // Sun-first grid (matches sidebar Calendar): Sun=0 ... Sat=6
  const dowFirst = first.getDay();
  const lastDay = new Date(year, month+1, 0).getDate();
  const todayKey = bkV2DateKey(new Date());

  const routeColor = (rid) => {
    const r = (typeof ROUTES !== 'undefined') ? ROUTES.find(rr => rr.id === rid) : null;
    return r?.color || '#9C9C95';
  };

  // Active families for the visible month (consults Programs · seasons)
  const activeFams = bkV2Families();
  // Program filter (multi-select) · empty/none = show ALL
  const calSelArr = Array.isArray(_bkV2.calFams) ? _bkV2.calFams : [];
  const calSel = calSelArr.length ? new Set(calSelArr) : null;

  const cells = [];
  for(let i = 0; i < dowFirst; i++) cells.push(`<div class="bkv2-cal-cell empty"></div>`);
  for(let d = 1; d <= lastDay; d++){
    const dateKey = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const x = agg.byDate[dateKey];
    const sel = _bkV2.selected?.date === dateKey && !_bkV2.selected?.routeId && !_bkV2.selected?.familyId;
    const isToday = dateKey === todayKey;
    const dow = new Date(year, month, d).getDay();
    const weekend = dow === 0 || dow === 6;
    // §bkCalPast · อดีต = ก่อนวันนี้ · วันนี้ยังรับจองได้ ไม่นับ
    const isPast = dateKey < todayKey;
    const cls = ['bkv2-cal-cell', sel?'sel':'', weekend?'weekend':'', isToday?'today':'', isPast?'past':''].filter(Boolean).join(' ');

    // Build chips for ALL families that are OPEN on this day (any sub-route open)
    // Chip shows family name + total pax (sum across sub-variants) · "empty" if no bookings
    let chipsHtml = '';
    let dayHasFoc = false;
    const openFams = activeFams
      .map(fam => ({ fam, agg: bkV2FamilyAggregate(fam.id, dateKey, agg), open: bkV2IsFamilyOpenOn(fam.id, dateKey) }))
      .filter(o => o.open && (!calSel || calSel.has(o.fam.id)));
    // Day total pax across the visible (filtered) programs
    const dayTotal = openFams.reduce((s, o) => s + (o.agg.total || 0), 0);
    if(openFams.length){
      openFams.sort((a, b) => b.agg.total - a.agg.total);
      const visible = openFams.slice(0, 5);
      const overflow = openFams.length - visible.length;
      chipsHtml = visible.map(({ fam, agg: famAgg }) => {
        const col = fam.color;
        const pax = famAgg.total;
        const focCls = famAgg.hasFocPending ? ' foc' : '';
        const emptyCls = pax === 0 ? ' empty' : '';
        if(famAgg.hasFocPending) dayHasFoc = true;
        const famWx = (typeof bkV2IsWeatherClosed==='function') && (bkV2FamilyRoutes(fam.id)||[]).some(rd => bkV2IsWeatherClosed((rd.id||rd), dateKey));
        if(famWx){
          return `<div class="bkv2-cal-chip${emptyCls}" style="border-left-color:#A32D2D" title="${fam.name} · Cancelled (weather)"><span class="bkv2-cal-chip-name" style="color:#A32D2D">&#9928; ${fam.name}</span>${pax > 0 ? `<span class="bkv2-cal-chip-pax" style="color:#A32D2D;text-decoration:line-through">${pax}</span>` : ''}</div>`;
        }
        return `<div class="bkv2-cal-chip${focCls}${emptyCls}" style="border-left-color:${col}" title="${fam.name}"><span class="bkv2-cal-chip-name" style="color:${col}">${fam.name}</span>${pax > 0 ? `<span class="bkv2-cal-chip-pax" style="color:${col}">${pax}</span>` : ''}</div>`;
      }).join('');
      if(overflow > 0) chipsHtml += `<div class="bkv2-cal-more">+${overflow} more</div>`;
    }
    const showFocDot = x?.hasFocPending || dayHasFoc;

    const lockedDay = (typeof bkV2DayLockedExact==='function') ? bkV2DayLockedExact(dateKey) : 0;
    const lockBadge = lockedDay>0 ? `<div class="bkv2-cal-lock" title="${lockedDay} seat(s) locked this day">&#128274; ${lockedDay}</div>` : '';
    const dayTotBadge = dayTotal > 0 ? `<span class="bkv2-cal-daytot" title="${dayTotal} pax total this day">${dayTotal}</span>` : '';
    cells.push(`<div class="${cls}" onclick="bkV2SelectDay('${dateKey}')" ondblclick="bkV2OpenFiltered('','${dateKey}')" title="Click to preview · double-click to open By trip date"><div class="bkv2-cal-daynum"><span>${String(d).padStart(2,'0')}</span>${showFocDot?'<span class="bkv2-cal-foc"></span>':''}${dayTotBadge}</div>${chipsHtml}${lockBadge}</div>`);
  }

  return `
    ${bkV2RenderStats()}
    ${bkV2RenderRouteAvgs()}
    <div class="bkv2-split">
      <div class="bkv2-cal">
        <div class="bkv2-cal-filter">
          <span class="bkv2-cal-filter-lab">Programs</span>
          <button class="bkv2-cal-fpill${!calSel?' on':''}" onclick="bkV2CalAllFamilies()">All</button>
          ${activeFams.map(f => `<button class="bkv2-cal-fpill${calSel&&calSel.has(f.id)?' on':''}" style="--fc:${f.color}" onclick="bkV2CalToggleFamily('${f.id}')"><span class="dot" style="background:${f.color}"></span>${f.name}</button>`).join('')}
        </div>
        <div class="bkv2-cal-wdrow">
          <div class="bkv2-cal-wd" style="opacity:.7">Sun</div>
          <div class="bkv2-cal-wd">Mon</div><div class="bkv2-cal-wd">Tue</div><div class="bkv2-cal-wd">Wed</div>
          <div class="bkv2-cal-wd">Thu</div><div class="bkv2-cal-wd">Fri</div>
          <div class="bkv2-cal-wd" style="opacity:.7">Sat</div>
        </div>
        <div class="bkv2-cal-grid">${cells.join('')}</div>
      </div>
      ${bkV2RenderSelDay()}
    </div>
    ${bkV2RenderFooterHints('cal')}
  `;
}

// Calendar program filter (multi-select · empty = show all)
function bkV2CalToggleFamily(id){
  let s = Array.isArray(_bkV2.calFams) ? _bkV2.calFams.slice() : [];
  const i = s.indexOf(id);
  if(i >= 0) s.splice(i, 1); else s.push(id);
  _bkV2.calFams = s;
  bkV2Render();
}
function bkV2CalAllFamilies(){ _bkV2.calFams = []; bkV2Render(); }

// Stats cards row (4 cards · matches Calendar page top stats with navy hero)
function bkV2RenderStats(){
  const cur = _bkV2.cursor;
  const ym = `${cur.getFullYear()}-${String(cur.getMonth()+1).padStart(2,'0')}`;
  const agg = bkV2Aggregate();
  const todayKey = bkV2DateKey(new Date());
  const monthLbl = cur.toLocaleDateString('en-US', { month:'long', year:'numeric' }).toUpperCase();

  let mPax=0, mBkSet=new Set(), mFocPending=0, mConfirmed=0, mConfirmedPax=0;
  Object.entries(agg.byDate).forEach(([d,x]) => {
    if(!d.startsWith(ym)) return;
    mPax += x.total;
    x.bookings.forEach(id => mBkSet.add(id));
  });
  SB_BOOKINGS.forEach(bk => {
    const norm = bkV2Norm(bk);
    const t = norm.travelDate || '';
    if(!t.startsWith(ym)) return;
    if(norm.status === 'pending_foc') mFocPending++;
    if(norm.status === 'confirmed'){ mConfirmed++; mConfirmedPax += norm.paxTotal; }
  });
  const lastDay = new Date(cur.getFullYear(), cur.getMonth()+1, 0).getDate();
  const weeksInMonth = Math.max(1, Math.ceil(lastDay / 7));
  const avgPerWeek = Math.round(mPax / weeksInMonth);

  // Today's stats
  const tx = agg.byDate[todayKey];
  const tPax = tx?.total || 0;
  const tBookings = tx?.bookings?.length || 0;
  const tIsCur = todayKey.startsWith(ym);

  return `
    <div class="bkv2-stats">
      <div class="bkv2-stat hero">
        <div class="s-lab">${monthLbl}</div>
        <div class="s-val">${mBkSet.size} <span class="s-unit">bookings</span></div>
        <div class="s-foot">${mPax} pax &middot; avg ${avgPerWeek}/week</div>
      </div>
      <div class="bkv2-stat success">
        <div class="s-lab">Confirmed</div>
        <div class="s-val">${mConfirmed} <span class="s-unit">bookings</span></div>
        <div class="s-foot">${mConfirmedPax} pax in month</div>
      </div>
      <div class="bkv2-stat warn">
        <div class="s-lab">Pending FOC</div>
        <div class="s-val">${mFocPending} <span class="s-unit">awaiting</span></div>
        <div class="s-foot">${mFocPending>0?'review needed':'all clear'}</div>
      </div>
      <div class="bkv2-stat">
        <div class="s-lab">Today</div>
        <div class="s-val">${tIsCur?tPax:'—'} <span class="s-unit">${tIsCur?'pax':''}</span></div>
        <div class="s-foot">${tIsCur?(tBookings+' trips today'):'not in view'}</div>
      </div>
    </div>
  `;
}

// Per-route avg cards row with Weekly/Daily/Total toggle
function bkV2RenderRouteAvgs(){
  const cur = _bkV2.cursor;
  const ym = `${cur.getFullYear()}-${String(cur.getMonth()+1).padStart(2,'0')}`;
  const agg = bkV2Aggregate();
  const lastDay = new Date(cur.getFullYear(), cur.getMonth()+1, 0).getDate();
  const weeksInMonth = Math.max(1, Math.ceil(lastDay / 7));

  // Aggregate per route for the month
  const perRoute = {};
  bkV2Routes().forEach(rd => { perRoute[rd.id] = { pax:0, daysRan:0, bookings:0 }; });
  Object.entries(agg.byDate).forEach(([d, day]) => {
    if(!d.startsWith(ym)) return;
    Object.entries(day.routes).forEach(([rid, r]) => {
      if(!perRoute[rid]) perRoute[rid] = { pax:0, daysRan:0, bookings:0 };
      perRoute[rid].pax += r.total;
      perRoute[rid].daysRan += (r.total > 0 ? 1 : 0);
    });
  });
  // bookings count per route this month
  const bkPerRoute = {};
  SB_BOOKINGS.forEach(bk => {
    if(bk.schemaVer === 2 && Array.isArray(bk.trips)){
      bk.trips.forEach(t => {
        if(t.date && t.date.startsWith(ym)){
          if(!bkPerRoute[t.routeId]) bkPerRoute[t.routeId] = new Set();
          bkPerRoute[t.routeId].add(bk.id);
        }
      });
    } else if(bk.travelDate && bk.travelDate.startsWith(ym) && bk.programId){
      if(!bkPerRoute[bk.programId]) bkPerRoute[bk.programId] = new Set();
      bkPerRoute[bk.programId].add(bk.id);
    }
  });
  Object.entries(bkPerRoute).forEach(([rid, set]) => {
    if(perRoute[rid]) perRoute[rid].bookings = set.size;
  });

  const mode = _bkV2.avgMode || 'week';
  const modeLab = { week:'pax /week', day:'pax /day', total:'pax total' }[mode];
  const sub = { week:'÷ weeks in month', day:'÷ days route ran', total:'sum of all pax' }[mode];

  const routeColor = (rid) => {
    const r = (typeof ROUTES !== 'undefined') ? ROUTES.find(rr => rr.id === rid) : null;
    return r?.color || '#9C9C95';
  };

  // Aggregate by family · sum sub-routes
  const cards = bkV2Families().map(fam => {
    const subRoutes = bkV2FamilyRoutes(fam.id);
    let pax = 0, daysRan = 0, bookings = 0;
    const dayRanSet = new Set();
    const bkSet = new Set();
    subRoutes.forEach(rd => {
      const p = perRoute[rd.id] || { pax:0, daysRan:0, bookings:0 };
      pax += p.pax;
    });
    // Recompute daysRan + bookings at family level (any sub-route running = family day)
    Object.entries(agg.byDate).forEach(([d, day]) => {
      if(!d.startsWith(ym)) return;
      const famHadActivity = subRoutes.some(rd => (day.routes[rd.id]?.total || 0) > 0);
      if(famHadActivity) dayRanSet.add(d);
    });
    daysRan = dayRanSet.size;
    SB_BOOKINGS.forEach(bk => {
      if(bk.schemaVer === 2 && Array.isArray(bk.trips)){
        bk.trips.forEach(t => {
          if(t.date && t.date.startsWith(ym) && bkV2RouteFamily(t.routeId)?.id === fam.id){
            bkSet.add(bk.id);
          }
        });
      } else if(bk.travelDate && bk.travelDate.startsWith(ym) && bk.programId){
        if(bkV2RouteFamily(bk.programId)?.id === fam.id) bkSet.add(bk.id);
      }
    });
    bookings = bkSet.size;

    let val = 0;
    if(mode === 'week') val = Math.round(pax / weeksInMonth);
    else if(mode === 'day') val = daysRan > 0 ? Math.round(pax / daysRan) : 0;
    else val = pax;

    return `
      <div class="bkv2-route-card" style="border-left-color:${fam.color}">
        <div class="rc-name">${fam.name}</div>
        <div class="rc-meta">${bookings} bookings &middot; ${daysRan} day${daysRan===1?'':'s'} ran &middot; ${subRoutes.length} variant${subRoutes.length===1?'':'s'}</div>
        <div class="rc-row">
          <div class="rc-unit">${modeLab}</div>
          <div class="rc-val">${val}</div>
        </div>
      </div>
    `;
  }).join('');

  return `
    <div class="bkv2-routes">
      <div class="bkv2-routes-hd">
        <span class="bkv2-routes-ttl">Avg pax &middot; per program</span>
        <span class="bkv2-routes-sub">${sub}</span>
        <div class="bkv2-mode">
          <button class="bkv2-mode-btn ${mode==='week'?'on':''}" onclick="bkV2SetAvgMode('week')">Weekly</button>
          <button class="bkv2-mode-btn ${mode==='day'?'on':''}" onclick="bkV2SetAvgMode('day')">Daily</button>
          <button class="bkv2-mode-btn ${mode==='total'?'on':''}" onclick="bkV2SetAvgMode('total')">Total</button>
        </div>
      </div>
      <div class="bkv2-routes-grid">${cards}</div>
    </div>
  `;
}

// Selected Day panel (right side · matches Calendar page SELECTED DAY panel)
function bkV2RenderSelDay(){
  const sel = _bkV2.selected;
  if(!sel){
    return `
      <div class="bkv2-selday">
        <div class="bkv2-selday-lab">Selected Day</div>
        <div class="bkv2-selday-ttl">No day selected</div>
        <div class="bkv2-selday-empty">Click a day in the calendar to see breakdown<br>AD &middot; CHD &middot; INF &middot; FOC + PK &middot; KL &middot; NT</div>
      </div>
    `;
  }

  const agg = bkV2Aggregate();
  const x = agg.byDate[sel.date];
  const dt = new Date(sel.date + 'T00:00');
  const dateLbl = dt.toLocaleDateString('en-US', { weekday:'long', day:'numeric', month:'long' });
  const todayKey = bkV2DateKey(new Date());
  const isToday = sel.date === todayKey;

  // Seat-locks block · show ONLY routes that already have a lock · one "Lock seats" button to create (route picked in modal)
  const _escR = s => String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
  const _lockedRts = (typeof ROUTES!=='undefined'?ROUTES:[]).filter(r => (typeof bkV2LockedTotal==='function' ? bkV2LockedTotal(r.id, sel.date) : 0) > 0);
  const lockRouteSection = `
    <div style="margin-top:14px">
      <div class="bkv2-selday-lab" style="margin-bottom:6px">&#128274; Seat locks</div>
      ${_lockedRts.length ? _lockedRts.map(r => {
        const lk = bkV2LockedTotal(r.id, sel.date);
        return `<div onclick="bkV2SwitchTab('locks')" title="Manage in Seat Locks tab" style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #f5f3ef;cursor:pointer">
          <span style="width:3px;height:18px;border-radius:3px;background:${r.color||'#ccc'};flex:none"></span>
          <span style="flex:1;min-width:0;font-size:12px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${_escR(r.name)}">${_escR(r.name)}</span>
          <span style="font-size:11px;color:#C0392B;font-weight:700;font-family:'DM Mono',monospace">&#128274; ${lk}</span>
        </div>`;
      }).join('') : '<div style="font-size:11px;color:var(--ink-soft);font-style:italic;margin-bottom:4px">No seat locks on this day</div>'}
      <button onclick="bkV2LockFromCalendar('','${sel.date}')" style="margin-top:10px;width:100%;border:1px solid #EAC6BF;background:#FBEAE6;color:#C0392B;border-radius:8px;font-size:12px;font-weight:700;padding:8px;cursor:pointer;font-family:inherit">&#128274; Lock seats</button>
    </div>`;

  if(!x){
    return `
      <div class="bkv2-selday">
        <div class="bkv2-selday-lab">Selected Day</div>
        <div class="bkv2-selday-ttl">${dateLbl}${isToday?'<span class="bkv2-selday-today">Today</span>':''}</div>
        <div class="bkv2-selday-empty">No bookings on this day</div>
        ${lockRouteSection}
      </div>
    `;
  }

  // Week context (Sun-Sat) — find week range and aggregate
  const dayDow = dt.getDay();
  const weekStart = new Date(dt); weekStart.setDate(dt.getDate() - dayDow);
  const weekEnd = new Date(weekStart); weekEnd.setDate(weekStart.getDate() + 6);
  let weekPax = 0, weekTrips = 0;
  for(let i=0; i<7; i++){
    const dd = new Date(weekStart); dd.setDate(weekStart.getDate() + i);
    const k = bkV2DateKey(dd);
    if(agg.byDate[k]){ weekPax += agg.byDate[k].total; weekTrips += Object.keys(agg.byDate[k].routes).length; }
  }
  const weekStartLbl = weekStart.toLocaleDateString('en-US', { day:'numeric', month:'short' });
  const weekEndLbl = weekEnd.toLocaleDateString('en-US', { day:'numeric', month:'short' });
  const avgPerDay = Math.round(weekPax / 7);

  const routeColor = (rid) => {
    const r = (typeof ROUTES !== 'undefined') ? ROUTES.find(rr => rr.id === rid) : null;
    return r?.color || '#9C9C95';
  };

  // Build family cards · each card = 1 program family with sub-route breakdown
  // Sorted by family pax desc · only families with data this day
  const famsWithData = bkV2Families()
    .map(fam => ({ fam, agg: bkV2FamilyAggregate(fam.id, sel.date, agg) }))
    .filter(o => o.agg.total > 0 || ((typeof bkV2IsWeatherClosed==='function') && bkV2FamilyRoutes(o.fam.id).some(rd => bkV2IsWeatherClosed(rd.id, sel.date))))
    .sort((a, b) => b.agg.total - a.agg.total);

  const routesHtml = famsWithData.map(({ fam, agg: famAgg }) => {
    // Sub-route breakdown (sorted by pax desc)
    const subRoutes = bkV2FamilyRoutes(fam.id);
    const subs = subRoutes
      .map(rd => ({ rd, data: x.routes[rd.id] }))
      .filter(s => s.data)
      .sort((a, b) => b.data.total - a.data.total);

    // Compact pax breakdown · order: Total · A · C · I · F (skip zeros)
    const fmtCompact = (r) => {
      const parts = [];
      if(r.ad)  parts.push(`<span style="color:var(--ink);font-weight:600">${r.ad}A</span>`);
      if(r.chd) parts.push(`<span style="color:var(--ink);font-weight:600">${r.chd}C</span>`);
      if(r.inf) parts.push(`<span style="color:var(--ink);font-weight:600">${r.inf}I</span>`);
      if(r.foc) parts.push(`<span style="color:#ba7517;font-weight:700">${r.foc}F</span>`);
      return parts.join(' <span style="color:var(--ink-soft)">&middot;</span> ');
    };

    // Sub-variant rows · compact · indent + name + (total · A·C·I·F) + capacity bar
    const subsHtml = subs.map(s => {
      const r = s.data;
      const breakdown = fmtCompact(r);
      const _swx = (typeof bkV2IsWeatherClosed==='function') && bkV2IsWeatherClosed(s.rd.id, sel.date);
      // Capacity meter (Phase 8)
      let capBarHtml = '';
      if(typeof getAllotment === 'function'){
        const al = getAllotment(s.rd.id, sel.date);
        if(al.hasAllotment){
          const usedPct = al.availableCapacity > 0 ? Math.min(100, Math.round(al.seatsConsumed / al.availableCapacity * 100)) : 0;
          const charterPct = al.totalCapacity > 0 ? Math.round(al.charterCapacity / al.totalCapacity * 100) : 0;
          const barColor = al.state === 'full' || al.state === 'all-chartered' ? '#a32d2d' : usedPct >= 70 ? '#A05A1A' : '#0F6E56';
          capBarHtml = `
            <div style="padding:2px 12px 5px 22px;font-size:9px;color:var(--ink-soft);font-family:'Manrope',sans-serif;font-variant-numeric:tabular-nums;display:flex;align-items:center;gap:6px">
              <div style="flex:1;height:5px;background:#f5f3ef;border-radius:3px;overflow:hidden;display:flex">
                ${al.charterCapacity > 0 ? `<div style="width:${charterPct}%;background:#6B289A" title="Charter ${al.charterCapacity}"></div>` : ''}
                <div style="width:${Math.max(0, 100 - charterPct) * usedPct / 100}%;background:${barColor}" title="${al.seatsConsumed} booked"></div>
              </div>
              <span style="white-space:nowrap">${al.seatsConsumed}/${al.availableCapacity}${al.charterCapacity>0?` +${al.charterCapacity}⚓`:''}</span>
            </div>
          `;
        } else {
          capBarHtml = `<div style="padding:2px 12px 5px 22px;font-size:9px;color:#A05A1A;font-style:italic">⚠ no boat assigned</div>`;
        }
      }
      if(_swx){
        const wc=(typeof bkV2WeatherCountsFor==='function')?bkV2WeatherCountsFor(s.rd.id,sel.date):{cancelled:0,rescheduled:0,pending:0};
        capBarHtml = `<div style="padding:2px 12px 6px 22px;font-size:9px;font-weight:700;color:#A32D2D">&#9928; Cancelled (weather) · &#8635; ${wc.rescheduled} resched · &#10005; ${wc.cancelled} cxl${wc.pending>0?` · &#8230; ${wc.pending} pending`:''}</div>`;
      }
      return `
        <div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:5px 12px 1px 22px;border-bottom:0;font-size:11px;line-height:1.4">
          <span style="font-family:'DM Sans',sans-serif;color:${_swx?'#A32D2D':'var(--ink-soft)'};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;min-width:0" title="${s.rd.full}">${_swx?'&#9928; ':''}${s.rd.full}</span>
          <span style="font-family:'DM Mono',monospace;color:var(--ink-soft);font-size:10.5px;flex-shrink:0;letter-spacing:-.01em"><span style="color:${_swx?'#A32D2D':'var(--ink)'};font-weight:700;font-size:12px;${_swx?'text-decoration:line-through':''}">${r.total}</span>${breakdown?` <span style="color:var(--ink-soft)">&middot;</span> ${breakdown}`:''}${(typeof bkV2LockedTotal==='function' && bkV2LockedTotal(s.rd.id, sel.date)>0)?` <span style="color:#C0392B;font-weight:700">&#128274;${bkV2LockedTotal(s.rd.id, sel.date)}</span>`:''}</span>
        </div>
        ${capBarHtml}
        <div style="border-bottom:1px solid #f5f3ef"></div>
      `;
    }).join('');

    // Weather-cancelled family → summary card (Original / Rescheduled / Cancelled / Pending) · like By-trip-date
    const famWxRoutes = subRoutes.filter(rd => (typeof bkV2IsWeatherClosed==='function') && bkV2IsWeatherClosed(rd.id, sel.date));
    if(famWxRoutes.length){
      const wcF={cancelled:0,rescheduled:0,pending:0,total:0};
      famWxRoutes.forEach(rd=>{ const c=(typeof bkV2WeatherCountsFor==='function')?bkV2WeatherCountsFor(rd.id,sel.date):{cancelled:0,rescheduled:0,pending:0,total:0}; wcF.cancelled+=c.cancelled; wcF.rescheduled+=c.rescheduled; wcF.pending+=c.pending; wcF.total+=c.total; });
      return `
        <div style="border:1px solid #E89A92;border-left:3px solid #A32D2D;border-radius:var(--r-sm);margin-bottom:8px;overflow:hidden">
          <div style="background:#FDEEEC;padding:7px 12px;display:flex;align-items:baseline;justify-content:space-between;gap:8px">
            <div style="flex:1;min-width:0">
              <div style="font-family:'DM Sans',sans-serif;font-size:13px;font-weight:700;color:#A32D2D;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${fam.name}">&#9928; ${fam.name}</div>
              <div style="font-size:9.5px;color:#9a3b30;margin-top:1px">Cancelled (weather)</div>
            </div>
            <div style="text-align:right;flex-shrink:0">
              <div style="font-family:'DM Mono',monospace;font-weight:700;font-size:18px;color:#A32D2D;letter-spacing:-.02em">${wcF.total}</div>
              <div style="font-size:8px;color:#9a3b30;text-transform:uppercase;letter-spacing:.04em">original</div>
            </div>
          </div>
          <div style="display:flex;gap:5px;flex-wrap:wrap;padding:7px 12px;background:#fff">
            <span style="font-size:10px;font-weight:600;background:#E6F1FB;color:#185FA5;padding:2px 8px;border-radius:6px">&#8635; Rescheduled ${wcF.rescheduled}</span>
            <span style="font-size:10px;font-weight:600;background:#FCEBEB;color:#A32D2D;padding:2px 8px;border-radius:6px">&#10005; Cancelled ${wcF.cancelled}</span>
            ${wcF.pending>0?`<span style="font-size:10px;font-weight:600;background:#FBF0DD;color:#7A4A00;padding:2px 8px;border-radius:6px">&#8230; Pending ${wcF.pending}</span>`:''}
          </div>
          ${subsHtml}
        </div>
      `;
    }
    return `
      <div style="border:1px solid var(--border);border-left:3px solid ${fam.color};border-radius:var(--r-sm);margin-bottom:8px;overflow:hidden">
        <div style="background:#f5f3ef;padding:7px 12px;display:flex;align-items:baseline;justify-content:space-between;gap:8px">
          <div style="flex:1;min-width:0">
            <div style="font-family:'DM Sans',sans-serif;font-size:13px;font-weight:700;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${fam.name}">${fam.name}${famAgg.hasFocPending?` <span class="bkv2-rd-foc">FOC ${famAgg.foc}</span>`:''}</div>
            <div style="font-family:'DM Mono',monospace;font-size:10px;color:var(--ink-soft);margin-top:2px;line-height:1.5">${fmtCompact(famAgg) || '<span style="font-style:italic">no pax</span>'}${famAgg.pk||famAgg.kl||famAgg.nt?' <span>&middot;</span> ':''}${famAgg.pk?`<span>PK ${famAgg.pk}</span>`:''}${famAgg.kl?` <span>KL ${famAgg.kl}</span>`:''}${famAgg.nt?` <span>NT ${famAgg.nt}</span>`:''}</div>
          </div>
          <div style="font-family:'DM Mono',monospace;font-weight:700;font-size:18px;color:var(--ink);flex-shrink:0;letter-spacing:-.02em">${famAgg.total}</div>
        </div>
        ${subsHtml}
      </div>
    `;
  }).join('');

  return `
    <div class="bkv2-selday">
      <div class="bkv2-selday-lab">Selected Day</div>
      <div class="bkv2-selday-ttl">${dateLbl}${isToday?'<span class="bkv2-selday-today">Today</span>':''}</div>
      <div class="bkv2-week-summary">
        <div>
          <div class="ws-lab">This week (${weekStartLbl}–${weekEndLbl})</div>
          <div class="ws-meta">Avg ${avgPerDay} pax/day &middot; ${weekTrips} trips</div>
        </div>
        <div style="text-align:right">
          <div class="ws-total">${weekPax}</div>
          <div class="ws-totlab">Week total</div>
        </div>
      </div>
      ${routesHtml || '<div class="bkv2-rd-empty-msg">No routes ran on this day</div>'}
      ${lockRouteSection}
      <div class="bkv2-rd-actions">
        <button onclick="bkV2OpenFiltered('','${sel.date}')" class="pri">Open day's bookings &rarr;</button>
      </div>
    </div>
  `;
}

// Event handler for avg mode toggle
function bkV2SetAvgMode(m){ _bkV2.avgMode = m; bkV2Render(); }

// ── Tab 1 · Matrix view ──
function bkV2RenderMatrix(){
  const cur = _bkV2.cursor;
  const year = cur.getFullYear();
  const month = cur.getMonth();
  const lastDay = new Date(year, month+1, 0).getDate();
  const agg = bkV2Aggregate();
  const todayKey = bkV2DateKey(new Date());

  let headers = `<th class="rowh">Route</th>`;
  const dayTotals = [];
  for(let d = 1; d <= lastDay; d++){
    const dt = new Date(year, month, d);
    const dow = dt.getDay();
    const weekend = dow === 0 || dow === 6;
    const dowLetter = ['S','M','T','W','T','F','S'][dow];
    const dateKey = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isToday = dateKey === todayKey;
    const dhSel = _bkV2.selected?.date === dateKey ? 'sel' : '';
    headers += `<th class="dh ${weekend?'weekend':''} ${isToday?'today':''} ${dhSel}" onclick="bkV2SelectDay('${dateKey}')" title="View ${dateKey}">${dowLetter}<span class="dnum">${d}</span></th>`;
    dayTotals.push(0);
  }

  // Family-grouped rows · parent rows shown by default · click to expand sub-routes
  const fams = bkV2Families();
  const rows = fams.map(fam => {
    const subRoutes = bkV2FamilyRoutes(fam.id);
    const isExpanded = _bkV2.expanded.has(fam.id);

    // Parent row · aggregate pax across all sub-routes per day
    let parentRow = `<td class="rowh" onclick="bkV2ToggleFamily('${fam.id}')" style="border-left-color:${fam.color}"><span class="caret">${isExpanded?'▾':'▸'}</span>${fam.name}<span class="subc">${subRoutes.length} variant${subRoutes.length===1?'':'s'}</span></td>`;
    for(let d = 1; d <= lastDay; d++){
      const dateKey = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
      const famOpen = bkV2IsFamilyOpenOn(fam.id, dateKey);
      const famData = bkV2FamilyAggregate(fam.id, dateKey, agg);
      const sel = _bkV2.selected?.date === dateKey && _bkV2.selected?.familyId === fam.id;
      // All sub-routes closed AND no bookings → off-season hatch
      if(!famOpen && famData.total === 0){ parentRow += `<td class="cell closed" title="All routes in this family closed">&times;</td>`; continue; }
      // Family open but no bookings → empty (available · clickable)
      if(famData.total === 0){ parentRow += `<td class="cell empty${sel?' sel':''}" onclick="bkV2SelectFamilyCell('${dateKey}','${fam.id}')">&mdash;</td>`; continue; }
      const intensity = bkV2CellIntensity(famData.total);
      const cls = ['cell', intensity, famData.hasFocPending?'foc':'', sel?'sel':'', famData.hasFocPending?'focdot':''].filter(Boolean).join(' ');
      parentRow += `<td class="${cls}" onclick="bkV2SelectFamilyCell('${dateKey}','${fam.id}')">${famData.total}</td>`;
      dayTotals[d-1] += famData.total;
    }
    let html = `<tr class="fam ${isExpanded?'expanded':''}">${parentRow}</tr>`;

    // Sub-routes (rendered when expanded)
    if(isExpanded){
      subRoutes.forEach(rDef => {
        let subRow = `<td class="rowh" title="${rDef.full}">${rDef.full}</td>`;
        for(let d = 1; d <= lastDay; d++){
          const dateKey = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
          const isOpen = bkV2IsRouteOpenOn(rDef.id, dateKey);
          const x = agg.byDate[dateKey];
          const r = x?.routes?.[rDef.id];
          if(!isOpen && !r){ subRow += `<td class="cell closed" title="Route closed">&times;</td>`; continue; }
          if(!r){ const eSel=(_bkV2.selected?.date===dateKey && _bkV2.selected?.routeId===rDef.id)?' sel':''; subRow += `<td class="cell empty${eSel}" onclick="bkV2SelectCell('${dateKey}','${rDef.id}')">&mdash;</td>`; continue; }
          const sel = _bkV2.selected?.date === dateKey && _bkV2.selected?.routeId === rDef.id;
          if(!isOpen){
            subRow += `<td class="cell closed-with-data ${sel?'sel':''}" onclick="bkV2SelectCell('${dateKey}','${rDef.id}')" title="Bookings on closed route">${r.total}</td>`;
            continue;
          }
          const cls = ['cell', bkV2CellIntensity(r.total), r.hasFocPending?'foc':'', sel?'sel':'', r.hasFocPending?'focdot':''].filter(Boolean).join(' ');
          subRow += `<td class="${cls}" onclick="bkV2SelectCell('${dateKey}','${rDef.id}')">${r.total}</td>`;
        }
        html += `<tr class="sub">${subRow}</tr>`;
      });
    }
    return html;
  }).join('');

  // Toolbar above matrix (expand/collapse all)
  const anyExpanded = _bkV2.expanded.size > 0;
  const toolbar = `<div class="bkv2-mx-toolbar"><span>${fams.length} programs &middot; ${bkV2Routes().length} variants</span><span style="margin-left:auto"></span><button onclick="bkV2ExpandAllFamilies()">Expand all</button>${anyExpanded?`<button onclick="bkV2CollapseAllFamilies()">Collapse all</button>`:''}</div>`;

  let totRow = `<td class="rowh">Day total</td>`;
  for(let d = 1; d <= lastDay; d++){
    const dateKey = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isToday = dateKey === todayKey;
    totRow += `<td class="${isToday?'today':''}">${dayTotals[d-1] || ''}</td>`;
  }

  // Colgroup enforces equal day column widths (works with table-layout:fixed)
  let colgroup = '<col class="label">';
  for(let d = 1; d <= lastDay; d++) colgroup += '<col class="day">';

  return `
    ${bkV2RenderStats()}
    ${bkV2RenderRouteAvgs()}
    <div class="bkv2-split">
      <div class="bkv2-mx">
        ${toolbar}
        <table>
          <colgroup>${colgroup}</colgroup>
          <thead><tr>${headers}</tr></thead>
          <tbody>
            ${rows}
            <tr class="tot">${totRow}</tr>
          </tbody>
        </table>
      </div>
      ${bkV2RenderSelDay()}
    </div>
    ${bkV2RenderFooterHints('mx')}
  `;
}

// ── Tab 1 · shared detail panel ──
function bkV2RenderDetailPanel(){
  const sel = _bkV2.selected;
  if(!sel){
    return `<div class="bkv2-detail" style="border-color:var(--border);background:var(--sand-mid);text-align:center"><div style="font-size:12px;color:var(--ink-soft);padding:14px 0">Click a cell to see breakdown &middot; AD &middot; CHD &middot; INF &middot; FOC + PK &middot; KL &middot; NT</div></div>`;
  }
  const agg = bkV2Aggregate();
  const x = agg.byDate[sel.date];
  if(!x){
    return `<div class="bkv2-detail" style="border-color:var(--border);background:var(--sand-mid);text-align:center"><div style="font-size:12px;color:var(--ink-soft);padding:14px 0">No bookings for ${bkV2FmtDate(sel.date)}</div></div>`;
  }
  const dt = new Date(sel.date + 'T00:00');
  const dateLbl = dt.toLocaleDateString('en-US', { weekday:'short', day:'2-digit', month:'short', year:'numeric' });
  const hasFoc = sel.routeId ? x.routes[sel.routeId]?.hasFocPending : x.hasFocPending;
  const subTitle = sel.routeId ? `${bkV2Route(sel.routeId)?.full || sel.routeId} &middot; ${dateLbl}` : `${dateLbl} &middot; all routes`;

  const fmtStats = r => `
    <div class="bkv2-detail-stats">
      <span><span class="lab">Total</span> <span class="val big">${r.total}</span></span>
      <span class="sep">|</span>
      <span><span class="lab">AD</span> ${r.ad} &middot; <span class="lab">CHD</span> ${r.chd} &middot; <span class="lab">INF</span> ${r.inf} &middot; ${r.foc?`<span class="lab" style="color:#ba7517">FOC</span> <span class="val foc">${r.foc}</span>`:`<span class="lab">FOC</span> 0`}</span>
      <span class="sep">|</span>
      <span><span class="lab">PK</span> ${r.pk} &middot; <span class="lab">KL</span> ${r.kl} &middot; <span class="lab">NT</span> ${r.nt}</span>
    </div>
  `;

  let rowsHtml;
  if(sel.routeId){
    const r = x.routes[sel.routeId];
    rowsHtml = `
      <div class="bkv2-detail-row first">
        <div class="bkv2-detail-rname">${bkV2Route(sel.routeId)?.full || sel.routeId}</div>
        ${fmtStats(r)}
      </div>
    `;
  } else {
    rowsHtml = bkV2Routes().map((rDef, i) => {
      const r = x.routes[rDef.id];
      if(!r) return `
        <div class="bkv2-detail-row ${i===0?'first':''}">
          <div class="bkv2-detail-rname muted">${rDef.full}</div>
          <div class="bkv2-detail-stats"><span style="color:var(--ink-soft);font-style:italic">no trip &middot; route closed</span></div>
        </div>
      `;
      return `
        <div class="bkv2-detail-row ${i===0?'first':''}">
          <div class="bkv2-detail-rname">${rDef.full}</div>
          ${fmtStats(r)}
        </div>
      `;
    }).join('');
  }

  return `
    <div class="bkv2-detail">
      <div class="bkv2-detail-hd">
        <div>
          <div class="bkv2-detail-lab">Selected</div>
          <div class="bkv2-detail-ttl">${subTitle}</div>
        </div>
        ${hasFoc ? `<div class="bkv2-detail-chip"><span class="dot"></span>FOC pending</div>` : ''}
        <button class="bkv2-detail-open" style="margin-left:auto" onclick="bkV2OpenFiltered('${sel.routeId||''}','${sel.date}')">Open ${sel.routeId?'bookings':"day's bookings"} &rarr;</button>
      </div>
      ${rowsHtml}
      <div class="bkv2-detail-foot">
        <div class="lab">Day total</div>
        <div class="stats">
          <span>Pax <span style="font-size:16px">${x.total}</span></span>
          <span class="sep">|</span>
          <span>Revenue &#3647;${bkV2FmtTHB(x.revenue)}</span>
          <span class="sep">|</span>
          <span>${x.bookings.length} booking${x.bookings.length===1?'':'s'}</span>
        </div>
      </div>
    </div>
  `;
}

function bkV2RenderFooterHints(viewMode){
  if(viewMode === 'cal'){
    // Calendar view: chips per route · no heatmap intensity · just FOC indicator + tip
    return `
      <div class="bkv2-foot-hints">
        <span class="bkv2-legend"><span class="sw focdot"></span>FOC pending</span>
        <span class="gp" style="color:var(--ink-soft);font-style:italic">Chips show pax per route &middot; click cell for AD&middot;CHD&middot;INF&middot;FOC + PK&middot;KL&middot;NT breakdown</span>
        <span style="margin-left:auto" class="gp"><span class="bkv2-kbd">M</span>switch to matrix</span>
      </div>
    `;
  }
  // Matrix view: keep heatmap legend
  return `
    <div class="bkv2-foot-hints">
      <span class="bkv2-legend"><span class="sw lo"></span>1&ndash;10 pax</span>
      <span class="bkv2-legend"><span class="sw mid"></span>11&ndash;24</span>
      <span class="bkv2-legend"><span class="sw hi"></span>25&ndash;50</span>
      <span class="bkv2-legend"><span class="sw peak"></span>51+</span>
      <span class="bkv2-legend"><span class="sw focdot"></span>FOC pending</span>
      <span style="margin-left:auto" class="gp"><span class="bkv2-kbd">M</span>back to calendar</span>
    </div>
  `;
}

// ── Tab 2 · By trip + date · Trip header + passenger manifest ──
// Pay method label: contract 'credit' -> Invoice, 'prepaid' -> PFM (prepaid full)
function bkV2PayLabel(m){
  if(!m) return '—';
  const map = { credit:'Invoice', invoice:'Invoice', prepaid:'PFM', proforma:'Proforma', bt:'Bank transfer', cot:'COT' };
  return map[m] || m;
}
function bkV2ZoneLabel(z){
  return ({ PK:'Phuket', KL:'Khao Lak', NoTransfer:'Own transportation', NT:'Own transportation' })[z] || z || 'Own transportation';
}
function bkV2ZoneOrder(z){ return ({ PK:0, KL:1, NoTransfer:2, NT:2 })[z] ?? 3; }
function bkV2ZoneColor(z){ return ({ PK:'#185FA5', KL:'#3B6D11', NoTransfer:'#8b909c', NT:'#8b909c' })[z] || '#8b909c'; }
// Boats assigned to a route on a date (from TRIPS ops) + any charter boats passed in
function bkV2Tab2Boats(routeId, dateStr, charterBoatIds){
  const names = [];
  const seen = new Set();
  const pushBoat = (bid)=>{ if(!bid || seen.has(bid)) return; seen.add(bid); const b=(typeof BOATS!=='undefined'?BOATS.find(x=>x.id===bid):null); names.push({id:bid, name:(b?b.name:bid)}); };
  try {
    const ops = (typeof TRIPS!=='undefined' && TRIPS[dateStr]) ? TRIPS[dateStr] : {};
    Object.entries(ops).forEach(([bid,op])=>{ if(op && op.route===routeId) pushBoat(bid); });
  } catch(e){}
  (charterBoatIds||[]).forEach(pushBoat);
  return names;
}
// Pick the active date for the view: explicit filter, else nearest trip date >= today, else today
function bkV2Tab2ActiveDate(){
  if(_bkV2.filterDate) return _bkV2.filterDate;
  const today = bkV2LocalYMD(new Date());
  const dates = new Set();
  SB_BOOKINGS.forEach(bk=>{
    if(bk.schemaVer===2){ (bk.trips||[]).forEach(t=>{ if(t.date) dates.add(t.date); }); }
    else if(bk.travelDate){ dates.add(bk.travelDate); }
  });
  const sorted = [...dates].sort();
  const upcoming = sorted.find(d => d >= today);
  return upcoming || sorted[sorted.length-1] || today;
}
// Format a Date as YYYY-MM-DD using LOCAL components (avoid UTC shift from toISOString in +07:00)
function bkV2LocalYMD(dt){ return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`; }
function bkV2Tab2DateShift(n){
  const cur = bkV2Tab2ActiveDate();
  const dt = new Date(cur + 'T00:00'); dt.setDate(dt.getDate() + n);
  _bkV2.filterDate = bkV2LocalYMD(dt);
  _bkV2.filterRoute = null;
  bkV2Render();
}
function bkV2Tab2Today(){ _bkV2.filterDate = bkV2LocalYMD(new Date()); _bkV2.filterRoute = null; bkV2Render(); }
function bkV2Tab2TogglePax(rowId){
  const el = document.getElementById(rowId);
  if(!el) return;
  const open = el.style.display === 'table-row';
  el.style.display = open ? 'none' : 'table-row';
  const ic = document.getElementById(rowId + '-ic');
  if(ic) ic.style.transform = open ? '' : 'rotate(180deg)';
}

