// §pax breakdown ต่อจุดรับ · เก็บ ad/chd/inf/foc แยกกัน แล้ว qty = ผลรวม (ของเดิมทั้งระบบยังอ่าน qty ได้เหมือนเดิม)
function bkV2SetAltPickupPax(i, key, val){
  if(!_bkV2.newBooking || !Array.isArray(_bkV2.newBooking.altPickups)) return;
  const a = _bkV2.newBooking.altPickups[i]; if(!a) return;
  if(PAX_K.indexOf(key)<0) return;
  PAX_K.forEach(k=>{ if(a[k]==null) a[k] = (k==='ad') ? Math.max(0,parseInt(a.qty)||0) : 0; });   // เลื่อนของเก่า (มีแต่ qty) ขึ้นมาก่อน
  a[key] = Math.max(0, parseInt(val)||0);
  a.qty  = bkPaxSum(bkAltPax(a));   // qty เป็นค่าที่คำนวณจาก 4 ช่อง ไม่ใช่ค่าที่พิมพ์เอง
  bkV2Render();
}
function bkV2SetAltPickupQty(i, val){
  // (ยังคงไว้เพื่อความเข้ากันได้) จำนวนคนที่จุดนี้ · clamp >=1 · re-render เพื่ออัปเดตสรุป "จุดรับหลัก"
  if(!_bkV2.newBooking || !Array.isArray(_bkV2.newBooking.altPickups)) return;
  const a = _bkV2.newBooking.altPickups[i]; if(!a) return;
  a.qty = Math.max(1, parseInt(val)||1);
  bkV2Render();
}
function bkV2RemoveAltPickup(i){
  if(!_bkV2.newBooking || !Array.isArray(_bkV2.newBooking.altPickups)) return;
  _bkV2.newBooking.altPickups.splice(i,1);
  // ลบจุดรับออกแล้ว split ที่สร้างไว้อัตโนมัติต้องยุบคืนด้วย — ไม่งั้นบุ๊กกิ้งยังถูกหั่นเป็นหลายก้อน
  // ทั้งที่ไม่มีจุดรับเพิ่มแล้ว (คนหายไปจากใบงาน) · bkV2SyncAltPickupSplits ยุบให้เองเมื่อ altPickups ว่าง
  const _id=_bkV2.newBooking.id;
  if(_id && typeof SB_BOOKINGS!=='undefined'){
    const b=SB_BOOKINGS.find(x=>x.id===_id);
    if(b){ b.altPickups = _bkV2.newBooking.altPickups.slice();
           if(typeof bkV2SyncAltPickupSplits==='function') bkV2SyncAltPickupSplits(b); }
  }
  bkV2Render();
}
