   + '.tb{width:100%;border-collapse:collapse;font-size:8pt}'
   + '.tb th{text-align:left;font-size:7pt;color:#8b9a94;font-weight:600;letter-spacing:.04em;border-bottom:0.4mm solid #d7d3ca;padding:2mm 1.5mm}'
