function bkV2OpenDetail(id){
  if(!id) return;
  _bkV2.detailId = id;
  bkV2Render();
  // scroll top
  try { document.querySelector('main')?.scrollTo({top:0,behavior:'instant'}); } catch(e){}
  window.scrollTo({top:0});
}
function bkV2CloseDetail(){
  _bkV2.detailId = null;
  bkV2Render();
}
function bkV2GetDetailBooking(){
  return SB_BOOKINGS.find(b => b.id === _bkV2.detailId) || null;
}
function bkV2FmtFullDate(d){
  if(!d) return '—';
  const dt = typeof d === 'string' ? new Date(d.length > 10 ? d : d + 'T00:00') : d;
  if(isNaN(dt)) return d;
  return dt.toLocaleDateString('en-GB', {weekday:'short', day:'2-digit', month:'short', year:'numeric'});
}
function bkV2FmtDateTime(d){
  if(!d) return '—';
  const dt = typeof d === 'string' ? new Date(d.length > 10 ? d : d + 'T00:00') : d;
  if(isNaN(dt)) return d;
  return dt.toLocaleDateString('en-GB', {day:'2-digit', month:'short', year:'numeric'}) + ' · ' +
         dt.toLocaleTimeString('en-GB', {hour:'2-digit', minute:'2-digit'});
}
