  return '#po-modal .pa-sec{border:1px solid #E1E4EA;border-radius:11px;margin-bottom:10px;overflow:hidden}'
   +'#po-modal .pa-sec .hd{display:flex;align-items:center;gap:8px;padding:8px 11px;background:#F2F5F9}'
   +"#po-modal .pa-sec .hd .nm{flex:1;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#20477E;font-size:11.5px}"
   +'#po-modal .pa-sec .hd .nm2{flex:1;font-weight:800;letter-spacing:.06em;color:#8B93A1;font-size:11.5px}'
   +"#po-modal .pa-sec .hd .n{font-size:10.5px;color:#8B93A1;font-family:'DM Mono',monospace}"
