   +'#po-modal .pa-sec .chip select{border:1px solid #E7EAEF;border-radius:6px;padding:3px 5px;font:600 10.5px inherit;color:#5A6472;background:#F7F8FA}'
   +'#po-modal .pa-sec .none{font-size:11.5px;color:#9AA3B0}'
