   +'#po-modal .pa-tick td.who b{font-size:11.5px;font-weight:600}'
   +'#po-modal .pa-tick td.who em{font-style:normal;font-size:10.5px;color:#8B93A1;margin-left:5px}'
   +'#po-modal .pa-tick td.who i{display:block;font-style:normal;font-size:10px;color:#A9B0BB;margin-top:1px}'
   +'#po-modal .pa-tick td.tk{width:82px;text-align:center;cursor:pointer}'
   +'#po-modal .pa-tick td.tk span{display:inline-flex;align-items:center;justify-content:center;width:21px;height:21px;'
